INSERT INTO `contents` (id, external_id, tmdb_id, created_at, updated_at, original_language, release_date, title, original_title, overview, poster_path, media_type) VALUES (1, NULL, 1306368, '2026-01-29 12:23:18', '2026-01-29 12:23:24', 'en', '2026-01-16', '더 립', 'The Rip', '허름한 은닉처에서 수백만 달러의 현금을 발견한 마이애미 경찰. 신뢰에 금이 가기 시작하면서 모든 사람, 모든 것이 의심의 대상이 된다.', 'https://image.tmdb.org/t/p/w500/o0d6Us9VWOW0nHhoB7ZNIwigARG.jpg', 'MOVIE'),(2, NULL, 1131759, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'ko', '2025-07-23', '전지적 독자 시점', '전지적 독자 시점', '10년 이상 연재된 소설이 완결된 날 소설 속 세계가 현실이 되어 버리고, 유일한 독자였던 ‘김독자’가 소설의 주인공 ‘유중혁’ 그리고 동료들과 함께 멸망한 세계에서 살아남기 위한 이야기.', 'https://image.tmdb.org/t/p/w500/lWQRM7IOCyJT9E5kOnoUvZNELHQ.jpg', 'MOVIE'),(3, NULL, 1137179, '2026-01-29 12:23:18', '2026-01-29 12:23:24', 'ko', '2025-04-16', '야당', '야당', '누명을 쓰고 교도소에 수감된 이강수는 검사 구관희로부터 감형을 조건으로 야당을 제안받는다. 강수는 관희의 야당이 돼 마약 수사를 뒤흔들기 시작하고, 출세에 대한 야심이 가득한 관희는 굵직한 실적을 올려 탄탄대로의 승진을 거듭한다.  한편, 마약수사대 형사 오상재는 수사 과정에서 강수의 야당질로 번번이 허탕을 치고, 끈질긴 집념으로 강수와 관희의 관계를 파고든다.  마약판을 설계하는 브로커 강수, 더 높은 곳에 오르려는 관희, 마약 범죄 소탕에 모든 것을 건 상재. 세 사람은 각자 다른 이해관계로 얽히기 시작하는데…', 'https://image.tmdb.org/t/p/w500/k4yTwFqvQDApqaoFdgubsbYcuno.jpg', 'MOVIE'),(6, NULL, 198663, '2026-01-29 12:23:18', '2026-01-29 12:23:24', 'en', '2014-09-18', '메이즈 러너', 'The Maze Runner', '삭제된 기억, 거대한 미로로 둘러싸인 낯선 공간  모든 기억이 삭제된 채 의문의 장소로 보내진 토마스. 토마스는 미로에 갇힌 그곳에서 자신과 같은 상황의 사람들을 만난다. 그들은 매일 밤 살아 움직이는 미로에서 정체를 알 수 없는 죽음의 존재와 대립하며, 지옥으로부터 빠져나갈 탈출구인 지도를 완성해 나간다. 그러던 어느 날, 미로의 문이 열리고 그들은 마지막 선택의 기로에 놓이게 되는데…', 'https://image.tmdb.org/t/p/w500/bL0bBepUCLFcCj2ATFD40FbyDEl.jpg', 'MOVIE'),(7, NULL, 912649, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2024-10-23', '베놈: 라스트 댄스', 'Venom: The Last Dance', '환상의 케미스트리의 에디 브록과 그의 심비오트 베놈은 그들을 노리는 정체불명 존재의 추격을 피해 같이 도망을 다니게 된다. 한편 베놈의 창조자 널은 고향 행성에서부터 그들을 찾아내기 위해 지구를 침략하고 에디와 베놈은 그동안 겪어보지 못한 최악의 위기를 맞이하게 되는데…', 'https://image.tmdb.org/t/p/w500/ptfoRD0MmL8Ry0iBVccYbqoN9Xc.jpg', 'MOVIE'),(8, NULL, 793387, '2026-01-29 12:23:18', '2026-01-29 12:23:24', 'ko', '2025-04-30', '거룩한 밤: 데몬 헌터스', '거룩한 밤: 데몬 헌터스', '악마와 그를 쫓는 어둠의 숭배자들로 인해 혼란에 빠지게 된 도시. 공권력조차 이들 앞에서 무력해지자 특별한 능력을 가진 어둠의 해결사 거룩한 밤 팀 바우, 샤론, 김군이 직접 악의 무리를 처단하고자 한다. 그러던 중 갑자기 동생 은서가 이상증세를 보인다는 의뢰인 정원이 찾아오고 그 안에서 지금껏 본 적 없던 강력한 존재의 기운을 느끼는데… 과연 거룩한 밤 팀은 악의 무리에 맞서 세상을 구원해 낼 수 있을까?', 'https://image.tmdb.org/t/p/w500/7MGnHpfhF8savUsrUJoI8Q7dTk9.jpg', 'MOVIE'),(9, NULL, 156022, '2026-01-29 12:23:18', '2026-01-29 12:23:24', 'en', '2015-01-28', '더 이퀄라이저', 'The Equalizer', '새벽 2시만 되면 어김없이 잠에서 깨는 로버트 맥콜. 불면증으로 잠 못 드는 이 시간이면 그는 늘 책 한 권을 들고 카페로 향한다. 가족도 친구도 없는 그는 아내가 남기고 간 ‘죽기 전에 읽어야 할 소설 100권’을 모두 읽는 것이 유일한 삶의 목표다. 그런 그에게 어느 날, 어린 콜걸 테리가 말을 건넨다. 무료하게 전화를 기다리다 벨이 울리면 대기하고 있던 리무진에 오르는 테리와 매일 같은 공간에서 같은 시간을 공유하던 로버트는 묘한 동질감을 느끼며 가까워진다. 그러던 어느 날, 테리가 포주인 러시아 마피아에게 무자비하게 폭행을 당한 채로 발견되자 세상을 향한 분노가 폭발하고만 로버트는 마침내, 강자에겐 약하고 약자에겐 한없이 강한 이 세상을 향해 스스로 심판자가 되기로 결심하는데...', 'https://image.tmdb.org/t/p/w500/hqes9NQtVIULs8VKu0WqY6RdXGU.jpg', 'MOVIE'),(10, NULL, 512195, '2026-01-29 12:23:18', '2026-01-29 12:23:23', 'en', '2021-11-12', '레드 노티스', 'Red Notice', '인터폴이 중범죄 피의자를 대상으로 내리는 전 세계적 경보인 레드 노티스. 세계 곳곳에서 지명 수배범을 추적하고 체포하는 것이 그 목적이다. 어느 날 초유의 도난 사건이 발생하고, 그로 인해 FBI 최고의 프로파일러(드웨인 존슨)가 라이벌 관계의 두 범죄자(갤 가돗, 라이언 레이놀즈)와 만나면서 모든 게 엇나가기 시작한다. 늘 한발 앞서 도망치는 사기꾼을 잡기 위해 그들은 어쩔 수 없이 싫어도 이를 악물고 힘을 합쳐야 한다. 이제 무슨 일이 일어날지 그 누구도 장담할 수 없다.', 'https://image.tmdb.org/t/p/w500/gG06Uu6UQseYaPx1RU2PQjFEUKK.jpg', 'MOVIE'),(11, NULL, 98, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2000-06-03', '글래디에이터', 'Gladiator', '죽을 날이 머지않은 황제 마르쿠스 아우렐리우스는 막시무스를 총애하여 아들이 아닌 그에게 권력을 넘겨주기로 한다. 황제의 아들 코모두스는 이에 질투와 분노를 느껴 황제를 살해한다. 왕좌를 이어받은 코모두스는 막시무스와 그의 가족을 죽이라고 명령한다. 가족을 모두 잃고 겨우 살아남은 막시무스는 노예로 전락하고, 투기장의 검투사가 된다. 그에게 남은 건 오직 황제 코모두스에 대한 복수 뿐. 검투사로서 매 경기마다 승리로 이끌면서 살아남자 그의 명성은 날로 높아 간다. 그러던 어느 날 오래 전 사랑했던 황제의 누이 루실라를 다시 만나게 되는데...', 'https://image.tmdb.org/t/p/w500/yemF0xxGU56Pf3JXxVr4C6kuKng.jpg', 'MOVIE'),(12, NULL, 949, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '1996-08-10', '히트', 'Heat', '닐 맥컬리(로버트 드 니로)는 빈틈없고 치밀하게 일을 처리하는 프로 범죄자지만 따뜻한 가정의 온기를 동경한다. 반면 LA 경찰국 강력계 수사반장인 빈센트 한나(알 파치노)는 두 번의 이혼 경력에 이어 세 번째 결혼마저 위기를 맞은 불안정한 사생활의 소유자지만, 일에 있어서는 굶주린 짐승처럼 집요하게 쫓아가 결국에는 해결을 보고 만다. 닐과 그의 동료들이 특급우편 발송 차량을 습격하는 대규모 도난 사건을 일으켜 증권 투자사 간부의 고액 채권을 강탈한다. 사건 발생 직후부터 빈센트는 예리한 추리력으로 한걸음씩 닐에게 접근해간다. 닐 역시 빈센트의 추격을 눈치채는데...', 'https://image.tmdb.org/t/p/w500/p0uAcyDgBXtCSXZdnacwr9OGcIH.jpg', 'MOVIE'),(13, NULL, 1930, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2012-06-28', '어메이징 스파이더맨', 'The Amazing Spider-Man', '어릴적 사라진 부모 대신 삼촌 내외와 살고 있는 피터 파커는 평범한 학교 생활을 하며 일상을 보내고, 같은 학교 학생 그웬 스테이시와 첫사랑에 빠져 우정과 사랑, 그리고 둘 만의 비밀을 키워나간다. 어느 날 아버지가 사용했던 가방을 발견하고 부모님의 실종사건에 대한 의심을 품게 된 그는 숨겨져 왔던 과거의 비밀을 추적하게 된다. 아버지의 옛 동료 코너스 박사의 실험실을 찾아가게 된 피터는 우연한 사고로 특별한 능력을 갖게 되고, 피터의 도움으로 연구를 완성한 코너스 박사는 자신의 숨겨진 자아인 악당 리자드를 탄생시키는데...', 'https://image.tmdb.org/t/p/w500/a1Kup5VnmxjAHnsT3Sz7RtrC9UU.jpg', 'MOVIE'),(14, NULL, 539972, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2025-03-12', '크레이븐 더 헌터', 'Kraven the Hunter', '죽음의 문턱에서 맹수의 초인적인 힘을 얻고 살아 돌아온 크레이븐이 무자비한 복수의 길을 택하며 거침없는 사냥을 펼치는 액션 블록버스터', 'https://image.tmdb.org/t/p/w500/gYOhHBHSqb3J0QaZWlKYDbpxY7Y.jpg', 'MOVIE'),(16, NULL, 24, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2003-11-21', '킬 빌: 1부', 'Kill Bill: Vol. 1', '어느 한적한 오후, 행복한 결혼식을 앞둔 더 브라이드와 그녀의 신랑, 그리고 모든 하객들이 의문의 조직에 의해 처참하게 살해당한다. 그로부터 5년 후, 코마상태의 더 브라이드는 죽음 직전까지 갔다가 어렵게 깨어난다. 그리고 피로 얼룩진 과거가 그녀의 뇌리에 스치면서 서서히 복수의 리스트를 작성하기 시작한다. 그녀는 전세계적으로 악명높은 살인조직 데들리 바이퍼의 일원이었고, 조직의 보스인 빌을 포함한 5명의 일원이 새로운 삶을 앞둔 그녀를 처참하게 무너뜨렸음이 밝혀지자, 그녀는 텍사스, 멕시코, 일본을 방문하며 가장 잔인한 복수를 실행하게 되는데...', 'https://image.tmdb.org/t/p/w500/lH82lk837fACeVZUmqHH0UiEeWL.jpg', 'MOVIE'),(17, NULL, 670, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'ko', '2003-11-21', '올드보이', '올드보이', '오대수는 어느 날 술이 거나하게 취해 집에 돌아가는 길에 누군가에게 납치, 사설 감금방에 갇히게 된다. 중국집 군만두만을 먹으며 8평이라는 제한된 공간에서 그가 할 수 있는 일이라곤 텔레비전 보는 게 전부. 1년이 지났을 무렵, 뉴스를 통해 나오는 아내의 살해소식. 게다가 아내의 살인범으로 자신이 지목되고 있음을 알게 된 오대수는 복수와 탈출을 위해 감금방 한쪽 구석을 쇠젓가락으로 파기 시작한다. 감금 15년을 맞이하는 해, 마침내 사람 몸 하나 빠져나갈 만큼의 탈출구가 생겼을 때, 어이없게도 15년 전 납치됐던 바로 그 장소로 풀려나 있는 자신을 발견하게 된다.', 'https://image.tmdb.org/t/p/w500/xpa9ybm6tYGna5LseqSXvKpSSJn.jpg', 'MOVIE'),(18, NULL, 82702, '2026-01-29 12:23:18', '2026-01-29 12:23:26', 'en', '2014-07-24', '드래곤 길들이기 2', 'How to Train Your Dragon 2', '바이킹과 드래곤이 친구가 되어 평화롭게 살아가는 버크섬.  청년이 된 히컵은 아버지 스토이크의 바람과는 달리  족장이 되는 것 보다 버크섬 밖의 더 넓은 세상을 보고 싶어한다.  그러던 어느 날, 신비로운 얼음대륙을 탐험하던 히컵과 투슬리스는 드래곤 사냥꾼들이 쳐놓은 덫에 걸리고,  드래곤들을 위협하는 강력한 어둠의 존재에 대해 알게 된다.  히컵과 투슬리스는 드래곤들의 평화를 위해  의문의 드래곤 군단과 맞서기로 결심하는데…', 'https://image.tmdb.org/t/p/w500/kSP4QmHMLnbySksUb2O9sGkoEQM.jpg', 'MOVIE'),(19, NULL, 545611, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2022-10-12', '에브리씽 에브리웨어 올 앳 원스', 'Everything Everywhere All at Once', '남편과 세탁소를 운영하며 근근히 살아가고 있는 이민자 이블린 왕. 20대 시절 남편과 순수한 사랑을 불태우며 모든 것을 뒤로 하고 미국으로 이민을 떠났지만, 50대가 된 지금은 세탁소 운영 등 온갖 일로 허덕이며 단란했던 가족과도 삐그덕거리는 등 고달프게 살고 있다. 세무조사를 받던 중 자신이 멀티버스의 여러 다른 자신들과 연결되어 있음을 알게 되고, 강력한 악의 기운으로부터 모든 우주와 가족을 구해내기 위한 모험에 나서게 되는데...', 'https://image.tmdb.org/t/p/w500/dd29Kt2p2voyP2sB6p3jC36A7ce.jpg', 'MOVIE'),(20, NULL, 351286, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2018-06-06', '쥬라기 월드: 폴른 킹덤', 'Jurassic World: Fallen Kingdom', '지상 최대의 테마파크 쥬라기 월드가 폐쇄된 지 3년 후.  이슬라 누블라의 활화산 시보산이 분화하려는 조짐을 보이자 조짐에 뉴스에서는 이와 더불어 공룡들의 보호에 관련된 시위나 소식들을 보도한다. 오웬(크리스 프렛)과 클레어(브라이스 달라스 하워드)는 벤자민 록우드(제임스 크롬웰)의 부탁으로 공룡들의 멸종을 막기 위해 이슬라 누블라 섬으로 떠난다. 한편 진화된 공룡들을 이용하려는 세력의 거대한 음모가 드러나고, 절대 지상에 존재해선 안될 위협적 공룡들이 마침내 세상 밖으로 등장하게 되는데...', 'https://image.tmdb.org/t/p/w500/xR2VgpNxElFOJBul0q7ULiT0ayF.jpg', 'MOVIE'),(22, NULL, 763215, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2024-03-08', '댐즐', 'Damsel', '매력적인 왕자와 결혼하게 된 젊은 여성. 그런데 신부가 아니라 불을 내뿜는 용에게 바칠 제물이 되면서, 꿈꿔왔던 결혼이 순식간에 치열한 생존 싸움으로 변한다.', 'https://image.tmdb.org/t/p/w500/nhH6M1JTcNJfbhvdrCsSrCB6PFZ.jpg', 'MOVIE'),(24, NULL, 135397, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2015-06-11', '쥬라기 월드', 'Jurassic World', '쥬라기 공원 사건에서 22년이 지난 후, 이슬라 누블라에서는 새로 열린 쥬라기 공원이 정상적으로 영업 중이다. 유전자 조작으로 탄생한 공룡들을 앞세운 쥬라기 월드는 지상 최대의 테마파크로 자리잡는다. 하지만 유전공학자들이 그 동안의 연구를 바탕으로 탄생시킨 새로운 유전자 조작 하이브리드 공룡들은 지능과 공격성을 끝없이 진화시키며 인간의 통제를 벗어날 조짐을 보인다. 한편 오랫동안 벨로시랩터를 연구해온 오웬 그래디(크리스 프랫)는 이런 시도에 반대하고, 그가 예상한 대로 이 하이브리드 공룡이 탈출하면서 공원은 아수라장이 되는데...', 'https://image.tmdb.org/t/p/w500/zJ5pZvsd5I8HYnRRAvLE2tSxtOW.jpg', 'MOVIE'),(25, NULL, 102382, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2014-04-23', '어메이징 스파이더맨 2', 'The Amazing Spider-Man 2', '스파이더맨의 삶에 완전히 적응한 피터 파커는 거미줄로 뉴욕을 활강하며 위험에 처한 시민들을 구해주고 사랑하는 연인 그웬과 데이트를 즐기며 행복하게 살아간다. 그러던 어느 날, 스파이더맨의 열렬한 팬이자 오스코프사의 전기 엔지니어인 맥스는 작업 중 치명적인 사고로 자신에게 엄청난 능력이 생긴 것을 발견한다. 하지만 이 능력으로 인해 뉴욕을 마비시킨 대규모 정전사태가 발생하고 사태를 해결하기 위해 나선 자신의 영웅 스파이더맨에게 공격을 당하자 배신감을 느끼고 분노하는데...', 'https://image.tmdb.org/t/p/w500/eYaFLrKuEdzrGw6XG5ZTVciH28v.jpg', 'MOVIE'),(26, NULL, 1267319, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'ko', '2025-09-26', '사마귀', '사마귀', '하룻밤 사이 몰락한 청부살인 업계의 거물들. 그들이 세운 질서가 무너지고, 어둠의 세계가 흔들린다. 혼돈 속에서 기회를 노리는 실력자 \'사마귀\'. 그의 손끝에서 새로운 킬러들의 시대가 열린다.', 'https://image.tmdb.org/t/p/w500/gRPSu4sG5iVnWyLv9um7t3L0yhH.jpg', 'MOVIE'),(27, NULL, 744, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '1987-12-09', '탑건', 'Top Gun', '해군 최신예 전투기인 F-14기를 모는 젊은 조종사 매버릭 대위는 훌륭한 전투기 조종사였던 아버지를 둔 패기만만한 파일럿 청년. 솜씨가 거칠기로 소문난 그는 탑 건 훈련학교에 입학하면서 인생의 전환을 맞게 된다. 가장 큰 변화는 항공물리학을 강의하는 여교관 찰리와 사랑에 빠진 것. 하지만 매버릭이 조종하던 F-14 전투기가 비행 훈련 도중 그만 제트 기류에 빠지면서 엔진 고장을 일으키고, 이때 함께 탈출을 시도하던 구즈가 사망하는 사고가 발생하고 마는데...', 'https://image.tmdb.org/t/p/w500/oqn0k8FbQ5mKXk5WbtKrvHwV5yV.jpg', 'MOVIE'),(28, NULL, 273481, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2015-12-03', '시카리오:  암살자의 도시', 'Sicario', '미국과 멕시코의 국경지역 후아레즈는 멕시코 최대 마약조직의 본거지이자 온갖 범죄의 온상지. FBI 요원 케이트는 어린이 납치사건을 수사하다가 멕시코 마약 조직의 정체를 알게 되고 CIA가 계획하는 마약 조직 소탕 작전에 자원한다. 그녀는 그곳에서 작전을 이끄는 책임자 맷과 멕시코 검사 출신의 알레한드로를 만난다. 작전이 전개되면서 수사는 법의 테두리를 넘지 말아야 한다는 케이트의 정의와 원칙은 수단과 방법을 가리지 않고 임무를 완수하려는 맷과 개인적인 복수를 위해 작전에 개입한 알레한드로 때문에 흔들리는데...', 'https://image.tmdb.org/t/p/w500/oVA4Rx01OUAYdLOiBNBPjaG7I7v.jpg', 'MOVIE'),(30, NULL, 458156, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2019-06-26', '존 윅 3: 파라벨룸', 'John Wick: Chapter 3 - Parabellum', '사랑하는 아내와 반려견이 죽은 후 복수를 위해 돌아온 전설의 킬러, 존 윅은 성역 콘티넨탈 호텔에서는 살인하면 안 된다는 룰을 깨면서 전세계 킬러들의 표적이 된다. 전편에서 존 윅이 국제암살자연맹에서 파문당한 직후 1시간 동안 도망갈 시간을 내어 준 윈스턴은 최고회의로부터 그를 도왔다는 이유로 자리에서 물러날 것을 요구받는다. 현상금이 1400만달러로 불어난 존 윅은 옛 동료이자 현재 카사블랑카 콘티넨탈 호텔의 지점장인 소피아에게 도움을 청한다.', 'https://image.tmdb.org/t/p/w500/8dGCWRwrMjn1jdFCI5xu5VrkGBL.jpg', 'MOVIE'),(31, NULL, 384018, '2026-01-29 12:23:18', '2026-01-29 12:23:23', 'en', '2019-08-14', '분노의 질주: 홉스 & 쇼', 'Fast & Furious Presents: Hobbs & Shaw', '이상한 약물에 의해 강력한 파워를 얻게 된 아나키스트 브릭스턴 로어는 인류를 천천히, 그리고 영원히 다른 존재로 바꿔버릴 수 있는 생화학무기를 손에 넣고 자신은 진화형 인간이 된다. 그런데 데카드 쇼의 동생이자 M16 요원인 해티 쇼가 치명적인 병원균이 들어 있는 실린더를 브릭스턴의 손에서 훔쳐 달아난다. 양국으로부터 해티의 행방을 찾아달라는 명령을 받은 루크와 데카드는 유전자 조작으로 사실상 파괴 불가능한 존재가 되어버린 브릭스턴을 상대로 힘겨운 싸움도 이겨나가야 하는데...', 'https://image.tmdb.org/t/p/w500/8MdVJYHKp7JFvTMkLkZOou13LYV.jpg', 'MOVIE'),(32, NULL, 87101, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2015-07-02', '터미네이터 제니시스', 'Terminator Genisys', '인간 저항군의 리더 존 코너의 탄생을 막기 위해 스카이넷은 터미네이터를 과거로 보내고, 이를 저지하기 위해 부하 카일 리스가 뒤를 따른다. 젊은 사라 코너와 그녀를 보호하고 있던 T-800은 로봇과의 전쟁을 준비하며 이미 그들을 기다리고 있었다. 시간의 균열로 존 코너 역시 과거로 오지만 그는 나노 터미네이터 T-3000으로 변해있었던 것. 이제 인류는 인간도 기계도 아닌 그 이상의 초월적인 존재, 사상 최강의 적에 맞서 전쟁을 벌여야만 한다.', 'https://image.tmdb.org/t/p/w500/bzcw6IyAbX3DbXrzPXx7ZgLXalr.jpg', 'MOVIE'),(33, NULL, 168259, '2026-01-29 12:23:18', '2026-01-29 12:23:25', 'en', '2015-04-01', '분노의 질주: 더 세븐', 'Furious 7', '도미닉과 멤버들은 범죄조직 소탕 후 모든 전과를 사면 받고 평범한 일상으로 돌아간다. 하지만 평화도 잠시, 전작에서 처리한 범죄조직의 리더 오웬 쇼의 형 데카드 쇼가 동생의 복수를 위해 멤버들을 차례로 공격한다. 특수부대 출신 용병 데카드 쇼의 난입으로 한이 갑작스레 사망하게 되고, 도미닉의 집은 순식간에 폭파당한다. 이에 맞서는 정부요원 페티는 도미닉을 돕는 조건으로 납치당한 해커 램지의 구출을 의뢰하고, 도미닉은 멤버들을 다시 모아 숨막히는 반격을 시작한다.', 'https://image.tmdb.org/t/p/w500/cuQdgDYANbKA46e4va2fz6fODkc.jpg', 'MOVIE'),(34, NULL, 335983, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2018-10-03', '베놈', 'Venom', '진실을 위해서라면 몸을 사리지 않고 사회의 부조리를 취재하는 정의로운 열혈 기자 에디 브록. 거대 기업 라이프 파운데이션의 생체실험에 의혹을 품고 뒤를 쫓던 그는 이들의 사무실에 잠입했다가 실험실에서 외계 생물체 심비오트의 기습 공격을 받게 된다. 심비오트가 숙주의 몸과 정신을 지배할 때 능력을 발휘하는 베놈은 에디의 몸에 기생하며 갖가지 소동을 일으킨다. 한편 비밀리에 인간과 심비오트를 결합해 새로운 생명체를 만들려는 시도를 계속하던 라이프 파운데이션의 회장 드레이크 또한 심비오트의 숙주가 된다.', 'https://image.tmdb.org/t/p/w500/x4ojC59pYfPlAP4mmy2LSkCCuK2.jpg', 'MOVIE'),(35, NULL, 615677, '2026-01-29 12:23:18', '2026-01-29 12:23:23', 'en', '2020-12-25', '오늘부터 히어로', 'We Can Be Heroes', '지구의 슈퍼히어로들이 외계인에게 납치된다. 부모님도 구하고 이 세상도 구해야 하는 그 2세들. 하지만 이대로는 안 되겠어. 힘을 모아 함께 싸우는 법부터 배워야지.', 'https://image.tmdb.org/t/p/w500/kEsaGfkZeoBbiEXlm6pMk4zEkI1.jpg', 'MOVIE'),(37, NULL, 339403, '2026-01-29 12:23:18', '2026-01-29 12:23:18', 'en', '2017-09-13', '베이비 드라이버', 'Baby Driver', '베이비는 탈출 전문 드라이버다. 은행 강도 등 범죄의 설계자인 박사에게 약점이 잡혀 일을 하고 있지만 손을 씻고 새로운 생활을 꿈꾼다. 어린 시절 교통사고를 당해 청력에 이상이 생긴 베이비는 이어폰을 끼고 음악을 들으며 안정을 유지한다. 어느 날 자주 가는 식당에서 종업원인 데보라를 만나 마음을 나누는 베이비. 하지만 마지막인 줄 알았던 범죄는 그의 발목을 놓아주지 않고 배츠, 버디, 달링과 함께 최후의 한탕을 준비한다.', 'https://image.tmdb.org/t/p/w500/fUfZ2zECULlN0pGPgXkez5rF7Hj.jpg', 'MOVIE'),(39, NULL, 336843, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2018-01-17', '메이즈 러너: 데스 큐어', 'Maze Runner: The Death Cure', '미스터리한 조직 ‘위키드’에게 잡힌 ‘민호’(이기홍)를 구하기 위해  ‘토마스’(딜런 오브라이언)와 러너들은 ‘위키드’의 본부가 있는 최후의 도시로 향한다.  인류의 운명이 걸린 ‘위키드’의 위험한 계획을 알게 된  ‘토마스’와 러너들은 마지막 사투를 준비하지만,  ‘토마스’는 친구와 인류의 운명 앞에서 딜레마에 빠지게 되는데…', 'https://image.tmdb.org/t/p/w500/xTOZbj6y3sTa83YH1dx82Ev7VlA.jpg', 'MOVIE'),(40, NULL, 110415, '2026-01-29 12:23:19', '2026-01-29 12:23:19', 'ko', '2013-08-01', '설국열차', '설국열차', '기상 이변으로 모든 것이 꽁꽁 얼어붙은 지구, 살아남은 사람들을 태운 기차 한 대가 끝없이 궤도를 달리고 있다. 춥고 배고픈 사람들이 바글대는 빈민굴 같은 꼬리칸, 그리고 선택된 사람들이 술과 마약까지 즐기며 호화로운 객실을 뒹굴고 있는 앞쪽칸. 열차 안의 세상은 결코 평등하지 않다. 기차가 달리기 시작한 17년째, 꼬리칸의 젊은 지도자 커티스는 긴 세월 준비해 온 폭동을 일으킨다. 기차의 심장인 엔진을 장악하고 기차 전체를 해방시키기 위해 절대권력자 윌포드가 도사리고 있는 엔진 칸을 향해 질주하는 커티스와 꼬리칸 사람들. 그들 앞에 예기치 못한 상황들이 기다리고 있는데...', 'https://image.tmdb.org/t/p/w500/jw66dQvYyXkZNA0bJ7nKvua9jDr.jpg', 'MOVIE'),(41, NULL, 299054, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2023-10-18', '익스펜더블 4', 'Expend4bles', '테러 단체에게 핵미사일이 탈취되어 3차 세계대전이 발발할 위기의 상황에 ‘리’(제이슨 스타뎀)를 새로운 리더로 맞은 무적의 팀 익스펜더블이 작전에 투입되는데...', 'https://image.tmdb.org/t/p/w500/dWR8OTRCcYDbBmd8GKsyJT73kU2.jpg', 'MOVIE'),(42, NULL, 777443, '2026-01-29 12:23:19', '2026-01-29 12:23:19', 'en', '2025-03-14', '일렉트릭 스테이트', 'The Electric State', '고아가 된 10대 소녀. 오래전 잃어버린 남동생을 찾아 미스터리한 로봇과 함께 길을 떠나는데. 그 여정에서 한 밀수꾼과 그의 재치 있는 조수를 만나 동행이 된다.', 'https://image.tmdb.org/t/p/w500/ol1oW2eVDHvU1yp30wCHfdY24ei.jpg', 'MOVIE'),(43, NULL, 846422, '2026-01-29 12:23:19', '2026-01-29 12:23:19', 'en', '2025-07-02', '올드 가드 2', 'The Old Guard 2', '새롭게 결의를 다지며 돌아온 앤디와 불멸의 전사들. 인류 수호의 사명을 위협하는 새로운 강적에 맞서 또 한 번 치열한 싸움에 돌입한다.', 'https://image.tmdb.org/t/p/w500/8UualSlMf7Tk1vHEOzHaQrjbUKC.jpg', 'MOVIE'),(45, NULL, 799379, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'ko', '2022-09-21', '늑대사냥', '늑대사냥', '동남아시아로 도피한 인터폴 수배자들을 이송할 움직이는 교도소 프론티어 타이탄. 극악무도한 이들과 베테랑 형사들이 필리핀 마닐라 항구에 모이고 탈출을 꿈꾸는 종두, 한국으로 돌아가야만 하는 도일을 비롯해 이들은 각자의 목적과 경계심을 품고 탑승한다. 한국으로 향하던 중, 태평양 한 가운데에서 이들에게는 지금까지 보지 못한 극한의 상황과 마주하게 되는데…', 'https://image.tmdb.org/t/p/w500/op2y1gvqKhAh4yAPLwc4PlX3XRv.jpg', 'MOVIE'),(46, NULL, 454626, '2026-01-29 12:23:19', '2026-01-29 12:23:23', 'en', '2020-02-12', '수퍼 소닉', 'Sonic the Hedgehog', '소리보다 빠른 초고속 고슴도치 히어로 \'소닉\'은 지구에 불시착한다. 그의 특별한 능력을 감지한 과학자 ‘닥터 로보트닉’은 세계 정복의 야욕을 채우려 하고, 경찰관 ‘톰’은 위험에 빠진 ‘소닉’을 돕기 위해 나서는데…! 과연, ‘소닉\'은 천재 악당에 맞서 지구를 지킬 수 있을까?', 'https://image.tmdb.org/t/p/w500/bhGOIk6lVNVDx082NDB2OlrjjWO.jpg', 'MOVIE'),(48, NULL, 343611, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2016-11-30', '잭 리처: 네버 고 백', 'Jack Reacher: Never Go Back', '군사 스파이 혐의로 자신의 후임인 수잔 터너 소령이 체포되자  잭 리처만이 그녀의 무죄를 확신하고 탈출을 돕는다. 사건의 진실을 파헤치던 중 관련된 사람들이 잇따라 살해 당하기 시작하고  잭 리처는 이 모든 사건의 배후에 누군가가 존재한다는 것을 알게 되는데...', 'https://image.tmdb.org/t/p/w500/jIhdOizM2SOiNzOU6jgiC9t3Qjc.jpg', 'MOVIE'),(49, NULL, 393, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2004-05-14', '킬 빌: 2부', 'Kill Bill: Vol. 2', '악명높은 데들리 바이퍼의 최고 암살단원 더 브라이드는 임신 사실을 알고 태어날 아이를 위해 피묻은 과거를 청산하고자 한다. 동료들의 눈을 피해 평범한 남자와 결혼식을 올리려는 찰나, 다섯명의 데들리 바이퍼가 그녀를 찾아와 총알세례를 퍼부었다. 5년간의 혼수상태에서 깨어난 더 브라이드는 아이가 죽었다는 사실에 분노의 눈물을 흘리고 복수를 맹세한다. 버니타 그린과 오렌 이시이를 처치한 그녀에게 이제 버드와 엘, 그리고 최종목표인 빌 이렇게 셋이 남았다. 그런데 죽은 줄 알았던 자신의 딸이 살아있다는 소식을 접하게 되고...', 'https://image.tmdb.org/t/p/w500/cSTDycUJuSSUd2QgmpmjUDrW69g.jpg', 'MOVIE'),(50, NULL, 919207, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'ko', '2023-11-22', '서울의 봄', '서울의 봄', '박 대통령의 암살 이후, 계엄령이 선포된다. 국군보안사령관 전두광과 그를 따르는 장교들에 의해 쿠데타가 일어나고 군대가 정치적 행동을 해선 안된다고 믿는 완고한 군인인, 수도방위사령관 이태신은 전두광을 막기 위해 그와 맞서기로 한다. 그들의 갈등이 점차 심화되고, 대혼란 속에서 모두가 갈망하던 서울의 봄은 예상치 못한 방향으로 흘러간다.', 'https://image.tmdb.org/t/p/w500/ukVVnY9ovwl78WE5KndcpA6SnAm.jpg', 'MOVIE'),(51, NULL, 758009, '2026-01-29 12:23:19', '2026-01-29 12:23:23', 'en', '2023-03-29', '샷건 웨딩', 'Shotgun Wedding', '‘다아시’(제니퍼 로페즈)와 ‘톰’(조쉬 더하멜)의 결혼식 당일, 우여곡절 끝에 결혼식에 참석할 모두가 섬에 모인다. 모든 게 순조로워 보이던 그때!  갑자기 들이닥친 해적으로 인해 결혼식장의 모두가 인질이 되고… ‘다아시’와 ‘톰’은 무사히 혼인서약을 마치기 위해 목숨을 건 버진 로드를 걷게 되는데…  죽이든가, 죽든가! 2023년 3월, 가장 화X한 웨딩이 온다!', 'https://image.tmdb.org/t/p/w500/aGhII6CTTvpZwnElzAUB7ZbgjTN.jpg', 'MOVIE'),(53, NULL, 668489, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2025-04-25', '해벅', 'Havoc', '마약 절도 사건이 통제 불능으로 치닫는 상황. 지칠 대로 지친 경찰이 정치가의 아들을 구하기 위해 부패한 도시의 지하 범죄 세계와 싸우며 길을 헤쳐 나간다.', 'https://image.tmdb.org/t/p/w500/oYUJsUlH0aoTNiKWJ78LD0cUVov.jpg', 'MOVIE'),(55, NULL, 4442, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2005-11-17', '그림 형제 : 마르바덴 숲의 전설', 'The Brothers Grimm', '때는 19세기 프랑스. 전국을 돌아다니며 괴물들과 악귀들을 퇴치해 준다는 명목으로 돈벌이를 하는 ‘사기꾼 퇴마사’ 형제 윌(맷 데이먼) 그림과 제이크(히스 레저) 그림. 프랑스 정부는 이들 형제의 어설픈 사기행각을 눈치채게 되고, 그림형제는 목숨을 건지기 위해 정부와 협상을 한다.  정부는 그림형제를 알 수 없는 이유로 처녀들이 연이어 사라지는 정령이 깃든 마법의 숲, ‘마르바덴’으로 이들을 보내버린다. 그 곳에서 살아남기 위해서 그림형제는 소녀들을 구해야만 한다. 마법의 숲 마르바덴에 도착한 두 형제. 미스터리로 가득찬 숲 속에서, 전설에 둘러싸인 ‘거울여왕’(모니카 벨루치)과 맞닥뜨리게 된다. 라푼젤 성에 잠들어 있는 거울 여왕과 그녀의 주변을 맴도는 정체 불명의 늑대인간. 그녀의 정체와 비밀을 파헤치면서 그림 형제는 진짜 모험을 시작하게 되는데…', 'https://image.tmdb.org/t/p/w500/fY8IRBwjQSFosJ2MoXv1rycfngT.jpg', 'MOVIE'),(56, NULL, 549590, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'ko', '2018-11-07', '동네사람들', '동네사람들', '여고생이 사라졌지만 너무나 평온한 시골의 한적한 마을, 기간제 교사로 새로 부임 온 외지 출신 체육교사 ‘기철(마동석)’은 동네 분위기가 심상치 않음을 감지한다. 실종된 여고생의 유일한 친구 \'유진(김새론)\'만이 친구가 납치된 거라 확신하여 사건을 쫓고, 의도치 않게 ‘유진’과 함께 사라진 소녀를 찾기 위해 나선 ‘기철’은 누군가에 의해 그녀의 흔적들이 사라지고 있다는 사실을 알게 되는데...', 'https://image.tmdb.org/t/p/w500/fL5OHCA7jXhvq4MOJAdVpJJzBF4.jpg', 'MOVIE'),(57, NULL, 33196, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'ko', '2009-07-22', '해운대', '해운대', '해운대 토박이 만식은 연희를 좋아하면서도 자신의 마음을 숨길 수 밖에 없다. 그러던 어느 날, 만식은 오랫동안 가슴 속에 담아두었던 자신의 마음을 전하기로 결심하고 연희를 위해 멋진 프로포즈를 준비한다. 한편 국제해양연구소의 지질학자 김휘 박사는 대마도와 해운대를 둘러싼 동해의 상황이 5년전 발생했던 인도네시아 쓰나미와 흡사하다는 엄청난 사실을 발견하게 된다. 그는 안전하지 않다고 수차례 강조하지만 그의 경고에도 불구하고 재난 방재청은 지질학적 통계적으로 쓰나미가 한반도를 덮칠 확률은 없다고 단언한다. 그 순간에도 바다의 상황은 시시각각 변해가고, 일본 대마도가 내려 앉으면서 초대형 쓰나미가 생성된다. 한여름 더위를 식히고 있는 수백만의 휴가철 인파와 평화로운 일상을 보내고 있는 부산 시민들, 그리고 이제 막 서로의 마음을 확인한 만식과 연희를 향해 초대형 쓰나미가 시속 800km의 빠른 속도로 밀려오는데...', 'https://image.tmdb.org/t/p/w500/AgWRG68qAT63wDybxNAebnbstts.jpg', 'MOVIE'),(58, NULL, 9509, '2026-01-29 12:23:19', '2026-01-29 12:23:25', 'en', '2004-09-24', '맨 온 파이어', 'Man on Fire', '세계 각지에서 수 많은 죽음을 집행했던 전 CIA 전문 암살 요원 존 크리시(덴젤 워싱턴). 암울한 과거로 인해 알코올에 의지하며 정처 없이 떠돌던 그는, 오랜 친구이자 동지인 레이번(크리스토퍼 월켄 분)의 권유로 마지못해 멕시코 시티에서 보디가드로 일하게 된다.  크리시가 맡은 임무는 멕시코인 사업가 사뮤엘(마크 앤서니 분)의 아홉 살짜리 딸 피타(다코타 패닝)를 보호하는 것. 세상을 향해 단단히 벽을 쌓고 살던 크리시에게, 이 무한한 호기심과 생기로 똘똘뭉친 소녀 피타는 닫혀 있던 그의 마음의 문을 여는 열쇠가 되어 준다. 처음엔 귀찮도록 질문을 해대는 소녀의 관심과 배려를 달가워하지 않던 크리시였지만, 점차 아이의 진심에 동화되고 결국 그는 오랫동안 잊고 지냈던 웃음을 되찾는다.  하지만 피타를 통해 행복을 느끼면서 새 출발을 꿈꾸던 크리시의 희망은 오래가지 못한다. 어느날, 피타를 기다리던 크리시는 수상한 사내들이 몰려오는 장면을 목격하고 그녀를 지키기 위해 사력을 다하지만 결국 총격을 받고 쓰러진다. 치명적인 부상에서 가까스로 의식을 회복한 크리시에게 전해진 소식은 유괴된 피타가 결국은 살해당하고 말았다는 것. 피타를 지키지 못했다는 죄책감과 이로 인해 절망과 분노가 극에 달한 크리시는, 자신의 목숨을 걸고서라도 반드시 납치범들을 찾아내어 모조리 없애버리겠다고 다짐한다.  이제 이 고독한 보디가드는, 유괴를 둘러싼 멕시코의 거대 범죄 조직에 맞서 그들 뒤에 숨겨진 진실들을 하나씩 밝혀내며 가장 잔인한 복수를 감행한다...', 'https://image.tmdb.org/t/p/w500/fGVxyJRrDCPMH22DnbPYePwlvSU.jpg', 'MOVIE'),(60, NULL, 581526, '2026-01-29 12:23:19', '2026-01-29 12:23:19', 'ko', '2020-08-05', '다만 악에서 구하소서', '다만 악에서 구하소서', '태국에서 충격적인 납치사건이 발생하고 마지막 청부살인 미션을 끝낸 암살자 인남은 그것이 자신과 관계된 것임을 알게 된다. 인남은 곧바로 태국으로 향하고, 조력자 유이를 만나 사건을 쫓기 시작한다. 한편, 자신의 형제가 인남에게 암살당한 것을 알게 된 레이. 무자비한 복수를 계획한 레이는 인남을 추격하기 위해 태국으로 향하는데...', 'https://image.tmdb.org/t/p/w500/xYnL0kA0V7aDvg8wupmWQbdgb9a.jpg', 'MOVIE'),(61, NULL, 1034716, '2026-01-29 12:23:19', '2026-01-29 12:23:23', 'en', '2026-01-09', '우리의 열 번째 여름', 'People We Meet on Vacation', '자유로운 영혼의 파피와 계획을 좋아하는 알렉스. 수년간 여름휴가를 함께 보낸 후, 이 정반대의 두 친구는 연인으로도 완벽한 한 쌍이 될 수 있을지 고민한다.', 'https://image.tmdb.org/t/p/w500/dCmOJiBIzr3XVkQTD85FRdOVfTK.jpg', 'MOVIE'),(64, NULL, 216015, '2026-01-29 12:23:19', '2026-01-29 12:23:24', 'en', '2015-02-25', '그레이의 50가지 그림자', 'Fifty Shades of Grey', '순수한 사회 초년생인 여대생 ‘아나스타샤’는 어느 날, 아픈 친구를 대신해 모든 것을 다 가진 매력적인 CEO ‘크리스찬 그레이’의 인터뷰를 맡게 된다. 단숨에 사람을 매료시키는 ‘크리스찬 그레이’의 마력에 ‘아나스타샤’는 순식간에 빠져들고, 그 역시 순수한 아나스타샤를 점점 더 알고 싶어지게 된다.  내 취향은 아주 분명해.  한편, 원하는 것을 모두 들어줄 만큼 완벽한 ‘그레이’의 숨겨진 비밀을 알게 된 ‘아나스타샤’는 거부할 수 없는 본능에 눈을 뜨게 되는데…', 'https://image.tmdb.org/t/p/w500/iQaLakvYBzpmdHUB2h6h2aVY5nE.jpg', 'MOVIE'),(66, NULL, 290098, '2026-01-29 12:23:19', '2026-01-29 12:23:24', 'ko', '2016-06-01', '아가씨', '아가씨', '어릴 적 부모를 잃고 후견인 이모부의 보호 아래 살아가는 귀족 아가씨에게 백작이 추천한 새로운 하녀가 찾아온다. 이모부의 서재에서 책을 읽는 것이 일상의 전부인 아가씨는  순박해 보이는 하녀에게 조금씩 의지하기 시작한다. 하지만 하녀의 정체는 유명한 여도둑의 딸인 소매치기 고아 소녀 숙희. 막대한 재산을 상속받게 될 아가씨를 유혹하여 돈을 가로채겠다는 사기꾼 백작의 제안을 받고  아가씨가 백작을 사랑하게 만들기 위해 하녀가 된 것. 드디어 백작이 등장하고, 백작과 숙희는 자신만의 방식으로 아가씨의 마음을 흔들기 시작하는데...', 'https://image.tmdb.org/t/p/w500/62l7g8lUJufEcd1Qz9TbAL5HR9t.jpg', 'MOVIE'),(67, NULL, 1290182, '2026-01-29 12:23:19', '2026-01-29 12:23:23', 'ko', '2025-02-21', '그 시절, 우리가 좋아했던 소녀', '그 시절, 우리가 좋아했던 소녀', '선아에게 고백하기까지 수많은 날을 보낸 철없던 진우의 열여덟 첫사랑 스토리. 각양각색 사춘기 소년들의 유일한 공통점은 같은 반 반장 선아를 좋아한다는 것! 어느 날, 고등학생 진우는 학교에서 작은 사고를 치게 되고, 이를 계기로 선아에게 특별 감시를 받게 된다. 문제아 진우를 비롯한 친구들은 모범생 선아의 사랑을 얻기 위해 고군분투하며 즐거운 학창 시절을 보내는데, 15년 뒤, 진우는 선아로부터 뜻밖의 고백을 듣게 된다.', 'https://image.tmdb.org/t/p/w500/1aSRSDDHQX2egc1az05qQ5tz6zS.jpg', 'MOVIE'),(69, NULL, 809, '2026-01-29 12:23:19', '2026-01-29 12:23:26', 'en', '2004-06-18', '슈렉 2', 'Shrek 2', '더 크고 신나는 세상! \"겁나먼\" 왕국에서 펼쳐지는 끝없는 상상!  꿈결같은 허니문에서 돌아온 슈렉과 피오나. 이 행복한 녹색 커플은 \"겁나먼\" 왕국의 왕과 왕비인 피오나의 부모님으로부터 초청장을 받는다. 드디어 도착한 왕국에는 모든 시민들이 기대에 부풀어 그들을 기다리고 있는데... 덜리는 맘으로 슈렉이 모습을 드러내는 순간, 멋진 왕자를 기대했던 모든 이들은 기절초풍! 초록색이 되어버린 공주는 말할 것도 없이 말이다. 발칵 뒤집힌 \"겁나먼\" 왕국. 이제 이 충격적인 사건을 해결하기 위해 만만치 않은 강적들이 속속 등장한다. 업계 1위의 괴물 전문 킬러 \'장화신은 고양이\', 퍼펙트한 외모의 왕자 \'프린스 챠밍\', 신비한 힘을 가진 요정 대모까지. 성가신 건 질색인 슈렉에게 터져버린 대형 사고! 또 다시 의도하지 않은 사건에 휘말린 슈렉 패밀리 앞에 상상할 수 없는 예측 불허의 모험들이 펼쳐지는데...', 'https://image.tmdb.org/t/p/w500/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', 'MOVIE'),(70, NULL, 851644, '2026-01-29 12:23:19', '2026-01-29 12:23:19', 'ko', '2022-10-06', '20세기 소녀', '20세기 소녀', '보라의 둘도 없는 친구 연두는 심장 수술을 위해 미국에 가면서 자신이 좋아하는 남자 백현진에 대한 모든 정보를 수집해 달라고 보라에게 부탁한다. 보라는 백현진의 가장 친한 친구 풍운호와 먼저 친해지기로 한다. 하지만 보라의 서투른 계획은 예상치 못한 방향으로 전개된다. 새로운 세기가 오기 1년 전인 1999년, 17세가 된 보라는 첫사랑의 열병에 빠진다.', 'https://image.tmdb.org/t/p/w500/rSNtRQpCsDckczokmynAcVAt4Fm.jpg', 'MOVIE'),(71, NULL, 287649, '2026-01-29 12:23:20', '2026-01-29 12:23:25', 'ko', '2014-10-02', '마담 뺑덕', '마담 뺑덕', '불미스러운 오해에 휘말려, 지방 소도시 문화센터의 문학 강사로 내려온 교수 학규는 퇴락한 놀이공원의 매표소 직원으로, 고여있는 일상에 신물 난 처녀 덕이와 걷잡을 수 없는 사랑에 빠진다. 그러나 학규는 복직이 되자마자 서울로 돌아가고 덕이는 버림 받는다. 8년 후, 학규는 작가로 명성을 얻지만 딸 청이는 엄마의 자살이 아버지 탓이라 여기며 반항하고, 학규는 눈이 멀어져 가는 병까지 걸린다. 모든 것을 잃을 위기에 처한 학규의 앞 집으로 이사 온 여자 세정. 눈이 거의 보이지 않는 학규가 세정이 8년 전 덕이라는 걸 모른 채 그녀에게 의지하는 사이, 청이 또한 그녀에게 집착하게 된다. 덕이 없이 아무것도 못하게 된 학규, 그리고 두 사람 사이를 눈치채고 위험한 질투를 시작하는 청이. 세 사람의 위태로운 관계의 한 가운데, 마침내 주도권을 쥔 덕이는 학규의 모든 것을 망가뜨리려고 하는데…', 'https://image.tmdb.org/t/p/w500/trvtnsNZjHwvB97RLQ3Nc5oncti.jpg', 'MOVIE'),(74, NULL, 9769, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '1998-10-17', '로리타', 'Lolita', '슬픈 첫사랑의 아픔을 간직한 47세의 불문학자 험버트(제레미 아이언스). 뜨거운 여름, 강의차 미국 뉴잉글랜드에 들른다. 샤롯트(멜라니 그리피스)라는 미모의 미망인의 집에 거처를 마련한 그는 그녀의 딸 로리타(도미니크 스웨인)를 본 순간, 아찔한 사랑에 빠진다. 결국 험버트는 로리타의 곁을 떠나지 않기 위해 샬롯의 프로포즈를 받아들이고 그녀와 결혼한다. 그러던 어느날, 로리타에 대한 마음을 기록한 그의 일기장을 샬롯이 발견하고, 그 충격에 거리로 뛰쳐나가 교통사고로 죽고 만다. 어머니의 죽음을 알게 된 로리타는 자신을 버리지 말라고 험버트에게 매달리는데...', 'https://image.tmdb.org/t/p/w500/9INcC14WZjCMKGE360VXmklCLdZ.jpg', 'MOVIE'),(76, NULL, 337167, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2018-02-21', '50가지 그림자: 해방', 'Fifty Shades Freed', '모든 과거를 잊고 서로에게 더 깊게 빠져든 ‘크리스찬 그레이’와 ‘아나스타샤’.  그레이의 독특한 취향으로 시작된 이 비밀스러운 관계는  더 큰 자극을 원하는 아나스타샤로 인해 역전되고,  마침내 그녀의 본능이 지배하는 마지막 절정의 순간을 맞이하게 되는데…', 'https://image.tmdb.org/t/p/w500/kdN58uXDV5D0RWdMjdO9jtdFjxg.jpg', 'MOVIE'),(77, NULL, 1587, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '1994-06-11', '길버트 그레이프', 'What\'s Eating Gilbert Grape', '인구 1091명이 사는 아이오아주 \'엔도라\'에 사는 길버트 그레이프는 식료품 가게의 점원으로 일하며 집안의 가장으로서의 역할과 가족들로부터의 탈출에 대한 욕망 속에서 살아가고 있다. 그에게는 남편이 목매달아 자살한 이후의 충격으로 몸무게가 500파운나 나가는 거구인 어머니와 정신 연령이 어린아이 수준인 지적장애인 동생 어니와 34살의 누나가 있고, 16살로 한창 멋 내기를 좋아하는 미모의 여동생 엘렌이 있다. 틈만 나면 높은 곳으로 올라가려 하는 동생 어니는 어머니의 엄청난 몸무게와 함께 집안의 골칫거리이다. 그러나 형의 말은 절대적으로 따른다. 또한 항상 불만이 많은 여동생 엘렌도 길버트 가의 또 하나의 골칫거리다. 길버트의 가족을 위한 생활은 설명하기 어려울 만큼 괴상하며, 자기 생활에 만족하지 못한다. 매일 반복되는 지루한 생활. 그 속에서 길버트는 동네의 카버 부인과 불륜 관계를 가진다. 물론 카버 부인에게 이끌려 그렇게 되었지만 답답한 틀 속에 갇혀 있던 길버트는 굳이 이를 부정하지 않는다. 한편, 캠핑족 소녀 베키는 자동차가 고장 나는 바람에 엔도라에 머무르게 되고, 우연히 가스탱크에 올라 가 있는 어니를 따뜻하게 대하는 길버트를 보게 되고, 그의 순수한 마음에 호감을 느끼게 된다. 길버트 또한 같은 또래의 여자인 베키에게 끌리게 되고 둘은 서로의 내면을 아껴 주는 순수한 사랑을 하게 되는데...', 'https://image.tmdb.org/t/p/w500/iKyOkIMkgcBFdPas2ArQJHiTW1n.jpg', 'MOVIE'),(78, NULL, 43347, '2026-01-29 12:23:20', '2026-01-29 12:23:23', 'en', '2011-01-13', '러브 & 드럭스', 'Love & Other Drugs', '타고난 바람둥이 제이미(제이크 질렌할 분)는 넘치는 바람기 때문에 다니던 직장에서 해고를 당한다. 제약회사에 영업사원으로 취직한 제이미는 자신의 매력을 100% 활용, 병원을 상대로 영업에 나선다. 얽매이길 싫어하는 자유로운 영혼의 소유자인 매기(앤 헤서웨이 분). 그녀는 진지한 사랑에 빠지길 두려워하며 가벼운 관계만을 쫓아 하룻밤 상대로 남자들을 고른다.  병원에 영업차 갔던 제이미는 그곳에서 환자인 매기를 우연히 만나게 되고 장난스럽고 유쾌한 제이미의 연애신청이 싫지 않은 매기는 진지한 사랑보다는 몇 시간을 함께 보낼 잠자리 친구로 지내자고 제안한다.  한편, 화이자가 개발한 비아그라가 선풍적인 인기를 끌면서 제이미는 업계에서 승승장구하게 된다. 몸으로 하는 사랑(?)엔 쿨하고 마음으로 하는 사랑은 싫은 두 사람은 시간이 지날수록 서로의 매력에 이끌리게 되고 제이미는 매기에게 사랑을 고백하지만 그녀는 받아들이지 않는데……', 'https://image.tmdb.org/t/p/w500/3Q4rfwS3HliQa2Yhp9bIDYWetJb.jpg', 'MOVIE'),(80, NULL, 1136867, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2025-08-08', '머티리얼리스트', 'Materialists', '잘나가는 커플매니저 루시. 고객의 결혼식에서 소위 ‘유니콘’이라 불리는 뉴욕 최고의 싱글남 해리에게 대시를 받는다. 같은 날, 같은 장소, 결혼식장에서 서빙 아르바이트를 하던 전남친 존과 마주치면서 루시는 예상하지 못한 고민이 시작되는데…', 'https://image.tmdb.org/t/p/w500/QhGn8LntSVpxFFSw7KU3SEscQm.jpg', 'MOVIE'),(82, NULL, 762975, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2022-07-30', '퍼플 하트', 'Purple Hearts', '파병이 예정된 해병대원과 위장 결혼을 한 뮤지션 지망생. 가짜였던 둘의 관계는 비극으로 인해 어느새 진심이 되어버린다.', 'https://image.tmdb.org/t/p/w500/bETrhE8ALy0fmfpG0j7ek6Da4Or.jpg', 'MOVIE'),(84, NULL, 537915, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2019-08-22', '애프터', 'After', '대학 입학 후 첫 파티에 초대 받게 된 신입생 ‘테사’는 진실게임을 하던 중 키스 벌칙에 걸리고 만다. 상대는 학교에서 유명한 반항아 ‘하딘’. 키스를 앞둔 0.1초 전, 모두가 주목하는 그 순간 ‘테사’는 ‘하딘’의 입술을 거절하고 만다. 강렬했던 첫 만남 이후, 마치 새로운 세상을 발견한 듯 한번도 경험한 적 없던 감정에 눈을 뜨게 된 두 사람. ‘하딘’은 자신의 비밀 장소로 ‘테사’를 초대하고 이제 두 사람은 서로를 모르기 전으로 절대 되돌아 갈 수 없음을 알게 되는데…', 'https://image.tmdb.org/t/p/w500/zTZ7Q9mAwBQoYaR8HgGbmBNp6AC.jpg', 'MOVIE'),(85, NULL, 499028, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'ko', '2018-03-14', '지금 만나러 갑니다', '지금 만나러 갑니다', '비가 오는 날 다시 돌아오겠다는 믿기 힘든 약속을 남기고 세상을 떠난 수아. 그로부터 1년 뒤 장마가 시작되는 어느 여름 날,  세상을 떠나기 전과 다름없는 모습의 수아가 나타난다. 하지만 수아는 우진이 누구인지조차도 기억하지 못한다. 자신을 기억하지 못해도 그녀가 곁에 있다는 사실만으로 행복에 젖은 우진과 자신이 기억하지 못하는 그와의 이야기가 궁금한 수아. 우진이 들려주는 첫 만남, 첫 사랑, 첫 데이트, 첫 행복의 순간을 함께 나누며 수아는 우진과 다시 사랑에 빠지는데…', 'https://image.tmdb.org/t/p/w500/t37dPqCCV7IgKaGm5nqmmHmLJ1L.jpg', 'MOVIE'),(87, NULL, 3981, '2026-01-29 12:23:20', '2026-01-29 12:23:24', 'en', '2001-01-13', '왓 위민 원트', 'What Women Want', '광고 회사에서 일하는 남성우월주의자 닉. 어느 날 감전 사고를 당한 그에게 특별한 능력이 생긴다. 여자들의 생각을 들을 수 있게 된 것! 하지만 이 능력이 생각처럼 유용한 것만은 아니다.', 'https://image.tmdb.org/t/p/w500/wamRJHN4OB1zSOAr35cJOnGooYg.jpg', 'MOVIE'),(91, NULL, 666277, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2024-03-06', '패스트 라이브즈', 'Past Lives', '12살의 어느 날, 해성의 인생에서 갑자기 사라져버린 첫사랑, 나영. 12년 후, 나영은 뉴욕에서 작가의 꿈을 안고 살아가다 SNS를 통해 우연히 어린 시절 첫사랑 해성이 자신을 찾고 있었다는 사실을 알게 된다. 또 한 번의 12년 후, 인연의 끈을 붙잡기 위해 용기 내어 뉴욕을 찾은 해성. 수많은 만약의 순간들이 스쳐가며, 끊어질 듯 이어져온 감정들이 다시 교차하게 되는데...', 'https://image.tmdb.org/t/p/w500/6o6jgwvPc0W1FuFwA9XFAHwljt4.jpg', 'MOVIE'),(92, NULL, 49203, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'ko', '2005-09-07', '가문의 영광 2: 가문의 위기', '가문의 영광 2: 가문의 위기', '최고 명문家 백호파의 대모 홍덕자 여사! 조직은 조직대로 무럭무럭 크고, 슬하의 세 아들은 나름 믿음직하다. 그러나 반드시 이룩해야 할 단 하나의 과제가 남아 있었으니, 가문의 체질개선을 위한 엘리트 며느리 모시기! 홍여사는 세 아들에게 자신의 환갑잔치 때까지 무조건 큰 며느리감을 데려오라는 명령을 내린다. 며느리감 물색에 나선 세 아들, 드디어 어디 내놔도 안 부끄러울 며느리 감을 발견했단다. 근데 며느리 될 아이가 강력계 검사라고라고라? 가문의 영광을 이루려다 가문이 위태롭게 생겼다. 과연 홍여사와 세 아들은 엘리트 며느리 모시기에 성공할 수 있을 것인가?', 'https://image.tmdb.org/t/p/w500/iJiSJ1y5P2CoVDFqzzpmBltTxc2.jpg', 'MOVIE'),(96, NULL, 3635, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2004-09-03', '진주 귀걸이를 한 소녀', 'Girl with a Pearl Earring', '1665년 네덜란드 델프트. 16세 소녀 그리트는 아버지가 사고로 시력을 잃자 화가 베르메르 집의 하녀로 들어간다. 베르메르의 작업실을 청소하기 위해 방에 들어선 순간 그리트는 다른 세상에 온 것만 같은 말할 수 없는 감동을 느끼게 되고 그런 그녀를 본 베르메르는 신선한 영감을 얻게 된다. 베르메르는 그리트에게 색을 보는 법과 만드는 방법을 가르쳐 주면서 가까워 지지만 탐욕스러운 아내, 장모와 함께 살면서 여섯 명의 아이들을 건사해야 하는 베르메르는 안타까운 시선 이상의 관심을 그리트에게 표현할 수가 없다.', 'https://image.tmdb.org/t/p/w500/41DkOi1MvTgTQXt5BevVSzo94kk.jpg', 'MOVIE'),(97, NULL, 466282, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'en', '2018-08-17', '내가 사랑했던 모든 남자들에게', 'To All the Boys I\'ve Loved Before', '지금까지 다섯 명. 짝사랑의 마음을 몰래 편지로만 남겨두었던 라라 진. 그런데 어느 날, 그들에게 쓴 비밀 러브레터가 발송됐다. 어떻게? 그건 중요하지 않다. 어제의 라라 진은 사라졌으니까.', 'https://image.tmdb.org/t/p/w500/nCz3swDzvFJxfCzeH1nS2qekIbL.jpg', 'MOVIE'),(98, NULL, 49214, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'ko', '2004-01-15', '말죽거리 잔혹사', '말죽거리 잔혹사', '1978년 말죽거리의 봄, 현수는 강남의 정문고로 전학온다. 정문고는 선생 폭력 외에도 학생들간 세력다툼으로 악명높은 문제학교. 이소룡 열혈팬이라는 이유로 금새 죽고 못사는 친구가 된 모범생 현수와 학교짱 우식. 하교길 버스안에서 올리비아 핫세를 꼭 닮은 은주를 보고 동시에 반하는 현수와 우식. 하지만 은주는 다정한 현수보다 남자다운 우식에게 빠져든다.', 'https://image.tmdb.org/t/p/w500/9h0Pos3Ydu1TkO9vtFOs45osdLB.jpg', 'MOVIE'),(99, NULL, 56247, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'ko', '2007-06-06', '황진이', '황진이', '16세기, 유일하게 인간대접을 받는 양반이 되기 위해 사람들은 돈과 거짓을 서슴치 않았다. 그러나 진이는 출생의 비밀을 듣는 순간 기꺼이 규방의 옷을 벗고 모두가 멸시하는 천민의 길을 선택한다. 소꿉친구인 노비 \'놈이\'를 첫 남자로 삼은 다음 날, 기생들의 거리 \'청교방\'에 들어간다. 밤마다 홍등을 걸고 남자들의 노리개가 되어야 하는 기생 명월이 된 진이. 옷감 세 필이면 모두 그녀를 안을 수 있었지만 그 재능과 위엄에 오히려 정복되고 만다. 양반부터 천민까지 모두의 동경의 대상이 된 기생 명월. 사농공상의 신분구별이 목숨처럼 중하게 여겨지던 시대였지만 그녀의 치마폭 앞에서는 한 인간으로서 평등했다. 그러나 이제 그녀는 신분을 버렸던 것보다 더 위험한 선택을 하게 되는데...', 'https://image.tmdb.org/t/p/w500/r2QINEUb0X3BWs17UgW84GKUnpO.jpg', 'MOVIE'),(100, NULL, 125183, '2026-01-29 12:23:20', '2026-01-29 12:23:20', 'ko', '1998-12-19', '미술관 옆 동물원', '미술관 옆 동물원', '결혼식 비디오를 찍는 일을 하고 있는 춘희는 자주 주례를 서는 국회의원의 보좌관 인공을 짝사랑하고 있는 중이다. 그러던 어느 날, 게으른 춘희의 자취방에 군대에서 휴가를 나온 철수가 찾아와 이사간 다혜의 연락처를 내놓으라며 막무가내로 들어온다. 철수의 등장으로 춘희는 쓰고 있던 시나리오가 진척이 되지 않고, 철수는 결혼을 한다며 연락을 피하는 다혜 때문에 속앓이를 한다. 감정에 충실한 동물원 남자 철수는 소녀적인 미술관 여자 춘희의 시나리오에 핀잔을 주고 둘은 서로가 사랑하는 인공과 다혜를 내세워 시나리오를 쓰기 시작한다. 시나리오 안에서 미술관 안내원 다혜와 동물원 수의사 인공의 관계가 발전할수록 철수와 춘희의 관계도 달라지는데...', 'https://image.tmdb.org/t/p/w500/yOcwp49oN6RlS8iWIxgdT0dW3xZ.jpg', 'MOVIE'),(101, NULL, 948549, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2024-07-10', '러브 라이즈 블리딩', 'Love Lies Bleeding', '체육관 매니저로 일하며 무료하게 일상을 보내던 루 앞에 보디빌딩 대회 우승을 꿈꾸는 와일드한 잭키가 나타나고 둘은 0.001초 만에 사랑에 빠진다. 두 사람의 사랑이 점점 깊어 가던 어느 날 사랑하는 루를 위해 엄청난 살인을 저지른 잭키. 범죄에 깊게 연루된 가족으로부터 잭키를 지키려는 루. 상상 이상의 짜릿한 슈퍼 범죄 로맨스가 시작된다!', 'https://image.tmdb.org/t/p/w500/aum9VtZx5wTDtcXbqH4rRzNr2lI.jpg', 'MOVIE'),(104, NULL, 578209, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2019-11-14', '윤희에게', '윤희에게', '갓 수능을 마친 고등학교 3학년 새봄은 우편함에서 수상한 편지를 발견한다. 일본 북해도의 어느 마을에서 엄마를 향해 날아든, 절절한 연애 편지. 3년 전에 엄마와 이혼한 아빠도, 하나뿐인 삼촌도 엄마에 대해 잘 모르는 눈치다. 늘 피로에 찌들어 있고 무기력해 보이는 엄마가 답답했던 새봄은 무작정 엄마에게 같이 여행을 가자고 조른다.', 'https://image.tmdb.org/t/p/w500/vSSOnj5Zsc2TQ1QAPAe8lUYr5Aq.jpg', 'MOVIE'),(105, NULL, 64882, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2010-12-08', '김종욱 찾기', '김종욱 찾기', '돌다리도 두드려 보고 건너는 고지식한 성격의 소유자 한기준. 지나치게 강한 책임감과 융통성 제로에 가까운 성격 덕에 회사에서 잘린 기준은 우연한 기회에 기발한 창업 아이템을 찾아 낸다. 바로 아직까지 첫사랑을 잊지 못한 사람들을 위해 첫사랑을 찾아주는 일! 기준은 고객에게 무한 감동을 선사하겠다는 열정과 패기로 첫사랑 찾기 사무소를 오픈 한다. 남자친구로부터 프러포즈를 받은 서지우는 딸이 시집가기만을 학수고대하는 홀아버지의 압박에도 불구하고 결국 프러포즈를 거절하고 만다. 일에만 매달려온 그녀 맘 속에는 김종욱이라는 잊을 수 없는 사람이 있기 때문. 아버지에게 등 떠밀려 첫사랑 찾기 사무소를 찾은 서지우는 우여곡절 끝에 이제는 기억 조차 희미한 첫사랑의 상대 김종욱을 찾아보기로 결심한다.', 'https://image.tmdb.org/t/p/w500/gByt7A0AK1bKCnQMCIdxOWCci5e.jpg', 'MOVIE'),(107, NULL, 189150, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2013-02-14', '남자사용설명서', '남자사용설명서', '국민흔녀를 위한 최강의 연애비법이 밝혀진다!  우유부단한 성격 탓에 온갖 궂은 일을 다 도맡는 CF 조감독 최보나.  연이은 야근에 푸석푸석해진 얼굴과 떡진 머리는 최보나의 일상이 된지 오래…  무엇보다 제대로 된 연애를 해본 기억조차 가물가물한 이 시대의 대표적인 흔녀이다.  그러던 어느 날, 최보나는 야외촬영을 마치고 우연히 “남자사용설명서”를 손에 쥐게 된다.  그녀가 반신반의하며 “남자사용설명서” 테잎 속 Dr. 스왈스키의 지시를 따라 하자,  거짓말처럼 지나가는 남자들의 시선은 물론 한류 톱스타 이승재의 마음까지 흔들어 놓게 되는데…  과연 최보나는 “남자사용설명서”를 통해 새로운 사랑을 시작할 수 있을까?  당신도 연애를 시작하세요!', 'https://image.tmdb.org/t/p/w500/xSqURMycyqnWQ2Gli8BpfwfntpP.jpg', 'MOVIE'),(108, NULL, 705996, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2022-06-29', '헤어질 결심', '헤어질 결심', '산 정상에서 추락한 한 남자의 변사 사건. 담당 형사 해준은 사망자의 아내 서래와 마주하게 된다. 남편의 죽음 앞에서 특별한 동요를 보이지 않는 서래. 경찰은 보통의 유가족과는 다른 서래를 용의선상에 올린다. 해준은 사건 당일의 알리바이 탐문과 신문, 잠복수사를 통해 서래를 알아가면서 그녀에 대한 관심이 점점 커져가는 것을 느낀다. 한편 좀처럼 속을 짐작하기 어려운 서래는 상대가 자신을 의심한다는 것을 알면서도 조금의 망설임도 없이 해준을 대하는데...', 'https://image.tmdb.org/t/p/w500/rXEJ28XDQsogIGqwVEgwM2oDdpl.jpg', 'MOVIE'),(109, NULL, 313628, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2015-01-14', '오늘의 연애', '오늘의 연애', '해 달라는 대로 다 해주는데 100일도 못 가 항상 여자친구에게 차이는 초등학교 교사 준수. 그에게 여자의 마음은 영원히 풀리지 않는 숙제다. 그런 준수에게는 특별한 썸녀가 있다. 바로 요즘 가장 인기 있는 기상캐스터 현우. 매일 밥 먹고 영화보고 데려다 주고 손도 잡고 위급할 때마다 도와주고 오피스텔 비번까지 아는 사이지만 애인은 아닌, 술 먹자고 불러내면 다른 남자 때문에 우는 그녀. 준수의 어린 시절 고백 따위는 묻어두는 쿨한…. 18년(!) 친구다.  현우는 임자 있는 회사 선배부터 적극적인 연하남까지 얽히고 설킨 남자들이 넘쳐나고, 그녀의 썸 뒷바라지나 해야 하는 준수는 더 이상 참을 수가 없는데…', 'https://image.tmdb.org/t/p/w500/aLhmyQXy1lCwA2htnjrJYtGgBbP.jpg', 'MOVIE'),(110, NULL, 644090, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2020-09-02', '러브, 개런티드', 'Love, Guaranteed', '어려운 이들을 돕느라 돈이 궁해진 변호사. 그녀 앞에 웬일로 돈이 되는 새 의뢰인이 나타난다. 그런데 뭐? 사랑을 찾을 거라고 보장한 데이팅 사이트를 소송하고 싶다고?', 'https://image.tmdb.org/t/p/w500/6K22JB6fZZLBuM0knfl8rs9Zoxg.jpg', 'MOVIE'),(112, NULL, 341174, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2017-02-09', '50가지 그림자: 심연', 'Fifty Shades Darker', '크리스찬 그레이는 아나스타샤 스틸을 잊지 못해 되찾으려고 하지만 아나스타샤는 지금까지와 다른 새로운 관계를 원한다. 과거의 상처를 고백하며 점점 변해가는 크리스찬의 모습에 아나스타샤는 결국 그를 받아들이고, 둘은 서로에게 더욱 깊이 빠져들며 뜨거운 사랑을 나눈다. 그러나 그의 숨겨진 과거와 비밀을 아는 사람들이 아나스타샤를 위협하기 시작하면서 그들의 관계는 위태로워지는데...', 'https://image.tmdb.org/t/p/w500/stwVY9rRcA3NSKW04IOD30ZsrZx.jpg', 'MOVIE'),(116, NULL, 962489, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2022-11-16', '동감', '동감', '1999년, 용은 첫눈에 반하게 된 한솔을 사로잡기 위해 친구에게 HAM 무전기를 빌린다. 2022년, 무늬는 인터뷰 과제를 위해 오래된 HAM 무전기를 작동시킨다. 개기 월식이 일어난 날, 시간을 뛰어넘어 기적처럼 연결된 용과 무늬는 서로의 사랑과 우정을 이야기하며 특별한 감정을 쌓아가는데...', 'https://image.tmdb.org/t/p/w500/f1i6kynpQDXcXxyZU5fpG9AwbKz.jpg', 'MOVIE'),(117, NULL, 376252, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2016-01-14', '그날의 분위기', '그날의 분위기', '부산행 KTX 열차에서 우연히 옆자리에 앉게 된 수정과 재현. 자꾸 눈길이 가는 매력적인 수정에게 재현이 건넨 한 마디, “저… 오늘 웬만하면 그쪽이랑 자려구요”  자유 연애, 오픈 마인드! 작업했다 하면 100% 성공률을 자랑하는 맹공남 재현의 훅훅 들어오는 맹렬한 공격에 수정은 점차 말려들게 되는데…  “저 그런 여자 아니거든요!”  10년 연애, 일편단심! 안 하는 것 참 많은 이 시대의 철벽녀 수정은 당황스러움도 잠시 철벽 방어로 재현의 유혹에 맞선다.  맹공남 VS 철벽녀! 두 남녀의 아슬아슬 밀당 로맨스, 승자는?', 'https://image.tmdb.org/t/p/w500/cbhGpXAVoK8ztKf78Uw0TWi2EPc.jpg', 'MOVIE'),(119, NULL, 21647, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2007-12-12', '색즉시공 시즌 2', '색즉시공 시즌 2', '\'색\'에 굶주린 법대생. 남들 다 부러워하는 여친이 있음 뭘 해. 주야장천 키스만 입술 부르트게 하는데! 고시 준비도 막막, 색의 실천도 막막하던 차에 엄청난 라이벌까지 맞이하다니. 이제 여친이랑 진도 빼기는커녕 여친을 잃을 위기? 캠퍼스는 불철주야 끓어오르는 열기와 함께 오늘도 ‘색’을 실천하며 나날이 건강(?)해 지고 있다. 밤마다 모텔행의 실랑이가 벌어지고, 잠 못 이루는 기숙사에선 예측 불가능한 실험들이 난무하는데...', 'https://image.tmdb.org/t/p/w500/7CXkBFZvQ6kKeiDJeUQOZRyLHMl.jpg', 'MOVIE'),(121, NULL, 1062722, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2025-10-22', '프랑켄슈타인', 'Frankenstein', '과학자 빅터 프랑켄슈타인과 그의 손에서 탄생한 괴물이 펼치는 이야기. 고전이 된 메리 셸리의 소설을 오스카 수상 감독 기예르모 델토로가 영화화했다.', 'https://image.tmdb.org/t/p/w500/vSMWJkBTEfa7kFxHizSz4uJNVlf.jpg', 'MOVIE'),(122, NULL, 1100988, '2026-01-29 12:23:21', '2026-01-29 12:23:24', 'en', '2025-06-19', '28년 후', '28 Years Later', '28년 전 생물학 무기 연구소에서 세상을 재앙으로 몰아넣은 바이러스가 유출된 후, 일부 생존자들이 모여 철저히 격리된 채 살아가는 섬 홀리 아일랜드. 이곳에서 태어나 한 번도 섬 밖을 나가 본 적 없는 소년 스파이크는 어느 날 섬을 떠나 본토에 발을 들이게 되고 난생처음 바이러스에 잠식된 세상을 마주하게 된다. 변이된 바이러스는 10,228일의 시간 동안 감염자들을 더욱 충격적으로 진화시켰고 스파이크는 그 실체를 목격하며 극강의 공포에 휩싸이게 되는데...', 'https://image.tmdb.org/t/p/w500/zRo90O0bTKJem1aDgVa6Sm0gthE.jpg', 'MOVIE'),(123, NULL, 1194963, '2026-01-29 12:23:21', '2026-01-29 12:23:24', 'ko', '2025-06-25', '노이즈', '노이즈', '내 집 마련에 성공한 주영과 주희 자매. 어느 날부터 아파트 어딘가에서 들려오는 정체불명의 층간소음에 시달린다. 그러던 중 동생 주희와 연락이 끊기자 불안에 휩싸인 주영은 급히 지방 공장에서 집으로 돌아오고, 주희의 남자친구 기훈과 함께 실종된 동생을 추적하기 시작한다. 한편, 자매와 마찬가지로 층간소음에 시달리던 아랫집 남자는 그 소음의 근원이 윗집 자매에게 있다고 생각해 살인 협박을 하게 되는데….', 'https://image.tmdb.org/t/p/w500/tPOcNetZHfmn97V93TikhWDXj4T.jpg', 'MOVIE'),(125, NULL, 1151031, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2025-06-06', '브링 허 백', 'Bring Her Back', '아빠의 죽음 후 새엄마에게 입양된 남매 앤디와 파이퍼. 평화로운 집, 따뜻한 보금자리에서의 안식도 잠시 새엄마는 두 남매 사이를 갈라놓으며 앤디와 파이퍼를 혼란에 빠트린다. 고립된 집, 집 안 곳곳에서 발견되는 정체를 알 수 없는 의식의 흔적들, 새엄마가 숨긴 끔찍한 비밀이 드러나면서 남매를 극한의 공포 상황으로 몰아붙이기 시작하는데… 보지 말아야 할 것을 본 두 사람은 과연 살아남을 수 있을까!', 'https://image.tmdb.org/t/p/w500/A4W0yRN7Xy6JLIhRymIh5plK2Zj.jpg', 'MOVIE'),(126, NULL, 4232, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '1999-01-16', '스크림', 'Scream', '작은 소도시 우즈버러에 사는 케이시에게 이상한 남자로부터 전화가 걸려온다. 비디오를 보려는 케이시에게 그 남자는 케이시의 남자 친구인 스티브의 목숨을 걸고 게임을 하자고 한다. 케이시가 문제를 맞추면 살고, 틀리면 남자친구가 죽는다. 문제는 \'13일의 금요일\'에 나오는 살인마의 이름을 맞추는 것. 케이시는 문제를 풀지 못하고, 스티브는 처참하게 죽임을 당한다. 이튿날, 혼자 집에 있는 시드니에게도 이상한 전화가 걸려온다. 시드니는 케이시와는 달리 힘들게 괴전화의 마수에서 빠져 나온다. 그러나 시드니의 남자 친구 빌리가 살인 용의자로 체포되는데, 조사 후 무혐의로 풀려난다.', 'https://image.tmdb.org/t/p/w500/fvprcRjlvrgok1rvOJN4NY8Uqba.jpg', 'MOVIE'),(127, NULL, 49797, '2026-01-29 12:23:21', '2026-01-29 12:23:25', 'ko', '2010-08-12', '악마를 보았다', '악마를 보았다', '국정원 경호요원 수현은 약혼녀 주연이 잔인하게 살해당하자 자신에게 가장 소중한 사람을 지켜내지 못했다는 자괴감과 분노로 가장 고통스러운 복수를 다짐한다. 수현은 연쇄살인마 장경철이 범인임을 알아내고 죽을 만큼의 고통만 가하고 놓아주기를 반복하며 처절한 응징을 시작한다. 그러나, 악마보다 더 악랄한 살인마 장경철은 난생 처음 만난 대등한 적수의 출현을 즐기며 반격에 나서기 시작하는데…', 'https://image.tmdb.org/t/p/w500/xAhsrqrsMIO7YwKbLAlWatzFbgX.jpg', 'MOVIE'),(128, NULL, 447332, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2018-04-12', '콰이어트 플레이스', 'A Quiet Place', '인류 종말의 초기 단계로 보이는 가까운 미래, 이미 폐쇄된 뉴욕 주에서 간신히 살아남은 부부와 세 자녀가 맨발로 숨죽인 채 시골 마을의 식료품점을 헤맨다. 작은 소리에도 민감하게 반응해 소리의 근원지를 파괴하러 달려오는 괴 생명체가 곳곳에 도사리고 있기 때문. 전 세계를 파괴해 버린 무차별적인 공격과 숨통을 조여 오는 거대한 위협 속에서 살아남기 위해 주인공 가족은 일상에서 발생하는 모든 소리를 최소화하며 위태롭게 살아간다. 숨소리조차 마음 편히 낼 수 없는 극한의 상황, 아버지 리(존 크래신스키)와 어머니 에블린(에밀리 블런트)은 아이들과 자신들의 생명을 지키기 위해 고군분투하는데...', 'https://image.tmdb.org/t/p/w500/qh2GYLCJlWZhC4jSzArFy5Ep0k6.jpg', 'MOVIE'),(131, NULL, 762441, '2026-01-29 12:23:21', '2026-01-29 12:23:25', 'en', '2024-06-26', '콰이어트 플레이스: 첫째 날', 'A Quiet Place: Day One', '평균 소음 90 데시벨을 자랑하는 미국 최대도시 뉴욕, 고양이 프로도와 함께 간만에 외출을 나온 사미라는 공연을 보고 돌아가던 중 하늘에서 떨어져 내리는 섬광을 목격하고 곧 사람들을 닥치는 대로 공격하는 정체불명 괴생명체의 출현에 충격에 휩싸인다. 아수라장이 된 뉴욕 도심에 ‘절대 소리 내지 말라’는 안내방송이 울려퍼지는 가운데 맨해튼의 모든 다리가 폭격으로 끊어지고, 사람들은 온갖 위협이 도사리는 도시에 고립되고 만다. 살아남기 위해 홀로 사투를 벌이던 \'사미라\'는 우연히 또 다른 생존자 에릭을 만나고 두 사람은 괴생명체를 피해 지하철역부터 시가지, 할렘까지 숨죽인 여정을 이어 나가는데…', 'https://image.tmdb.org/t/p/w500/eufjDFIHtFSmcblWpvw5BiNzmO6.jpg', 'MOVIE'),(132, NULL, 508642, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2018-03-28', '곤지암', '곤지암', '1979년 환자 42명의 집단 자살과 병원장의 실종 이후, 섬뜩한 괴담으로 둘러싸인 곤지암 정신병원으로 공포체험을 떠난 7명의 멤버들. 원장실, 집단 치료실, 실험실, 열리지 않는 402호. 괴담의 실체를 담아내기 위해 병원 내부를 촬영하기 시작하던 멤버들에게 상상도 못한 기이하고 공포스러운 일들이 실제로 벌어지기 시작 하는데…', 'https://image.tmdb.org/t/p/w500/llj8dIkLSHOG1X7aFXims2IaCU5.jpg', 'MOVIE'),(133, NULL, 493922, '2026-01-29 12:23:21', '2026-01-29 12:23:25', 'en', '2018-06-07', '유전', 'Hereditary', '애니는 일주일 전 돌아가신 엄마의 유령이 집에 나타나는 것을 느낀다. 애니가 엄마와 닮았다며 접근한 수상한 이웃 조안을 통해 엄마의 비밀을 발견하고, 자신이 엄마와 똑같은 일을 저질렀음을 알게 된다. 그리고 마침내 애니의 엄마로부터 시작돼 아들 피터와 딸 찰리에게까지 이어진 저주의 실체가 정체를 드러내는데…', 'https://image.tmdb.org/t/p/w500/zAEhUJB5ytmDtjVZP0aooPkdGyq.jpg', 'MOVIE'),(135, NULL, 1232546, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2025-05-27', '언틸 던: 무한루프 데스게임', 'Until Dawn', '1년 전, 여동생 멜라니가 흔적도 없이 사라진 후, 클로버는 친구들과 함께 그녀의 마지막 행적이었던 외딴 계곡을 찾아 나선다. 버려진 방문자 센터에서 하룻밤을 보내기로 한 그들은, 정체불명의 가면을 쓴 살인마에게 차례로 희생당한다. 그러나 죽음은 끝이 아니었다. 그들은 다시 그날 저녁으로 돌아오고, 매번 새로운 공포가 그들을 기다리고 있다. 죽음이 반복될수록 희망은 사라지고, 그들은 이 악몽에서 벗어나기 위해 반드시 새벽까지 살아남아야만 하는데...', 'https://image.tmdb.org/t/p/w500/vxg728iguFU0lgV4kw1T12n50xc.jpg', 'MOVIE'),(137, NULL, 1041613, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2024-07-17', '이매큘레이트', 'Immaculate', '순수하고 신실한 믿음을 가진 수녀 \'세실리아\'. 어느 비밀스러운 수녀원의 초청을 받아 낯선 생활에 적응해 가던 중 처녀의 몸으로 임신을 했다는 사실이 밝혀지고 기적의 주인공으로 추앙 받기 시작하는데… 순결한 수녀의 임신, 축복인가 저주인가!', 'https://image.tmdb.org/t/p/w500/p9XNkXNUOx30vwIxRoDx6KgmFDV.jpg', 'MOVIE'),(138, NULL, 726139, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'ko', '2024-07-12', '탈출: 프로젝트 사일런스', '탈출: 프로젝트 사일런스', '한치 앞도 구분할 수 없는 짙은 안개 속 붕괴 직전의 공항대교에 고립된 사람들이 그 안에 도사리고 있는 예기치 못한 위협으로부터 살아남기 위해 고군분투하는 이야기.', 'https://image.tmdb.org/t/p/w500/rXuSca6qEb4xPrSRT7XRzYCFbZB.jpg', 'MOVIE'),(140, NULL, 520763, '2026-01-29 12:23:21', '2026-01-29 12:23:21', 'en', '2021-06-16', '콰이어트 플레이스 2', 'A Quiet Place Part II', '실체를 알 수 없는 괴생명체의 공격으로 일상의 모든 것이 사라진 세상, 아이들 대신 죽음을 선택한 아빠의 희생 이후 살아남은 가족들은 위험에 노출된다. 갓 태어난 막내를 포함한 아이들과 함께 소리 없는 사투를 이어가던 엄마 에블린은 살아남기 위해 새로운 은신처를 찾아 집 밖을 나서지만, 텅 빈 고요함으로 가득한 바깥은 더 큰 위험이 도사리고 있다. 이들은 과연 고요함으로 가득한 세상 속을 무리 없이 걸어나갈 수 있을까.', 'https://image.tmdb.org/t/p/w500/6DoKA0l2TaHvw9BbP6YbMuAnxV3.jpg', 'MOVIE'),(141, NULL, 755, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '1998-09-05', '황혼에서 새벽까지', 'From Dusk Till Dawn', '은행털이범 세스 게코(조지 클루니)와 리치 형제는 멕시코로 안전하게 탈출하기 위해 목사 가족을 인질로 삼는다. 목사 가족의 트레일러에 몸을 숨겨 무사히 국경을 통과한 후, 이들은 은신처를 제공할 조직과의 접선을 위해 술집으로 들어간다. 술집 안으로 들어서자 무희들이 춤추는 모습이 보이고, 일행은 테이블에 앉아 술을 마신다. 술이 조금씩 오르는 중에 바텐더와 시비가 붙어 격투를 벌어지고, 두 형제는 총으로 종업원들을 쏴 버린다. 댄서들은 피를 보는 순간 흡혈귀의 본성을 드러내고, 죽은 줄 알았던 이들이 모두 흡혈귀로 변해 손님들을 공격하는데...', 'https://image.tmdb.org/t/p/w500/A2zS0TOyv0FjXm91CrkzBgrtw7X.jpg', 'MOVIE'),(143, NULL, 77823, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2004-09-17', '귀신이 산다', '귀신이 산다', '세방살이 삼대째 박필기 드디어 문패에 이름 석자 새기다! 3대를 이어온 셋방살이 설움에 \'네 집을 가져\'라는 아버지 유언을 인생목표로 사는 박필기. 낮에는 조선소 기사로 밤엔 대리운전으로 투잡스, 쓰리잡스를 뛰면서 결국 사회생활 10년만에 대출에 융자까지 보태 거제도 바닷가 이층집을 사는데 성공했으니... 이사 첫날 문패 박으며 온 동네 떠나가도록 울부짖었다! \"아버지...나 집 샀어요~~~ 엉엉~~\"  나보고 집을 나가라고? 여긴 우리집이거든... 넌 누구냐? 그러나 내 집을 마련했다는 기쁨도 잠시. 그런데, 부엌에 잘 꽂혀있던 식칼이 공중부양해 날라오고, 멀쩡했던 소파가 공격하질 않나, TV속 을 열연중이던 박영규가 필기를 노려보며 \'살고 싶으면 이집에서 나가!!\'라 윽박지르더니, 의 배두나처럼 TV밖으로 기어나오기까지... 이것이 무슨 귀신이 곡할 노릇! \"사람살려~~ 박필기 살려~~\" 이사 첫날... 그는 여관방 신세를 졌다.  하필이면... 왜? 우리집에 귀신이 사냐구~~~~~!! 경찰서로, 이웃에게로 귀신 곡할 사연을 호소해보지만... 필기만 몰랐던 그 집의 비밀이 있었으니 \"그 집에 귀신 살아요!!\" 재빨리 급매모드로 변신하지만 흥정은커녕 돈을 얹어줘도 안 산다니... 은행 이잣날은 다가오고 언제까지 제집 두고 여관방신세 질 수도 없고... 환장할 박필기, 마침내 귀신과의 전면전을 선포하는데...', 'https://image.tmdb.org/t/p/w500/aUxZM5G7bwmWs1d3UZugVxnC9sc.jpg', 'MOVIE'),(146, NULL, 838209, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2024-02-22', '파묘', '파묘', '미국 LA, 거액의 의뢰를 받은 무당 화림과 봉길은 기이한 병이 대물림되는 집안의 장손을 만난다. 조상의 묫자리가 화근임을 알아챈 화림은 이장을 권하고, 돈 냄새를 맡은 최고의 풍수사 상덕과 장의사 영근이 합류한다. 절대 사람이 묻힐 수 없는 악지에 자리한 기이한 묘. 상덕은 불길한 기운을 느끼고 제안을 거절하지만, 화림의 설득으로 결국 파묘가 시작되고… 나와서는 안될 것이 나왔다.', 'https://image.tmdb.org/t/p/w500/tw0i3kkmOTjDjGFZTLHKhoeXVvA.jpg', 'MOVIE'),(147, NULL, 360551, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2015-11-05', '검은 사제들', '검은 사제들', '2015년 서울, 뺑소니 교통사고 이후 의문의 증상에 시달리는 한 소녀. 잦은 돌출 행동으로 교단의 눈 밖에 난 김신부는 모두의 반대와 의심 속, 소녀를 구하기 위한 자신만의 계획을 준비한다. 이를 위해선 모든 자격에 부합하는 또 한 명의 사제가 필요한 상황, 모두가 기피하는 가운데 신학생인 최부제가 선택되고, 그는 김신부를 돕는 동시에 감시하라는 미션을 받게 된다. 그리고 마침내 소녀를 구할 수 있는 단 하루의 기회, 김신부와 최부제는 모두의 목숨을 잃을 수도 있는 위험한 예식을 시작하는데…', 'https://image.tmdb.org/t/p/w500/3zYZ5hZUNHwgObdqbDYlS8l24FE.jpg', 'MOVIE'),(148, NULL, 433808, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2017-10-11', '리추얼: 숲속에 있다', 'The Ritual', '스웨덴 원시림으로 하이킹을 간 네 명의 오랜 친구. 마냥 신날 수만 없는 이들의 신경이 더욱 곤두서게 된 까닭은 무엇인가. 이유는 하나, 이 숲에 뭔가 있다.', 'https://image.tmdb.org/t/p/w500/9022CYEGqYETCeXN1oE3uwYJWub.jpg', 'MOVIE'),(149, NULL, 523593, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2018-09-12', '물괴', '물괴', '중종 22년, 거대한 물괴가 나타나 백성들을 공격하기 시작한다. 물괴와 마주친 백성들은 그 자리에서 잔인하게 죽임을 당하거나 살아남아도 역병에 걸려 끔찍한 고통 속에 결국 죽게 되고, 한양은 삽시간에 공포에 휩싸인다. 모든 것이 자신을 몰아세우는 영의정과 관료들의 계략이라 여긴 중종은 옛 내금위장 윤겸을 궁으로 불러들여 수색대를 조직한다. 윤겸과 오랜 세월을 함께한 성한과 외동딸 명, 그리고 왕이 보낸 허선전관이 그와 함께 한다. 물괴를 쫓던 윤겸과 수색대는 곧 실로 믿을 수 없는 거대한 비밀을 마주하게 되는데…', 'https://image.tmdb.org/t/p/w500/mV0E3t1AtaYHlvM6HNOTJ1SmYjt.jpg', 'MOVIE'),(150, NULL, 546121, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2020-11-20', '런', 'Run', '태어날 때부터 장애 때문에 휠체어를 타고 외딴 집에서 엄마와 함께 살며 일상을 보내는 클로이. 딸을 사랑으로 돌보는 엄마 덕분에 힘들지만 매일을 긍정적으로 살아간다. 그러던 어느 날 식탁에 놓인 장바구니에서 하나의 물건을 발견하게 되고 믿었던 모든 일상이 흔들리기 시작하는데…', 'https://image.tmdb.org/t/p/w500/swMFgTEcDUz7MCvWfYIIiZ8PatU.jpg', 'MOVIE'),(153, NULL, 405774, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2018-12-21', '버드 박스', 'Bird Box', '미지의 재앙이 인류를 휩쓴다. 세상이 뒤집힌 지 5년. 용케 살아남은 여자와 그녀의 아이들이 또다시 위기에 처한다. 안전한 곳을 향해, 그들은 필사적인 모험을 감행한다.', 'https://image.tmdb.org/t/p/w500/dB7jNL5I3hb7b1zsGD5OEoSl2BQ.jpg', 'MOVIE'),(155, NULL, 4233, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '1999-06-05', '스크림 2', 'Scream 2', '2년전, 우즈보로를 피로 물들였던 사건을 다룬 게일의 책이 베스트셀러에 진입하면서 시드니 엄마의 살인범으로 기소된 카튼이 석방된다. 게다가 게일의 책이 영화로 만들어져, 첫 시사회를 갖던 중 두명의 대학생이 무참히 살해된다. 또다시 찾아온 공포, 비명소리는 극장에서 다시 시작된다. 끔찍한 악몽을 딛고 이제 대학생으로 평범한 삶을 찾아가던 시드니에게 또다시 전화벨이 울린다. 그녀의 곁에는 공포영화광 랜디, 다정한 남자친구 데릭, 더 큰 특종을 노리며 다가온 리포터 게일, 절룩거리며 끝없이 주위를 배회하는 듀이, 엄마의 살인범으로 기소됐다 풀려난 카튼, 그리고 호기심으로 몰려든 수많은 사람들이 있다. 그러나 시드니를 도우려는 사람들이 많아질수록 비명소리는 커져만 간다. 그들 모두는 희생자일수도 있고, 동시에 용의자일수도 있다. 자신외에는 아무도 믿을 수 없는 시드니, 과연 이 살인극을 벌이는 진범은 누구이며 도대체 무슨 이유로?', 'https://image.tmdb.org/t/p/w500/XoIlgmMwbTC4SnmcxJhf8JNFgs.jpg', 'MOVIE'),(156, NULL, 22536, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2009-04-30', '박쥐', '박쥐', '정체불명의 피를 수혈 받고 뱀파이어가 된 신부 상현. 피를 원하는 욕구와 신앙심 사이에서 갈등하던 그는 우연히 어린 시절 친구 강우와 그의 아내 태주를 만나면서 인간적 욕망에까지 눈뜨게 된다. 상현은 태주의 묘한 매력에 빠져 쾌락을 갈구하고 태주는 히스테리컬한 시어머니와 무능력한 남편에게 억눌렸던 욕망을 깨워준 상현에게 집착한다. 점점 더 대담해져만 가던 둘의 사랑은 급기야 상현이 뱀파이어라는 사실을 알게 된 태주가 자신의 남편을 죽이자고 제안하고, 상현이 제안을 받아들이면서 새로운 국면에 접어드는데...', 'https://image.tmdb.org/t/p/w500/2CoIYuNwGmdhsV5CM8jRJ2sAZKe.jpg', 'MOVIE'),(157, NULL, 4234, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2000-04-29', '스크림 3', 'Scream 3', '시드니(니브 캠벨)는 아직도 과거 죽은 어머니의 환영 때문에 놀라곤 한다. 안전을 위해 가명을 사용하고 있는 그녀는 전화 공포에 시달리는 여성들에게 상담을 해주며 살아간다. 어느 날 익명의 전화 한 통이 걸려오고 그녀는 최근 헐리우드의  촬영 현장에서 살인 사건이 발생했다는 소식을 듣는다. 시드니는 살인자가 그녀의 죽은 엄마 모린의 사진을 남기고 사라졌다는 소식을 듣고 현장으로 달려간다. 계속해서 모린의 사진이 발견되면서 에 출연 중인 배우들이 차례로 죽어간다. 이 살인 사건을 조사하려는 수사관과 기자들이 몰려오고, 시드니는 기자가 된 게일과 다시 한 번 만난다. 사건의 전모가 밝혀지면서 숨겨졌던 시드니의 과거 비밀이 드러나는데...', 'https://image.tmdb.org/t/p/w500/qpH8ToZVlFD1bakL04LkEKodyDI.jpg', 'MOVIE'),(159, NULL, 977155, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2023-02-22', '마루이 비디오', '마루이 비디오', '국내에서 일어난 사건 영상 중 그 수위가 높아 외부로 유출되면 안 되는 영상물 마루이 비디오. 검찰청 지하 보관소에 봉인된 비디오에 대한 소문을 들은 김수찬 PD는 이를 입수해 다큐멘터리를 제작하기로 하는데… 영상 속에 담긴 1992년 동성장 여관방 살인사건과 1987년 아미동 일가족 살인사건의 진실은 과연 무엇인가?', 'https://image.tmdb.org/t/p/w500/oVWfkaztIW6QEJlBJ66kYpi9Nmj.jpg', 'MOVIE'),(162, NULL, 632727, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2022-02-18', '텍사스 전기톱 학살 2022', 'Texas Chainsaw Massacre', '텍사스의 한 유령 도시. 이곳에 생기를 불어넣겠다는 꿈을 안고 도착한 인플루언서들. 이들이 악명 높은 살인마 \'살가죽 가면\'과 마주친다. 《텍사스 전기톱 학살》의 속편.', 'https://image.tmdb.org/t/p/w500/xVT66OFGCoHXWEzmapPNS1rFX0J.jpg', 'MOVIE'),(163, NULL, 535370, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2018-07-25', '신비아파트: 금빛 도깨비와 비밀의 동굴', '신비아파트: 금빛 도깨비와 비밀의 동굴', '100년이 넘은 신비아파트에 살고 있는 \'하리\', \'두리\' 남매와 102살 도깨비 \'신비\'는 우연히 숲 속에 숨겨진 비밀의 동굴을 발견한다. 동굴의 힘에 휩쓸려 22년 전 과거, 1996년으로 가게 된 \'하리\', \'두리\', \'신비\'는 아파트가 사라진 마을에서 어린 시절의 엄마 \'유지미\'를 만난다.  \'유지미\'의 보물지도를 따라 함께 모험을 떠나게 된 \'하리\', \'두리\', \'신비\'는 금빛 도깨비 \'금비\'를 만나게 되고, 이들은 함께 오싹한 모험을 시작하는데...!  올 여름, 대세 애니메이션 \'신비아파트\'의 첫 스크린 데뷔! 오싹한 재미와 뭉클한 감동이 극장에서 펼쳐진다!', 'https://image.tmdb.org/t/p/w500/v9uKB2LhTGeVI18KcxdOA0uu9jU.jpg', 'MOVIE'),(164, NULL, 2675, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2002-08-08', '싸인', 'Signs', '미국 펜실베니아 주 벅스 카운티에 소재한 그래함 헤스(멜 깁슨)의 농장 주택! 집안에서 바라본 창밖 세상에는 평화로운 기운만 가득하다. 그런데 바로 그 때 2층 창문의 투명한 유리가 물결치듯이 잠시 일렁이는 것이 아닌가! 그 유리창을 통해 누가 창밖을 보고 있었던 것일까? 바로 그 날 아침 그래함(멜 깁슨)은 아이들과 애완견의 비명소리에 놀라 잠에서 깨어나 밖으로 달려 나간다. 그리곤 경악을 금치 못한다.', 'https://image.tmdb.org/t/p/w500/zQywNOfCoJfGigJoBdjOGLsOW38.jpg', 'MOVIE'),(165, NULL, 572151, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2019-02-13', '기묘한 가족', '기묘한 가족', '망해버린 주유소의 트러블메이커 가장 \'만덕\'은 우연히 만난 좀비를 집안에 들인다. 여타 좀비와 달리 반반한 외모, 말귀 알아듣는 ‘쫑비’를 보며 저마다의 속셈으로 패밀리 비즈니스를 꿈꾸는 가족. 리더인 맏며느리 \'남주\'를 중심으로 행동대장 장남 \'준걸\'과 브레인 차남 \'민걸\' 에너지 담당 막내 \'해걸\'에 물리면 죽기는커녕 더 젊어지는 좀비 \'쫑비\'까지! 이들의 기막힌 비즈니스는 조용했던 동네를 별안간 혈기 왕성한 마을로 만들어버리는데...', 'https://image.tmdb.org/t/p/w500/jQ4CMTvz7s5R6csiu3RH7TVNfS9.jpg', 'MOVIE'),(166, NULL, 503736, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2021-05-21', '아미 오브 더 데드', 'Army of the Dead', '좀비들이 점령한 라스베이거스, 최후의 도박이 시작된다. 도시의 격리 구역으로 침투하는 용병 무리. 사상 최고의 강도 작전은 어떤 결말을 맞을 것인가.', 'https://image.tmdb.org/t/p/w500/srRZnqkJI24qrs2whOJ1rBbo1Fv.jpg', 'MOVIE'),(167, NULL, 614696, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2020-06-24', '#살아있다', '#살아있다', '원인불명 증세의 사람들의 공격에 통제불능에 빠진 도시. 영문도 모른 채 잠에서 깬 준우는 아무도 없는 집에 혼자 고립된 것을 알게 된다. 데이터, 와이파이, 문자, 전화 모든 것이 끊긴 채 고립된 상황. 연락이 두절된 가족에 이어 최소한의 식량마저 바닥이 나자 더 이상 버티기 힘들어진 준우. 하지만 그 순간 건너편 아파트에서 누군가 시그널을 보내온다. 또 다른 생존자 유빈이 아직 살아있음을 알게 된 준우는 함께 살아남기 위한 방법을 찾아 나서는데...', 'https://image.tmdb.org/t/p/w500/zb06eXz3Pg5JzytPnMFb3cIDV7B.jpg', 'MOVIE'),(168, NULL, 800815, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2023-01-06', '페일 블루 아이', 'The Pale Blue Eye', '1830년 웨스트포인트 육군사관학교.  겨울의 희뿌연 이른 아침, 한 생도가 죽은 채로 발견된다.  그런데 시신이 시체안치소로 옮겨진 후, 이 비극적 사건의 잔혹함이 드러나는데.  생도의 심장이 능숙한 솜씨로 제거되어 있었던 것.  신생 사관학교가 씻을 수 없는 오명을 입을 것을 우려한 학교장은  지역의 은퇴 형사 오거스터스 랜도어(크리스천 베일)에게 사건 해결을 의뢰한다.  하지만 생도들의 침묵 규약으로 수사에 진척이 없자,  랜도어는 사건 해결에 협조할 독자적인 성향의 인물을 따로 구하는데.  군대의 엄격함을 경멸하고 시를 사랑하는 특이한 생도인 그 인물은  바로 에드거 앨런 포(해리 멜링)였다.', 'https://image.tmdb.org/t/p/w500/hnwq7IbbmBVLGaXcdoTiEk4Z63q.jpg', 'MOVIE'),(169, NULL, 204260, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2013-06-27', '더 웹툰: 예고살인', '더 웹툰: 예고살인', '그녀의 웹툰대로 살인사건이 벌어진다!  포털 사이트 웹툰 편집장 사망 사건 현장. 사건을 담당한 형사 기철은, 피해자가 사망 당시 보고 있던 웹툰과 똑같이 죽어있음을 확인하고 그 웹툰을 그린 작가 지윤을 찾아간다. 혐의를 부인하는 지윤, 하지만 얼마 뒤 그녀의 웹툰과 동일한 방식으로 살해된 두 번째 피해자가 나타나고 기철은 사건 현장에 있던 지윤을 유력한 범인으로 체포한다. 결국 취조를 받던 지윤은 자신의 웹툰에 대한 충격적인 고백을 시작하는데…', 'https://image.tmdb.org/t/p/w500/dNGdA2n1YAGnS3ozhXE9nZxwFZR.jpg', 'MOVIE'),(170, NULL, 38321, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2011-06-09', '프리스트', 'Priest', '신의 규율에 의해 통제되는 거대한 미래도시. 전사가 된 신부 프리스트(폴 베타니)는 인류를 위협하는 존재들과 수 세기에 걸친 전쟁을 승리로 이끌고 돌아온다. 하지만 그의 능력을 두려워한 신의 조직에게 버림받아 비참한 삶을 살아 간다. 어느 날 다시 부활한 뱀파이어의 습격으로 가족을 잃게 된 프리스트는 신과의 서약을 깨고 자신의 모든 걸 걸고 복수에 나서게 되는데…', 'https://image.tmdb.org/t/p/w500/iyXl7zW8U1AVBxF9whch2ylIwIr.jpg', 'MOVIE'),(171, NULL, 1169340, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2024-03-29', '씬', '씬', '실험적 요소로 내로라하는 해외 유수 영화제에서 이름을 알린 유명 감독 ‘휘욱’은 춤을 소재로한 새로운 작품 촬영을 위해 신인 배우 ‘시영’, ‘채윤’과 함께 폐교 옥상에서 촬영을 시작한다. 파격적이고 거친 동작의 춤사위로 촬영이 시작되자 이내 배우와 제작진들은 오묘한 기운에 휩싸이고 촬영 현장은 순식간에 아비규환이 되어 버린다. 그리고, 깨어나지 말아야할 존재 ‘그것’과 마주하게 되는데…', 'https://image.tmdb.org/t/p/w500/3bD4PlunjMXne1FX2zb9ktZDPXs.jpg', 'MOVIE'),(172, NULL, 1244810, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2024-11-06', '아메바 소녀들과 학교괴담: 개교기념일', '아메바 소녀들과 학교괴담: 개교기념일', '영화감독이 꿈인 지연과 친구들은 우연히 방송반 캐비닛에서 1998년에 촬영 된 비디오테이프를 보게 된다. 그 날 이후, 지연과 친구들은 동시에 기이한 현상을 겪고, 비디오테이프의 정체를 쫓다 학교괴담을 알게 되는데…', 'https://image.tmdb.org/t/p/w500/c1DGRZAIaQh0sJW780YISttOepk.jpg', 'MOVIE'),(175, NULL, 923612, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'ko', '2022-01-27', '효자', '효자', '엄마가 돌아가시고 얼마 지나지 않아 닥친 태풍 소식에 5명의 형제들은 함께 산소를 찾아간다  그런데, 이게 도대체 무슨 일? 부서진 관 사이로 엄마의 시신이 온데간데 사라졌다?  알 수 없는 기막힌 상황에 집으로 돌아오자 좀비로 변한 엄마가 이들을 기다리는데...', 'https://image.tmdb.org/t/p/w500/dvtWec87XPvFb6wJOesuLDBHwj1.jpg', 'MOVIE'),(176, NULL, 926899, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2022-01-14', '더 하우스', 'The House', '어느 가난한 가족, 불안에 시달리는 개발업자, 그리고 화가 잔뜩 난 집주인까지. 미스터리한 집에서 여러 세대에 걸쳐 일어나는 사건을 다룬 블랙 코미디 애니메이션.\r 《더 하우스》는 한 채의 집과 그 집에 사는 사람들에 관한 세 가지 초현실적인 이야기를 담은 독특한 다크 코미디 앤솔러지이다. 독립 스톱모션애니메이션 업계 대표 주자들인 에마 드스와프, 마르크 룰스, 니키 린드로트 본바르, 펄로마 베이자가 연출을 맡고, 넥서스 스튜디오(Nexus Studios)가 제작했다.', 'https://image.tmdb.org/t/p/w500/gQiY7XhkiaKwiHzZYxZlpfWVG4q.jpg', 'MOVIE'),(177, NULL, 434555, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2018-11-29', '포제션 오브 한나 그레이스', 'The Possession of Hannah Grace', '불명예스럽게 경찰을 그만두고 병원 시체공시소에서 일하게 된 전직 경찰에게 어느날 잔혹하게 살해된 시체 한구가 오게 되는데 그 시체가 깨어나면서 공포를 맞이하게 되고 사악한 실체를 맞이하게 되는데...', 'https://image.tmdb.org/t/p/w500/hDDb0H0uJp2wjoJBbBHbKlYRbug.jpg', 'MOVIE'),(178, NULL, 424121, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2018-10-12', '복수의 사도', 'Apostle', '1905년, 토머스 리처드슨은 납치된 여동생 제니퍼를 구하려고 외딴 섬에 침입한다. 정체불명의 사이비 종교 집단이 제니퍼를 풀어주는 대가로 거액의 몸값을 요구한 상태다. 토머스가 비밀과 거짓말로 이뤄진 종교 집단의 실체를 깊숙이 파헤치면서, 이단 세력은 그에게 미끼를 던진 것을 곧 후회하게 된다.', 'https://image.tmdb.org/t/p/w500/rd269f2Yftxxam3EOJPYVwrvjIJ.jpg', 'MOVIE'),(180, NULL, 456740, '2026-01-29 12:23:22', '2026-01-29 12:23:22', 'en', '2019-04-10', '헬보이', 'Hellboy', '\'헬보이\' 자신이 소속된 B.P.R.D의 임무로 영국의 한 비밀 단체의 괴수 사냥을 도우러 갔지만 되려 공격을 당하고, 곧 영국에서 어마어마한 일이 벌어지고 있다는 것을 알게 된다. 서기 566년, 아서왕에게 패하고 몸이 7조각으로 나뉘어 봉인된 \'블러드 퀸\'을 다시 부활시켜 인류를 파멸시키려는 초자연적 빌런들에 의해 영국은 물론 전 세계가 위험에 빠지게 된다. 헬보이는 이들에 맞서 인류를 위험으로부터 구해야만 하는데…', 'https://image.tmdb.org/t/p/w500/8LcENvKEkaikg9ere2xZ9taiFaZ.jpg', 'MOVIE'),(182, NULL, 803796, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2025-10-31', '케이팝 데몬 헌터스', 'KPop Demon Hunters', '케이팝 슈퍼스타 루미, 미라, 조이. 매진을 기록하는 대형 스타디움 공연이 없을 때면 이들은 또 다른 활동에 나선다. 바로 비밀 능력을 이용해 팬들을 초자연적 위협으로부터 보호하는 것.', 'https://image.tmdb.org/t/p/w500/5fqcLmrgVDicMuGLOa9PKErFP72.jpg', 'MOVIE'),(183, NULL, 701387, '2026-01-29 12:23:23', '2026-01-29 12:23:24', 'en', '2025-11-05', '부고니아', 'Bugonia', '벌들은 사라지고, 지구는 병들고 있고, 인류는 고통받고 있다. 거대 바이오 기업의 물류센터 직원인 테디는 이 모든 것이 은밀하게 진행되고 있는 외계인의 지구침공 계획 때문이고, 사장 미셸이 안드로메다에서 온 외계인이라고 굳게 믿는다. 오랜 준비 끝, 함께 사는 사촌 동생 돈과 함께 결국 미셸을 납치하는데 성공한 테디. 그는 지하실에 미셸을 감금한 채 지구를 찾아온 이유와 앞으로의 음모를 캐묻지만 자신은 외계인이 아니라는 말만 반복하는 미셸. 과연 테디는 미셸에게서 원하는 답을 얻고 지구를 지킬 수 있을까?', 'https://image.tmdb.org/t/p/w500/ko6Wxr4sB9RM3pJb5JlWPqiSOIp.jpg', 'MOVIE'),(186, NULL, 812583, '2026-01-29 12:23:23', '2026-01-29 12:23:24', 'en', '2025-12-12', '나이브스 아웃: 웨이크 업 데드 맨', 'Wake Up Dead Man: A Knives Out Mystery', '브누아 블랑이 탐정 인생을 통틀어 가장 위험한 사건으로 돌아온다.어두운 과거를 지닌 작은 마을의 성당. 그곳에서 불가사의한 범죄가 발생한다. 그러자 브누아 블랑 탐정이 신실한 젊은 신부와 함께 수사에 나선다.', 'https://image.tmdb.org/t/p/w500/qFXkslzkBIihZnwyYal9WnQ9OTe.jpg', 'MOVIE'),(187, NULL, 496243, '2026-01-29 12:23:23', '2026-01-29 12:23:24', 'ko', '2019-05-30', '기생충', '기생충', '전원 백수로 살 길 막막하지만 사이는 좋은 기택 가족. 장남 기우에게 명문대생 친구가 연결시켜 준 고액 과외 자리는 모처럼 싹튼 고정수입의 희망이다. 온 가족의 도움과 기대 속에 박 사장 집으로 향하는 기우. 글로벌 IT기업의 CEO인 박 사장의 저택에 도착하자 젊고 아름다운 사모님 연교와 가정부 문광이 기우를 맞이한다. 큰 문제 없이 박 사장의 딸 다혜의 과외를 시작한 기우. 그러나 이렇게 시작된 두 가족의 만남 뒤로, 걷잡을 수 없는 사건이 기다리고  있는데.....', 'https://image.tmdb.org/t/p/w500/jjHccoFjbqlfr4VGLVLT7yek0Xn.jpg', 'MOVIE'),(189, NULL, 808, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2001-07-06', '슈렉', 'Shrek', '성 밖 늪지대에 사는 엄청나게 못생기고 무지무지 큰 괴물 슈렉. 지저분한 진흙으로 샤워를 즐기고 동화책은 화장실 휴지 삼아 쓰는 그는 혼자만의 시간을 즐긴다.  그러던 어느 날, 자신만의 고요한 안식처에 백설공주, 신데렐라, 빗자루를 타고 다니는 마녀, 피리부는 아저씨, 피터팬, 피노키오 등등.. 동화속의 주인공들이 모두 쳐들어온다. 그 중에서도 가장 귀찮은 건 쉴새없이 떠들어대는 당나귀 덩키. 알고보니 얼굴이 몸의 반을 차지하는 1m도 안되는 숏다리 파콰드영주가 동화속의 주인공들을 다 쫓아낸것. 결국 슈렉은 파콰드영주와 담판을 지으러 떠난다.  하지만 일은 이상하게 꼬여 결국 파콰드영주 대신 불뿜는 용의 성에 갇힌 피오나 공주를 구하러 떠나게 되는데..', 'https://image.tmdb.org/t/p/w500/hABnmgdAU3u6Nu61b9GUGaOseVl.jpg', 'MOVIE'),(190, NULL, 680, '2026-01-29 12:23:23', '2026-01-29 12:23:24', 'en', '1994-09-10', '펄프 픽션', 'Pulp Fiction', '펌프킨와 허니 버니가 레스토랑에서 강도 행각을 벌이기 시작한다. 빈센트와 그 동료 쥴스는 두목의 금가방을 찾기 위해 다른 건달이 사는 아파트를 찾아간다. 마르셀러스는 부치에게 돈을 주며 상대 선수에게 져 주라고 하지만 부치는 상대 선수를 때려 눕히고 도망치다, 어릴 때 아버지에게 물려받은 시계를 찾기 위해 아파트로 향한다. 아무런 상관 없이 보이는 이 사건들이 서로 얽히고 섥히면서 예상치 못한 인과관계가 만들어지는데...', 'https://image.tmdb.org/t/p/w500/6lXRHGoEbnnBUKsuqpL9JxD4DzT.jpg', 'MOVIE'),(191, NULL, 519182, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2024-07-24', '슈퍼배드 4', 'Despicable Me 4', '슈트-업 하고 악당 전담 처리반 AVL이 된 에이전트 미니언즈와 미니언즈 만큼 귀여운 그루 주니어가 태어나면서 더욱 완벽해진 그루 패밀리. 이들 앞에 과거 그루의 고등학교 동창이자 그에게 체포당했던 빌런 맥심이 등장하고, 오직 그루를 향한 복수심에 불타올라 탈옥까지 감행한 맥심은 그루 패밀리의 뒤를 바짝 추격하며 위협을 가하기 시작하는데... 과연 에이전트 미니언즈와 그루 패밀리는 맥심을 막아낼 수 있을까?', 'https://image.tmdb.org/t/p/w500/vZmCFVff9JySHTUp9zbYUIAcxzc.jpg', 'MOVIE'),(193, NULL, 546554, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2019-12-04', '나이브스 아웃', 'Knives Out', '미스터리 소설의 대가인 작가 할란이 자신의 85살 생일에 자신의 방에서 날카로운 단검으로 목이 그인 채 발견된다. 외딴 저택에 모인 할란의 간병인과 자식 내외, 그리고 3세들은 유산 상속을 놓고 대거 혼란에 빠진다. 파견된 형사들은 가족과의 면담을 할 수록 자살로 의견이 모이지만, 면담 중 멀찍이 떨어져 상황을 전망하는 푸른 눈의 사내는 형사들마저 압도하며 심문을 주도해나간다. 남자의 이름은 바로 브누아 블랑. 챔피언 사건을 해결해서 이름이 높아진 유명한 사립탐정이다.', 'https://image.tmdb.org/t/p/w500/7brBiaaH1sToGV1YBi5EIUnyjo0.jpg', 'MOVIE'),(194, NULL, 10192, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2010-07-01', '슈렉 포에버', 'Shrek Forever After', '슈렉이 아름다운 공주 피오나와 겁나먼 왕국을 구해낸 이후. 그들도 오래오래 행복하게 살았...더라면 참 좋았을텐데! 과연 슈렉에게도 모두가 바라던 해피엔딩이 올까?  한 가정의 평범한 아빠와 남편으로 반복되는 일상에 따분함을 느끼던 슈렉은 마을 사람들에게 겁을 주고, 진흙 목욕도 실컷 하던 시절의 자유를 꿈꾸게 된다. ‘단 하루라도 자유로워진다면 죽어도 한이 없겠어’라며 일탈을 꿈꾸던 슈렉은 ‘겁나먼 왕국’을 차지하려는 악당 럼펠의 그럴싸한 계략에 속아 넘어가 ‘완전 딴판 겁나먼 세상’에 떨어지고 만다. 완전 딴판으로 바뀌어버린 세상에서 절친 동키는 슈렉을 미친 괴물 취급하며 줄행랑 치고, 단 하나의 사랑 피오나는 하이킥을 날리고, 장화신은 고양이는 더 이상 장화를 신지 않는 D라인의 고양이가 되어 있다. 친구들과 왕국, 그리고 하나뿐인 진실한 사랑을 되찾기 위한 슈렉의 마지막 이야기가 시작된다!', 'https://image.tmdb.org/t/p/w500/t3FNCqPBgRK9jYTzLGWptIdpD3O.jpg', 'MOVIE'),(195, NULL, 953, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2005-07-14', '마다가스카', 'Madagascar', '센트럴파크 동물원의 인기절정 뉴요커 4인방  사자 알렉스(벤 스틸러)는 스포트라이트를 한 몸에 받는 뉴욕 센트럴파크 동물원 최고의 인기 스타. 타고난 품종은 정글의 왕이지만 사실 알렉스는 동물원 인기 스타인 자신을 자랑스러워하고 정글 구경은 한 번도 해 본 적 없는 정통 뉴욕 토박이다.  알렉스의 친구들인 얼룩말 마티(크리스 록)와 기린 멜먼(데이비드 쉬머), 하마 글로리아(제이다 핀켓 스미스)도 온실 속 화초처럼 동물원의 안락한 생활이 익숙하기만 한데...  탈출은 꿈꾼 적도 없는 데 미지의 정글 마다가스카로?!  그러던 어느 날, 호기심 많은 마티가 그들의 고향 남극으로 탈출기회만을 노리는 정체불명 펭귄 특공대의 꾐에 빠져 야생에 대한 동경을 안고 외출을 시도한다. 알렉스와 친구들은 사라진 마티를 찾기 위해 동물원 밖으로 나가게 되고, 사람들에게 발견된 동물 4인방(사실은 뉴요커 4인방)은 갑갑한 동물원 탈출을 모의했다는 오해 아닌 오해를 받은 채 아프리카로 향하는 배에 오르게 되고...  정글보다 도시가 더 좋은 뉴요커 4인방의 정글 탈출기!  뉴요커 4인방이 포획된 배를 남극을 향한 배로 오인한 펭귄 특공대는 재빠르게 선박을 접수하고 항로를 바꾸는 사이, 4인방이 갇혀 있던 상자가 바다로 떨어지면서 알렉스와 친구들은 미지의 정글 마다가스카에 표류하게 된다.  지금까지 안락한 뉴요커의 삶을 살아온 이들이 과연 거친 야생의 정글 마다가스카에서 살아갈 수 있을 것인가? 아니면 다시 센트럴파크의 동물원으로 돌아갈 것인가?  정글보다 도시가 더 좋은 뉴요커 4인방의 험난한 정글 탈출기는 이제부터 시작된다!!', 'https://image.tmdb.org/t/p/w500/7BeMHBgS6nUaxj6w0hGhsiK827c.jpg', 'MOVIE'),(197, NULL, 466272, '2026-01-29 12:23:23', '2026-01-29 12:23:25', 'en', '2019-09-25', '원스 어폰 어 타임 인… 할리우드', 'Once Upon a Time... in Hollywood', '자유의 바람이 불던 1969년 할리우드, 잊혀져 가는 액션스타 릭 달튼과 그의 스턴트 배우 겸 매니저인 클리프 부스는 과거의 영광을 되찾기 위해 고군분투하지만 새로운 스타들에 밀려 큰 성과를 거두진 못한다. 어느 날 릭의 옆집에 할리우드에서 가장 핫한 로만 폴란스키 감독과 배우 샤론 테이트 부부가 이사 오자 릭은 새로운 기회가 생길 수도 있다고 기뻐하지만 인사조차 나누지 못한다. 형편상 더 이상 함께 일할 수 없게 된 릭과 클리프는 각자의 길을 가기로 하고 릭의 집에서 술을 거나하게 마시던 중 뜻하지 않은 낯선 방문객을 맞이하게 되는데…', 'https://image.tmdb.org/t/p/w500/1F2rDT1oNdvMyXF7gxbGxaXCzrz.jpg', 'MOVIE'),(199, NULL, 490132, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2019-01-09', '그린 북', 'Green Book', '1962년 미국, 입담과 주먹만 믿고 살아가던 토니 발레롱가는 교양과 우아함 그 자체인 천재 피아니스트 돈 셜리의 운전기사 면접을 보게 된다. 백악관에도 초청되는 등 미국 전역에서 콘서트 요청을 받으며 명성을 떨치고 있는 돈 셜리는 위험하기로 소문난 미국 남부 투어 공연을 떠나기로 결심하고, 투어 기간 동안 자신의 보디가드 겸 운전기사로 토니를 고용한다. 거친 인생을 살아온 토니와 교양과 기품을 지키며 살아온 돈. 생각, 행동, 말투, 취향까지 달라도 너무 다른 두 사람은 그들을 위한 여행안내서 그린북에 의존해 특별한 남부 투어를 시작하는데...', 'https://image.tmdb.org/t/p/w500/dyqQ12gZGwl5Y0R9UsLBDkZWOUA.jpg', 'MOVIE'),(201, NULL, 2280, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '1989-07-15', '빅', 'Big', '13세 난 개구쟁이 조쉬는 어느날 축제에 놀러갔다가 \'졸타\'라는 기계에 어른이 되고 싶다는 소원을 빌자 다음날 정말 30세의 어른으로 변한다. 커진 조쉬를 본 어머니가 강간범으로 알고 칼을 들고 덤벼들자 어쩔 수 없이 집을 나오게 된다.  일자리를 찾다가 멕밀런 완구회사의 전산과 말단 직원으로 취직한 조쉬는 어린이의 시각에서 어린이가 원하는 장난감의 아이템을 기획해냄으로서 승진을 거듭하게 된다.  갑자기 어른이 되버린 어린 소년 조쉬가 어른의 세계에서 겪게되는 모험과 사랑, 그리고 사업의 세계! 어른이 되면 뭐든 할수 있을 거라는 꿈을 꾸었던 조쉬가 현실과 부딪히면서 갖가지 해프닝이 벌어 진다.  완구회사의 간부 수잔은 그가 평범한 사람들과는 달리 어린 아이처럼 행동하자 호감을 갖고 마침내 두 사람은 사랑하는 사이로 발전한다. 그러나 조쉬는 점점 어린 시절과 집에 대한 향수를 느끼게 되고 자신만을 기다리는 어머니를 만나고 싶어진다.', 'https://image.tmdb.org/t/p/w500/eh6yFxb7DOFLwP7gBWKbk87Gy8J.jpg', 'MOVIE'),(202, NULL, 661374, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2022-12-23', '나이브스 아웃: 글래스 어니언', 'Glass Onion: A Knives Out Mystery', '가장 아끼는 친구들을 본인의 사유지인 그리스의 섬으로 초대한 IT계의 억만장자 마일스 브론. 하지만 머지않아 이곳이 마냥 낙원이 아니라는 사실이 드러난다.', 'https://image.tmdb.org/t/p/w500/lrgmo1qluO9c2qdBduiu412fRDS.jpg', 'MOVIE'),(203, NULL, 810, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2007-06-06', '슈렉 3', 'Shrek the Third', '마침내 평온을 되찾은 ‘겁나먼 왕국’.  이제 자신들의 늪에 돌아가 둘만의 달콤한 생활을 꿈꾸던 슈렉과 피오나에게 엄청난 태클이 들어온다. 피오나의 아버지 해롤드 왕이 위독해져 슈렉과 피오나가 왕위를 계승해야 하는 상황이 벌어진 것.  해롤드 왕은 슈렉에게 왕위 계승 다음 서열인 피오나의 먼 친척 ‘아더 왕자’를 찾아오면 늪으로 돌아가도 좋다는 타협책을 내놓는다. 슈렉은 동키, 장화 신은 고양이와 함께 아더 왕자를 찾기 위한 머나먼 여정에 나서고….  한편, 슈렉이 없는 틈을 ‘프린스 챠밍’은 동화속 악당을 모아 겁나먼 왕국을 차지하려는 음모를 꾸미고, 왕국에 남아있는 피오나 등 5공주(백설공주, 신데렐라, 잠자는 숲속의 공주, 라푼첼)와 릴리안 왕비는 힘을 합쳐 프린스 챠밍에 맞서는데….  ‘모두가 王이 되고자 하는 시대’에 ‘스스로 王을 포기하려는’ 슈렉. 자신이 원하는 삶을 누리는 ‘진정한 王’이 될 수 있을까?', 'https://image.tmdb.org/t/p/w500/s8VjSynQ1wGwkALwmn5nsifivyq.jpg', 'MOVIE'),(206, NULL, 20352, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2010-09-16', '슈퍼배드', 'Despicable Me', '파리의 에펠탑, 뉴욕의 자유의 여신상 등 각 나라를 대표하는 명소들을 한 번에 훔쳐버린 기상천외한 주인공 그루. 그는 세계 최고의 악당이 되기 위하여 다른 사람이 절대 훔칠 수 없는 것을 하나 훔치기로 마음 먹는다. 그것은 바로 달. 달을 훔치기 위한 최신식 장비를 구하기 위해 어쩔 수 없이 세 소녀들을 맡게 된 그루는 세 소녀들과 함께 살게 되면서 세상에서 가장 어려운 일은 악당이 되는 것이 아니라 바로 이 소녀들을 키우는 일임을 알게 된다. 소녀들에 의해 점차 사랑을 배우고 변화되어 가는 그루, 과연 그는 달을 훔칠 수 있을 것인가?', 'https://image.tmdb.org/t/p/w500/avyPqGBGeeGsx4c89sIIDcfggjR.jpg', 'MOVIE'),(208, NULL, 9279, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '1996-12-07', '솔드 아웃', 'Jingle All the Way', '하워드(아놀드 슈왈제네거 분)는 의욕적이고 능력있는 사업가. 그러나 일이 너무 바쁘다보니 본의 아니게 아들 제이미(제이크 로이드 분)와 아내 리즈(리타 윌슨 분)에게는 평균 점수 이하의 가장일 수 밖에 없다. 반면 그의 옆집에 사는 이혼남 테드(필 하트먼 분)는 아들에게 극진한 정성을 보이는 완벽한 아빠. 테드의 존재로 인해 하워드는 늘 자신이 부족한 아빠라는 컴플렉스에 시달린다.  크리스마스를 이틀 앞둔 어느날, 하워드는 아들에게 크리스마스 선물로 터보맨이라는 로봇 인형을 사주기로 했던 걸 깜빡 잊고 있었음을 깨닫는다. 모처럼 아들에게 점수를 만회할 기회를 잘못하면 망치게 된 것. 그는 터보맨 인형을 사러 이브날 아침 일찍 백화점으로 달려가지만 그해에 아이들에게 가장 인기있는 선물 터보맨은 이미 동이 나고 없었다. 그때부터 터보맨 인형을 사기위한 하워드의 필사적이고 눈물겨운 노력이 시작된다. 한편 하워드 못지않게 필사적으로 터보맨을 사려는 우체부 마이런 라라비(신밧드 분)가 가는 곳마다 나타나서 하워드를 괴롭힌다.', 'https://image.tmdb.org/t/p/w500/k5oG9KadNLQCInvGnXa7DwPC6xC.jpg', 'MOVIE'),(210, NULL, 109418, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2022-01-01', '다 큰 녀석들 2', 'Grown Ups 2', '어렸을 때부터 친했던 친구들인 레니, 라몬소프, 맥켄지, 히긴스. 여름을 맞아 이들은 옛 추억을 떠올리며 한때 자신들이 겁 없이 무모한 짓을 했던 곳을 찾아간다. 하지만 접근 금지 구역인 그곳에는 과거의 자신들처럼 젊은 대학생들이 한창 파티를 즐기고 있다. 대학생들은 이들을 불청객 취급을 하고 쫓아낸다. 수치스러운 모습으로 쫓겨난 이들은 대학생들에게 복수를 하고 옛 추억을 떠올리며 레니의 집에서 80년대를 주제로 한 파티를 여는데...', 'https://image.tmdb.org/t/p/w500/hT6ijOtjtYrnyDhN7VA2QWyGFAm.jpg', 'MOVIE'),(212, NULL, 8920, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2004-08-19', '가필드', 'Garfield', '푹신 푹신한 소파, 인정 많은 주인 존(브레킨 메이어 분) 덕에 TV 리모콘을 점령하고 맘껏 게으름을 피우면서 배부르게 라자니아를 먹고 낮잠을 청하는 것이 전부인 오렌지색 고양이 ‘가필드’. 어느날, 주인이 강아지 ‘오디’를 데려오기 전까지는 그야말로 남부러울 것 없는 천국 같은 생활이 계속되고 있었다. 그러나 ‘존’이 짝사랑 해오던 ‘리즈 박사’(제니퍼 러브 휴이트 분)의 부탁으로 ‘오디’를 데려오는 순간, ‘가필드’의 생활은 순식간에 절망으로 바뀌고 만다. 특유의 애교로 ‘오디’는 ‘존’의 사랑을 맘껏 받으며 점차 ‘가필드’의 안락한 생활을 위협하기 시작하는데… 게다가 ‘오디’는 주인이 맘에 두고 있는 여자 수의사 ‘리즈 박사’가 사랑하는 강아지가 아닌가?  다시 예전의 천국 같은 생활로 돌아갈 수 있을까 머리를 굴리면서 ‘오디’를 사사건건 괴롭히기 시작한다. 그러나, ‘오디’는 절대 굴하지 않고 특유의 천진난만함으로 ‘존’의 사랑까지 흠뻑 받으며 ‘가필드’ 그 동안 무서울 것이 없었던 ‘가필드’는 위기 의식을 느끼고 어떻게 하면 ‘오디’를 집에서 내쫓고 의 행복을 위협한다.  마침내 ‘가필드’는 눈에 가시 같은 ‘오디’를 집 밖으로 내몰고 ‘오디’가 없는 집에서 꿈 같은 하루를 보낸다. 아침에 눈을 뜬 ‘존’는 ‘오디’가 없어진 것을 알고 백방으로 ‘오디’를 찾아보지만 ‘오디’의 행방은 오리무중. ‘오디’의 스타성을 감지한 케이블 TV 진행자 해피 챔만(스티븐 토보로스키 분)이 ‘오디’를 유괴한 것이다. ‘오디’를 내쫓지 못해 안달하던 ‘가필드’는 ‘오디’의 빈자리가 크게 느껴지고 ‘오디’가 불쌍해 지기 시작하면서 ‘오디’를 구해 내겠다는 결심을 하게 된다. 집 앞 다섯 발자국만 나가도 식은 땀을 흐리는 ‘가필드’는 마침내 안락한 생활을 박차고 바깥 세상에 나서고, 그 앞에는 그 동안 상상 할 수 없었던 스펙터클한 사건이 기다리고 있는데…', 'https://image.tmdb.org/t/p/w500/eLDV1QDG67YjWdEpczAOpijmLkQ.jpg', 'MOVIE'),(214, NULL, 93456, '2026-01-29 12:23:23', '2026-01-29 12:23:26', 'en', '2013-09-12', '슈퍼배드 2', 'Despicable Me 2', '슈퍼 악당에서 딸바보 슈퍼 대디로 180도 변신한 그루는  수다스럽고 사랑스러운 세 딸 마고, 에디스, 아그네스와 함께 행복한 삶을 살고 있다.  어느 날 거대한 자석에 의해 남극의 비밀연구소가 사라지는 사건이 발생한다. 알고보니 이 연구소는 생물을 야수로 만드는 약물을 개발하고 있었고, 악당퇴치연맹은 이 짓을 벌인 악당을 잡기 위해 그루에게 조언을 구한다. 세 딸과 평화로운 시간을 보내던 그루는 비밀요원 루시와 함께 위장 쿠키 가게를 차려 악당을 찾고, 이 과정에서 루시에게 마음을 뺏기기 시작한다. 한편 정체 모를 악당은 미니언들을 납치해 괴물로 변신시켜 세계를 정복하려 하지만 그루는 이 사실도 모른 채 루시와 딸들에게만 신경을 쓰는데...', 'https://image.tmdb.org/t/p/w500/z20OdiTzgA7kh4mPKzwLZxymG7i.jpg', 'MOVIE'),(215, NULL, 589174, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'ko', '2020-09-29', '담보', '담보', '1993년 인천, 거칠고 까칠한 사채업자 두석과 종배는 떼인 돈 받으러 갔다가 얼떨결에 9살 승이를 담보로 맡게 된다. 뜻도 모른 채 담보가 된 승이와 승이 엄마의 사정으로 아이의 입양까지 책임지게 된 두석과 종배. 하지만 부잣집으로 간 줄 알았던 승이가 엉뚱한 곳에 있다는 것을 알게 된 두 사람은 승이를 데려와 돌보게 된다. 예고 없이 찾아온 아이에게 인생을 담보 잡힌 두석과 종배. 빚 때문에 아저씨들에게 맡겨진 담보 승이. 두석, 종배, 승이 세 사람은 어느덧 서로에게 특별한 존재가 되는데...', 'https://image.tmdb.org/t/p/w500/b6clzuYNbizWFUtcpLBsp00zXNe.jpg', 'MOVIE'),(216, NULL, 1037113, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2024-06-03', '스낵 쉑', 'Snack Shack', '\"한여름의 청춘, 돈벌이와 첫사랑이 충돌한다\"\r 1991년 네브래스카, 붙어 다니는 단짝 AJ와 무스는 동네 수영장의 스낵바 운영권을 따내며 일확천금을 꿈꾼다. 장사 수완과 엉뚱한 계획으로 매일이 모험이 되던 그들 앞에 세련된 신참 라이프가드 브룩이 나타나면서 우정과 사업은 미묘한 균열을 맞이한다. 햇살과 땀, 소란스러운 여름의 기운 속에서 두 소년은 욕망과 책임, 그리고 마음의 방향을 선택해야만 하게 되는데...', 'https://image.tmdb.org/t/p/w500/wCXd5tpUSc12LVPd2oN9OKU1EVQ.jpg', 'MOVIE'),(219, NULL, 673271, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'en', '2022-08-12', '13: 더 뮤지컬', '13: The Musical', '부모님의 이혼으로 뉴욕에서 인디애나주로 이사 온 영리한 중학생. 최고로 멋진 바르미츠바 파티를 열기로 결심한다.', 'https://image.tmdb.org/t/p/w500/rqShG2kTbsVbgrgjfoEwawjR88N.jpg', 'MOVIE'),(220, NULL, 623135, '2026-01-29 12:23:23', '2026-01-29 12:23:23', 'ko', '2021-08-11', '싱크홀', '싱크홀', '서울 입성과 함께 내 집 마련의 꿈을 이룬 가장 동원은 이사 첫날부터 프로 참견러 만수와 사사건건 부딪힌다. 동원은 자가취득을 기념하며 직장 동료들을 집들이에 초대하지만 행복한 단꿈도 잠시, 순식간에 빌라 전체가 땅 속으로 떨어지고 만다. 지하 500m 싱크홀 속으로 떨어진 이들은 과연 무사히 빠져나갈 수 있을까?', 'https://image.tmdb.org/t/p/w500/l71a3Mh4PbOZwbIOlcsi3QcezK5.jpg', 'MOVIE'),(221, NULL, 646380, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2021-12-08', '돈 룩 업', 'Don\'t Look Up', '지구를 향해 돌진하는 혜성의 존재를 발견한 두 천문학자. 임박한 재앙을 전 인류에 경고하려 언론사를 찾아다니기 시작한다. 하지만 다른 데 정신이 팔린 세상은 시큰둥한 반응뿐. 그래서요?', 'https://image.tmdb.org/t/p/w500/e48Ychye5TtwarRe41PzeCJH9RZ.jpg', 'MOVIE'),(222, NULL, 318846, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2016-01-21', '빅쇼트', 'The Big Short', '사회성이라곤 없는 캐피털 회사 대표 마이클 버리는 금융시장의 붕괴를 예측하고, 골드만삭스를 찾아가 부동산 폭락에 돈을 걸겠다고 말해 비웃음을 산다. 도이치뱅크의 트레이더인 자레드 베넷은 대형 은행들이 안전자산이라 홍보한 부채담보부증권의 부실을 파악하고 내부 정보를 투자자들에게 흘린다. 펀드매니저 마크 바움은 자레드에게서 제공받은 정보로 대형 은행과 반대되는 투자를 감행한다. 은퇴 뒤 은둔 중인 전직 트레이더 벤 리커트는 눈밝고 대담한 젊은 펀드매니저 찰리와 제이미를 돕는다.', 'https://image.tmdb.org/t/p/w500/bKzXKJPFQbR7V8C4YtqFUwDNZLy.jpg', 'MOVIE'),(223, NULL, 9472, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2004-11-12', '피구의 제왕', 'DodgeBall: A True Underdog Story', '낡고 초라하지만, 가진 것 없는 회원들에게는 최고의 휴식처 같은 ‘애버리지 조 체육관’이 폐쇄 위기에 처한다. 맞은편에 들어선 글로보 피트니스 센터의 사장인 화이트 굿맨(벤 스틸러 분)이 체육관을 허물고 회원전용 주차타워를 짓기로 한 것이다.  체육관 주인 피터(빈스 본 분)는 한달 안에 대출금 5만 달러를 갚지 못하면 체육관을 화이트에게 넘겨야 하는 상황. 도저히 돈을 구할 방법이 없어 자포자기한 그에게 회원 중의 한명이 우승 상금 5만 달러가 걸린 피구 대회에 참가하자고 제안한다.  피구를 애들 장난쯤으로 생각한 피터는 코웃음을 치지만, 다른 회원들의 간청에 못 이겨 대회 참가를 결정한다. ‘애버리지 조’팀은 지역 예선에서 걸스카웃 팀에게 처참하게 깨지지만, 상대팀이 약물 복용으로 실격하는 바람에 어부지리로 본선 진출권을 따낸다. 그때 그들의 실력을 지켜보던 한 남자가 코치를 자청하고 나선다. 그는 바로 ‘피구의 제왕’으로 통했던 전설적인 피구 스타 패치스. 이제 애버리지 조 팀은 패치스의 지도 아래 지옥 훈련을 시작한다.  한편, 피터 일행이 피구 대회에 참가한다는 첩보를 입수한 굿맨은 고춧가루 뿌리기에 나서 최강의 멤버들로 퍼플 코브라 팀을 구성한다. 굿맨의 팀은 승승장구를 거듭하여 결승에 진출하고, 그의 바람대로 애버리지 조를 최후의 상대로 맞이하게 된다.  결승전이 벌어지기 전날, 피터와 라이벌 관계에 있던 굿맨은 그의 자존심을 짓밟을 음모를 꾸민다. 현금 10만 달러를 들고 피터를 찾은 그는 돈을 받는 대신 결승전을 포기하라고 제안한다. 이에 피터는 돈을 받고 짐을 챙겨 떠나는데…', 'https://image.tmdb.org/t/p/w500/5vLbxwwGLaLduMPKYx7TDMa1Ler.jpg', 'MOVIE'),(224, NULL, 554972, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'ko', '2018-11-22', '성난황소', '성난황소', '거칠었던 과거를 벗어나 수산시장에서 건어물 유통을 하며 건실하게 살던 동철. 어느 날 아내 지수가 납치되고, 경찰에 신고를 하지만 그녀의 행방은 묘연하기만 하다. 그리고 동철에게 걸려 온 납치범의 전화. 오히려 지수를 납치한 대가로 거액의 돈을 동철에게 주겠다는 파격 제안을 하고, 이에 폭발한 동철은 지수를 구하기 위해 움직이기 시작하는데…', 'https://image.tmdb.org/t/p/w500/xiVHlQ4aUyeQQFngyGEounzcYlX.jpg', 'MOVIE'),(225, NULL, 629028, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'ko', '2021-02-17', '미션 파서블', '미션 파서블', '입금만 되면 뭐든 가능해지는 흥신소 사장 우수한 앞에 어느 날 열정 충만 비밀 요원 유다희가 현금 천 만원과 함께 찾아 온다. 무기 밀매 사건을 해결하자며, 대놓고 공조를 요청해 온 것. 혼자일 때보다 둘일 때 더 눈에 띄는 두 사람. 작전을 거듭해 갈수록 사건은 커져만 가고, 형사들이 오해할만한 단서를 여기저기 흘리고 다녀 수배 목록에 오르기도 하지만 아찔한 이 공조를 멈출 수는 없다.', 'https://image.tmdb.org/t/p/w500/xul24PvmhG1smXsAcOPCeeuKLUN.jpg', 'MOVIE'),(226, NULL, 194662, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2015-03-05', '버드맨', 'Birdman or (The Unexpected Virtue of Ignorance)', '슈퍼히어로 버드맨으로 할리우드 톱 스타에 올랐지만 지금은 잊혀진 배우 리건 톰슨. 그는 꿈과 명성을 되찾기 위해 브로드웨이 무대에 도전한다. 대중과 멀어지고, 작품으로 인정받은 적 없는 배우에게 현실은 그의 이상과 거리가 멀다. 재기에 대한 강박과 심각한 자금 압박 속에, 평단이 사랑하는 주연배우의 통제불가 행동들, 무명배우의 불안감, SNS 계정 하나 없는 아빠의 도전에 냉소적인 매니저 딸, 연극계를 좌지우지 하는 평론가의 악평 예고까지... 과연 버드맨 리건은 다시 날아오를 수 있을까?', 'https://image.tmdb.org/t/p/w500/xualqZzQOYp6YVw05J4QFMQZ453.jpg', 'MOVIE'),(227, NULL, 639720, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2024-05-15', '이프: 상상의 친구', 'IF', '상상의 친구 ‘이프’를 볼 수 있는 능력을 지닌 한 소녀가 아이들에게 잊혀졌던 ‘이프’를 다시 되찾아주기 위해 마법 같은 모험을 시작하는 이야기를 그린 영화', 'https://image.tmdb.org/t/p/w500/os1AE0MWPu1S1gcfKxosDv9fwuP.jpg', 'MOVIE'),(228, NULL, 594, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2004-08-27', '터미널', 'The Terminal', '동유럽의 작은 나라 크로코지아의 평범한 남자 빅터 나보스키(톰 행크스)는 뉴욕 입성의 부푼 마음을 안고 JFK 공항에 도착한다. 그러나 입국 심사대를 빠져 나가기도 전에 고국에선 쿠데타가 일어나고, 일시적으로 유령국가가 되었다는 소식을 접한다. 아무리 둘러봐도 그가 머물 곳은 JFK 공항 밖에 없지만, 공항 관리국의 프랭크에게 빅터는 골칫거리일 뿐. 지능적인 방법으로 밀어내기를 시도하는 프랭크에 굴하지 않고, 바보스러울 만큼 순박한 행동으로 버티기를 거듭하는 빅터. 이제 친구도 생기고 아름다운 승무원 아멜리아(캐서린 제타 존스)와 로맨스까지 키워나가는데...', 'https://image.tmdb.org/t/p/w500/6BGzYTpKGsMiFwJUUJj1sE7JoXj.jpg', 'MOVIE'),(234, NULL, 9957, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2007-01-18', '벤치워머스', 'The Benchwarmers', '항상 후보신세로 \'벤치만 따뜻하게 데우며\' 어두운 그림자 속에서 살아온 세 남자. 이제 더 이상은 이렇게 살지 않을 것이라고 결심한다. 그들 셋이 우연히 도와주게 된 소년 넬슨의 아버지 멜의 도움으로 그들은 리틀 리그에서 가장 강력한 팀에 맞서 싸울 준비를 위해 혹독한 훈련에 돌입한다.', 'https://image.tmdb.org/t/p/w500/5yMPCr4qhuNg6fT538xicHaMaG7.jpg', 'MOVIE'),(235, NULL, 360920, '2026-01-29 12:23:24', '2026-01-29 12:23:26', 'en', '2018-12-19', '그린치', 'The Grinch', '모두가 행복한 크리스마스를 참을 수 없는 그린치는 크리스마스를 훔치기 위해 산타가 되기로 결심한다. 그린치는 만능집사 맥스, 덩치만 큰 소심 루돌프 프레드와 함께 슈퍼배드한 크리스마스 훔치기 대작전에 돌입하는데…', 'https://image.tmdb.org/t/p/w500/clJYtRBUhDtvKhPk2HNfXouviKF.jpg', 'MOVIE'),(236, NULL, 9928, '2026-01-29 12:23:24', '2026-01-29 12:23:26', 'en', '2005-07-28', '로봇', 'Robots', '성공의 주역들이 이번엔 사람을 꼭 닮은 로봇세상을  창조했다!!!  로봇의 귀여운 포스(?)가 세상을 놀래켜 버릴껄???  작은 빈민가 식당주인에서부터 거대 기업의 임원들까지 사람들과 똑같이 다양한 직업을 가진 로봇들의 세계. 이곳의 로봇들은 개인의 희망에 따라서, 혹은 자식의 앞날을 걱정하는 부모님의 강요(?)에 의해 각자 그에 맞도록 부품을 보태며 어른이 된다. 작은 시골마을의 로봇식당 식기세척로봇인 마음씨 착한 ‘쿠퍼보텀씨’는 아내와 함께 아들을 키우기로 결심하고 아기로봇상품을 주문한다. 그리고 배달된 아기로봇 부품을 힘들게 조립하고 나서 드디어 ‘로드니’ (이완 맥그리거)가 로봇세상에 태어난다.  어린 로드니는 사촌들의 로봇부품을 물려받아 자라야 할만큼 어려운 형편이지만, 부모님의 따뜻한 사랑을 받으면서 무럭무럭 자란다. 그리고 어린 시절부터 TV에 봐왔던 위대한 발명가 ‘빅웰드씨’처럼 되겠다는 꿈을 가지고 있던 ‘로드니’는 성공해서 부모님을 편안히 모셔드릴 꿈을 이루기 위해 ‘로봇시티’로 떠난다.  희한하네?!? 로봇이 사람 같네??!!  로봇시티에 도착한 로드니는 난생 처음 경험하는 도시에서의 온갖 고생 끝에 빅웰드사에 도착하지만 이미 빅웰드씨는 사라지고 업그레이드 부품만을 생산해 사리사욕을 채우는 악랄한 경영자 라챗이 실권을 쥔 상태. 실의에 빠진 로드니는 고향으로 돌아가려 하지만 그를 믿어주는 아버지를 위해 사고뭉치 친구 팬더(로빈 윌리엄스)와 친구들과 함께 라챗으로 부터 로봇시티를 구해내기 위한 기상천외한 작전을 꾸미는데…', 'https://image.tmdb.org/t/p/w500/f6tvS9qM9TaFTWZd79xCa9lhCao.jpg', 'MOVIE'),(238, NULL, 537921, '2026-01-29 12:23:24', '2026-01-29 12:23:26', 'en', '2025-08-13', '오늘만은 수컷이고 싶어', 'Fixed', '중성화 수술을 하루 앞둔 강아지. 남은 24시간 동안 친구들과 마지막으로 수컷 본능을 불태울 하룻밤 모험에 나선다.', 'https://image.tmdb.org/t/p/w500/uHxDUawGwC6ysjZg8nHqx3NfbtA.jpg', 'MOVIE'),(239, NULL, 426166, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'ko', '2016-11-24', '형', '형', '유도 국가대표 고두영은 경기 도중 불의의 사고를 당하게 되고  이 소식을 들은 사기전과 10범의 형 고두식은 눈물의 석방 사기극을 펼친다.  하루 아침에 앞이 깜깜해진 동생을 핑계로 1년간 보호자 자격으로 가석방 된 두식. 15년 동안 단 한번도 연락이 없던 뻔뻔한 형이 집으로 돌아오고  보호자 노릇은커녕 두영의 삶을 더 엉망진창으로 만드는데….  남보다 못한 형제의 예측불허 동거가 시작된다!', 'https://image.tmdb.org/t/p/w500/3cumlfgwUWdbxke9s19bqWEDYcs.jpg', 'MOVIE'),(240, NULL, 6477, '2026-01-29 12:23:24', '2026-01-29 12:23:26', 'en', '2007-12-19', '앨빈과 슈퍼밴드', 'Alvin and the Chipmunks', 'LA의 유명한 음반사 로비. 도시 외곽 숲 속의 나무에서 살아가던 다람쥐 앨빈, 사이먼, 테오도르는 살던 나무가 잘려나가는 바람에 얼떨결에 음반사에 안치된 트리 위에 살게 된다. 음반사 사장에게 된통 당하고 집으로 돌아가던 작곡가 데이브의 가방으로 세 마리의 앙증맞은 다람쥐가 뛰어들면서 데이브와 앨빈, 사이먼, 테오도르의 운명적인 만남이 시작된다. 열정적인 앨빈, 똑똑한 사이먼, 순수한 테오도르는 자기 마음대로 데이브의 집을 보금자리로 정한다. 데이브는 재치 있는 말솜씨에 절대음감, 게다가 작렬하는 댄스까지 끼와 재능으로 똘똘 뭉친 그들을 힙합 가수로 데뷔 시키고, 앨빈과 슈퍼밴드는 곧 선풍적인 인기를 얻게 된다. 데이브는 그들의 작곡가 이면서 매니저, 나아가 아버지 역할까지 하게 되는데, 앨빈과 슈퍼밴드의 인기가 하늘 높이 치솟으면서 데이브의 간섭이 슬슬 귀찮아지기 시작한다.', 'https://image.tmdb.org/t/p/w500/cNNYVMshozcnaAehGBRKIvfePvo.jpg', 'MOVIE'),(254, NULL, 1147266, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'ko', '2024-10-16', '6시간 후 너는 죽는다', '6시간 후 너는 죽는다', '서른 살 생일을 하루 앞둔 정윤은 길에서 만난 낯선 남자 준우에게 죽음 예고를 듣는다. 믿을 수 없는 예언이 거짓말처럼 현실이 되어가면서 정윤은 자신을 죽이려는 범인을 찾기 위해 준우와 여정을 시작하게 되는데...', 'https://image.tmdb.org/t/p/w500/asdw71nkWcyvwfuPlpgohavTuXL.jpg', 'MOVIE'),(258, NULL, 11324, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2010-03-18', '셔터 아일랜드', 'Shutter Island', '보스턴 셔터아일랜드의 정신병원은 중범죄를 저지른 정신병자를 격리하는 병동으로 탈출 자체가 불가능하다. 하지만 자식 셋을 죽인 혐의를 받고 있는 여인이 이상한 쪽지만을 남긴 채 감쪽같이 사라지는 사건이 발생한다. 연방보안관 테디 다니엘스(레오나르도 디카프리오)는 수사를 위해 동료 척(마크 러팔로)과 함께 셔터아일랜드로 향한다. 테디는 수사를 위해 의사, 간호사, 병원관계자 등을 심문하지만 수사는 전혀 진척되지 않는다. 설상가상 폭풍이 불어 닥쳐 테디와 척은 섬에 고립되게 되고, 그들에게 점점 괴이한 일들이 일어나기 시작하는데...', 'https://image.tmdb.org/t/p/w500/5gEu0DqMtRj6IB98BGlb8FyyUtZ.jpg', 'MOVIE'),(259, NULL, 1426776, '2026-01-29 12:23:24', '2026-01-29 12:23:24', 'en', '2025-06-06', '벼랑 끝에 서서', 'STRAW', '열심히 일하며 간신히 버텨온 싱글맘. 하지만 인내심을 무너뜨릴 최후의 타격을 맞게 된다면? 끔찍한 하루를 보내고 한계에 다다른 그녀는 절망에 빠져 충격적인 행동을 하기에 이른다.', 'https://image.tmdb.org/t/p/w500/puj4agwRL5TsT7e0TYDqEXBZqyN.jpg', 'MOVIE'),(266, NULL, 242582, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2015-02-26', '나이트 크롤러', 'Nightcrawler', '루이스는 우연히 목격한 교통사고 현장에서 사건 현장을 카메라에 담아 TV 매체에 고가에 팔아 넘기는, 일명 나이트 크롤러를 보게 된다. 경찰이 도착하기 전에 빠르게 나타나 현장을 스케치하고 전화를 통해 가격을 흥정하는 그들에게서 묘한 돈 냄새를 맡은 루이스는 즉시 캠코더와 경찰 무전기를 구입하고 사건현장에 뛰어든다. 유혈이 난무하는 끔찍한 사고 현장을 적나라하게 촬영해 첫 거래에 성공한 루이스는 남다른 감각으로 지역채널의 보도국장 니나의 적극적인 지지를 받게 된다. 매번 더욱 더 자극적이고 충격적인 뉴스를 원하는 니나와 그 이상을 충족 시켜주는 루이스는 최상의 시청률을 만들어내며 승승장구한다. 자신의 촬영에 도취된 루이스는 결국 완벽한 특종을 위해 사건을 조작하기에 이르는데...', 'https://image.tmdb.org/t/p/w500/wVflplL5OMy8nD1Z7gM64lIRvwa.jpg', 'MOVIE'),(270, NULL, 1359, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2000-11-25', '아메리칸 싸이코', 'American Psycho', '모든 것에 최고와 최상을 추구하는 패트릭 베이트만. 하버드 MBA출신의 그는 합병회사의 최고경영자이다. 최고급 브랜드의 옷을 입고, 최고급 향수를 뿌리며 아무나 예약할 수 없는 최고급 식당에서 식사를 즐긴다. 패트릭은 자신보다 더 잘나가는 폴이에게 적대감을 느끼고 그를 자신의 집으로 불러들여 살인을 저지른다. 곧 일상으로 복귀한 패트릭은 간밤의 살인은 까맣게 잊은 듯 하다. 그러나 사실 그는 살인에서 묘한 쾌감을 얻었다. 죄책감없이 일상으로 완벽하게 복귀한 듯 보이지만, 그는 어느 새 다른 대상을 물색하는 자신을 본다.', 'https://image.tmdb.org/t/p/w500/ix9Q7d4IQ329yhsBo7lZ9n9EgIb.jpg', 'MOVIE'),(272, NULL, 291805, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2016-07-12', '나우 유 씨 미 2', 'Now You See Me 2', '3년 전, 전세계를 무대로 한 통쾌하고 짜릿한  완전범죄 매직쇼로 세계를 발칵 뒤집어 놓은 그들이 돌아왔다!  마술사기단은 더 강력해진 적에 의해 전세계 팬들이 보는 앞에서 함정에 빠지게 되고  세상의 모든 컴퓨터를 컨트롤할 수 있는 카드를 훔쳐야 하는 절체절명의 위기에 빠진다.  불가능한 마술로 명예 회복에 나선 마술사기단!  보고도 믿을 수 없는 완전범죄 매직쇼가 시작된다!', 'https://image.tmdb.org/t/p/w500/7Q6HhzkuV6kXQzKDUttoPZY1b5k.jpg', 'MOVIE'),(279, NULL, 1400782, '2026-01-29 12:23:25', '2026-01-29 12:23:27', 'en', '2025-10-17', '완벽한 이웃', 'The Perfect Neighbor', '경찰 측 보디캠 영상을 통해 오랜 기간 이어진 이웃 간 분쟁이 어떻게 치명적인 폭력 사태로 번졌는지 낱낱이 드러난다. 두려움, 편견, 그리고 \'스탠드 유어 그라운드\' 법을 다룬 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/6iQSlOkq4w5OK5hv37eTfavm4Df.jpg', 'MOVIE'),(281, NULL, 1151766, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'ko', '2025-09-05', '살인자 리포트', '살인자 리포트', '특종에 목마른 위기에 기자 백선주에게 자신이 연쇄살인범이라고 주장하는 정신과 의사 이영훈이 새로운 살인 예고와 함께 인터뷰 요청을 한다. 고민 끝에 선주는 호텔 스위트 룸에서 살인자와의 인터뷰를 시작하고, 그의 살인 동기가 환자의 치료 목적으로 시작되었다는 믿기지 않는 고백을 듣게 된다. 인터뷰가 진행될수록 무언가 잘못됨을 느끼고 도망가려던 선주는 지금 인터뷰를 멈추면 또 한 명이 살해될 것이라는 영훈의 충격적인 얘기를 듣게 되는데…', 'https://image.tmdb.org/t/p/w500/rcmJRflS4aFJg8Ockk7YePQWlzc.jpg', 'MOVIE'),(283, NULL, 64690, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2011-11-17', '드라이브', 'Drive', '낮에는 스턴트맨과 자동차 정비소 직원, 밤에는 범죄집단의 도주를 돕는 운전을 하는 드라이버. 이름조차 불리지 않는 무미건조한 그의 삶에 어느 날 아이린이 찾아왔다. 옆집에 사는 아이린과 교감하며 따스함을 느끼던 것도 잠시, 감옥에 가 있던 아이린의 남편이 돌아오며 모든 것은 원점으로 돌아간다. 하지만 감옥에서 진 빚 때문에 협박을 받자 그녀의 행복을 지키기 위해 갱단의 요구대로 전당포 터는 일에 협조하지만 함정에 빠지고, 위험에 노출된 아이린을 지키기 위한 드라이버의 폭주가 시작된다. 숨막히는 폭력과 치열한 사투를 벌이던 그는 서서히 자신의 숨겨져 있던 냉혹한 본성과 마주하게 되는데...', 'https://image.tmdb.org/t/p/w500/ukDRwCEnVwBVSJ13xpzSzegIi1u.jpg', 'MOVIE'),(284, NULL, 77, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2001-08-25', '메멘토', 'Memento', '전직 보험 수사관이었던 레너드에게 기억이란 없다. 자신의 아내가 강간당하고 살해되던 날의 충격으로 기억을 10분 이상 지속시키지 못하는 단기 기억상실증 환자가 되었던 것이다. 그가 마지막으로 기억하고 있는 것은 자신의 이름이 레너드 셸비 라는 것과 아내가 강간당하고 살해당했다는 것, 그리고 범인은 존 G 라는 것이 전부. 레너드는 자신의 가정을 파탄 낸 범인을 찾기 위한 방법으로 메모와 문신을 사용하게 된다. 하지만 진실에 다가갈수록 자신의 기억, 주위 사람들에 대한 의심이 갈수록 커져만 가는데...', 'https://image.tmdb.org/t/p/w500/vqxdADPdy0ZVJr8dMB3mh6C5Vsv.jpg', 'MOVIE'),(286, NULL, 74, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2005-07-07', '우주전쟁', 'War of the Worlds', '레이 페리어는 이혼한 항만 근로자로 아무런 희망 없이 매일을 살아간다. 그러던 어느 주말, 그의 전 부인은 아들 로비와 어린 딸 레이첼과 주말을 보내라고 레이에게 맡긴다. 그리곤 얼마 안 있어 강력한 번개가 내리친다. 잠시 후, 레이는 그의 집 근처에 있는 교차로에서 그들의 삶을 영원히 바꾸어버릴 엄청난 사건을 목격하게 된다. 커다랗고 다리가 셋 달린 정체 불명의 괴물이 땅속 깊은 곳에서 나타나 사람들이 미처 반응도 하기 전에 모든 것을 재로 만들었다. 평범했던 하루가 갑자기 외부의 알 수 없는 침략자들의 첫 번째 지구 공격으로 그들 인생에서 가장 엄청난 사건이 일어난 날이 되어버린 것이다. 레이는 그의 아이들을 이 무자비한 새로운 적들로부터 보호하기 위해 급히 피난을 떠나, 파괴되고 황폐해진 도시를 가로지르는 여정에 오른다. 거기서 그들은 침략자들을 피하기 위해 필사적으로 도망치는 피난민들을 만나 합류하게 된다. 그러나 그들이 어디로 가든지 안전한 곳은 없고, 피난처도 없다. 단지 소중한 사람을 지켜내겠다는 레이의 확고한 의지만 존재 할 뿐인데…..', 'https://image.tmdb.org/t/p/w500/kVfs7m8hfBC6nUrJBcuoTg1NLeA.jpg', 'MOVIE'),(294, NULL, 985939, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2022-11-16', '폴: 600미터', 'Fall', '내려갈 길이 끊겨버린 600미터 TV 타워 위에서  두 명의 친구가 살아남기 위해 펼치는 사상 최초의 고공 서바이벌 여기에서', 'https://image.tmdb.org/t/p/w500/uyiALGPVtVsrTY4YHSq2osSYls5.jpg', 'MOVIE'),(298, NULL, 800158, '2026-01-29 12:23:25', '2026-01-29 12:23:25', 'en', '2023-10-25', '더 킬러', 'The Killer', '결정적 순간에 아슬아슬하게 타깃을 놓친 암살자. 사적인 감정은 없다면서도, 이 응징을 위해 국제적인 추격전에 뛰어든다. 그 여정에서 의뢰인들, 그리고 그 자신과의 싸움이 시작된다.', 'https://image.tmdb.org/t/p/w500/8yX4Bt1qTUETuVyWgqyqlFM1nzw.jpg', 'MOVIE'),(310, NULL, 166428, '2026-01-29 12:23:26', '2026-01-29 12:23:26', 'en', '2019-01-30', '드래곤 길들이기 3', 'How to Train Your Dragon: The Hidden World', '영원한 친구 히컵과 투슬리스의 활약으로 사람과 드래곤이 공존하며 평화롭게 살아가는 버크섬. 새로운 드래곤 ‘라이트 퓨어리’를 쫓아간 투슬리스를 찾다가 히컵은 누구도 찾지 못했던 드래곤의 파라다이스 ‘히든월드’를 우연히 발견하게 된다. 하지만 평화도 잠시, 역대 최악의 드래곤 헌터 그리멜의 등장으로 드래곤들의 안전과 버크섬의 평화까지 위협받기 시작하는데…', 'https://image.tmdb.org/t/p/w500/51HTWy1h5a2cbXC9gKYGOt2YQBV.jpg', 'MOVIE'),(311, NULL, 10191, '2026-01-29 12:23:26', '2026-01-29 12:23:26', 'en', '2010-05-20', '드래곤 길들이기', 'How to Train Your Dragon', '바이킹의 세계, 절대 친구가 될 수 없는 둘이 만났다?  용맹한 바이킹과 사나운 드래곤들의 싸움이 끊이지 않는 버크섬.  바이킹 족장의 아들 ‘히컵’은 드래곤 사냥에 소질 없는 마을의 사고뭉치. 어느날 그는 부상 당한 드래곤 ‘투슬리스’를 구하게 되고, 아무도 몰래 그를 돌본다. 서로를 알아가며, 드래곤들의 친구가 된 ‘히컵’. 그들과의 새로운 생활을 만끽하던 ‘히컵’은 드래곤들의 위험한 비밀을 알게 되는데…  불멸의 드래곤과 바이킹족 이단아의 만남!  2010년 5월, 그들의 스펙터클한 모험이 시작된다!', 'https://image.tmdb.org/t/p/w500/5JtTkNwOeztwfCPv965e9bZi6G3.jpg', 'MOVIE'),(340, NULL, 431580, '2026-01-29 12:23:26', '2026-01-29 12:23:26', 'en', '2019-11-08', '스노우 몬스터', 'Abominable', '할머니, 어머니와 함께 살고 있는 ‘이’는 아버지가 죽기 전 함께 가고자 했던 여행을 위해 아르바이트를 하며 하루하루 돈을 모으고 있다.  그런 ‘이’ 앞에 악당인 동물학자와 사장의 손아귀에서 도망친 신비의 동물 ‘예티’가 나타난다. ‘이’는 ‘예티’를 가족의 품으로 돌려보내기 위해 ‘펭’ 그리고 진’과 함께 에베레스트로 떠난다. 하지만 ‘이’와 친구들 앞에 ‘예티’를 포획하고자 하는 동물학자, 사장이 나타난다. ‘이’와 친구들은 ‘예티’를 지키기 위해 있는 힘껏 도망치지만, 그들은 바짝 뒤를 쫓아오게 되는데…  ‘이’와 ‘펭’ 그리고 ‘진’은 어느새 친구가 되어버린 ‘예티’를 무사히 에베레스트까지 데려다 준 뒤 집으로 돌아올 수 있을까?', 'https://image.tmdb.org/t/p/w500/nwW056VfnoiGBbZyrZvP9laDUsy.jpg', 'MOVIE'),(350, NULL, 893723, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2023-10-06', '퍼피 구조대: 더 마이티 무비', 'PAW Patrol: The Mighty Movie', '신비한 힘을 가진 유성이 어드벤처 시티에 떨어진 날, 퍼피 구조대는 유성에서 나온 크리스탈 덕분에 초능력을 가진 ‘퍼피 히어로즈’로 변신한다. 하지만 악당 ‘험딩어 시장’과 미치광이 과학자 ‘빅토리아’는 초능력의 원천인 크리스탈을 빼앗아 어드벤처 시티를 지배하려 하는데..! 작고 약하게 태어났지만 오랫동안 큰 꿈을 키워 온 ‘스카이’와 퍼피 히어로즈는 주니어 구조대원들과 함께 어드벤처 시티를 지켜낼 수 있을까?', 'https://image.tmdb.org/t/p/w500/62CEuwp287mbVarn3f2KcSAsrj1.jpg', 'MOVIE'),(351, NULL, 915866, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2021-12-14', '별빛 히어로 스타빔: 우당탕탕 새해맞이', 'StarBeam: Beaming in the New Year', '새해맞이 전날 조이와 빔 팀에게 찾아온 서머셋의 힘센 악당무리. 하지만 우리에겐 멋쟁이 사촌 자라가 있는걸! 그럼, 이제 마을을 구하러 가볼까? 자라도 함께 말이야!', 'https://image.tmdb.org/t/p/w500/mKsXvzNdMJ6MhqNsO45zLdnyncS.jpg', 'MOVIE'),(352, NULL, 153518, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2016-05-19', '앵그리 버드 더 무비', 'The Angry Birds Movie', '화가 나면 참지 못하는 분노새 ‘레드’. 생각보다 말과 행동이 앞서는 깐족새 ‘척’. 욱하면 폭발해버리는 폭탄새 ‘밤’. 모두가 행복한 버드 아일랜드에서 어울리지 못하는 앵그리버드 레드, 척, 밤  어느 날, 정체불명의 초록 돼지 ‘피그’가 찾아오고,  평화로운 새계에 수상쩍은 일들이 벌어지기 시작하는데…  앵그리버드, 이들이 화난 진짜 이유가 밝혀진다!', 'https://image.tmdb.org/t/p/w500/vX1HEsTCQoKtwIOckN1f596QTpq.jpg', 'MOVIE'),(354, NULL, 400160, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2020-11-05', '스폰지밥 무비: 핑핑이 구출 대작전', 'The SpongeBob Movie: Sponge on the Run', '우리 핑핑이가 어디로 갔을까? 설마, 납치당한 건가? 사랑하는 반려 달팽이를 찾아 떠나는 스폰지밥. 뚱이도 함께 가야지. 비키니 시티를 벗어나 미지의 세계로, 출발이다!', 'https://image.tmdb.org/t/p/w500/fVALNXS9jgVKUNerF9C0X9i4EP5.jpg', 'MOVIE'),(361, NULL, 1595481, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2026-01-21', '납치된 아이: 엘리자베스 스마트', 'Kidnapped: Elizabeth Smart', '14세의 나이에 유타주 자택에서 납치되었던 엘리자베스 스마트의 이야기를 조명한 다큐멘터리. 피해자 본인의 증언과 미공개 자료를 통해 당시 사건의 충격적인 전말이 공개된다.\r 2002년 6월 5일 이른 새벽, 14세 소녀 엘리자베스 스마트가 유타주 솔트레이크시티의 자택 침실에서 납치당했다. 미국 역사상 손꼽히게 큰 파장을 일으키며 집중 보도된 실종 사건의 시작이었다. 《납치된 아이: 엘리자베스 스마트》는 엘리자베스 본인의 증언과 가족, 수사 담당자, 사건 관계자들의 단독 인터뷰를 통해 그날의 이야기를 생생하게 들여다보는 강렬한 다큐멘터리 영화다. 이 작품은 생생한 기록 영상과 미공개 자료를 엮어, 브라이언 데이비드 미첼과 완다 바지의 손아귀에 붙잡혀 있었던 엘리자베스의 악몽 같은 9개월을 따라간다. 또한, 그 과정에서 엘리자베스와 가족들이 겪었던 심리적·정서적 고통, 끊임없이 이어진 언론의 관심, 끈기 있게 해답을 찾으려 한 지역 사회의 노력을 조명하는 동시에, 그 당시 엘리자베스를 살아남게 했고 20년이 지난 지금까지도 그녀를 단단히 지탱해 온 불굴의 생존 의지를 되새긴다. 이 다큐멘터리는 미국 전역을 충격에 빠뜨렸던 사건을 단순히 되짚는 데서 그치지 않고, 그 후 엘리자베스가 걸어온 치유의 여정과 다른 이들에게도 희망을 전하고 울타리가 되어주고자 하는 그녀의 장기적인 목표까지 함께 조명한다.', 'https://image.tmdb.org/t/p/w500/lFSaWH6IYjSOtSF3CCoUuRNC3Av.jpg', 'MOVIE'),(362, NULL, 1610413, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2026-01-12', '기묘한 이야기 5 메이킹: 마지막 모험', 'One Last Adventure: The Making of Stranger Things 5', '더퍼 형제의 기획으로 한 세대를 대표하는 아이콘이 된 시리즈. 그 마지막 시즌이 완성되기까지 투입된 수년간의 노력과 제작 과정을 비하인드 스토리로 만나 본다.', 'https://image.tmdb.org/t/p/w500/sUkdh0YmY7GLJg7LcM2SGUAqrlo.jpg', 'MOVIE'),(364, NULL, 318256, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2015-01-24', '핫 걸 원티드', 'Hot Girls Wanted', '부모 곁을 떠나 자유를 찾으려는 소녀들. 생활비와 학비를 벌고 싶은 소녀들. 유명해지고 팬들을 거느리고 싶은 소녀들... 아마추어 포르노 업계에는 하루에도 수십, 아니 수백 명의 어린 지원자가 쏟아진다. 4백 만 클릭을 이끌어내는 비디오의 주인공이 되어 성취감과 유명세를 느끼지만, 정작 그녀들은 폭력적이고 강제적인 섹스의 소모품으로 착취되고 있을 뿐이다. 황폐해가는 몸과 마음을 돌 볼 시간도 없이, 매일매일 쏟아지는 뉴페이스들에게 떠밀려 포르노 업계의 더욱 깊숙한 나락으로 떨어지고 있는 소녀들. 그들을 삶을 밀착 조명한다.', 'https://image.tmdb.org/t/p/w500/75ot83QOkc02vujyzmIbumQCU6Y.jpg', 'MOVIE'),(365, NULL, 490818, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2018-02-09', '글로리아 올레드: 약자 편에 선다', 'Seeing Allred', '열정적이고 급진적인 페미니스트? 섹스 스캔들 전문 스타 변호사? 뭔가 부족하다. 항상 약자 편에서 부당한 권력과 맞서 싸운 강인한 여성, 글로리아 올레드 스토리!', 'https://image.tmdb.org/t/p/w500/k5QKlCTspfHoC6v4u4LvJSIC16E.jpg', 'MOVIE'),(366, NULL, 1480847, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2025-11-21', '기예르모 델토로의 피', 'Sangre del Toro', '어린 시절의 기억들, 문화적인 오해와 괴물들로 이루어진 미로. 기예르모 델토로 감독이 이 복잡한 미로를 헤쳐나가며 그의 독보적인 영화들의 기원을 보여준다.', 'https://image.tmdb.org/t/p/w500/i6gRde2TqBimsn1WTj4bgx0mnL.jpg', 'MOVIE'),(367, NULL, 1314450, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'ko', '2024-09-04', '안녕, 할부지', '안녕, 할부지', '선물로 찾아온 만남, 예정된 이별. 푸바오의 중국 귀환 일정이 결정되고, 사랑하는 이들의 아쉬움이 커져만 간다. 마침내 다가온 이별의 순간, 푸바오의 행복을 위해 애써 담담해 보였던 강바오와 송바오 역시 흔들리기 시작하는데… 헤어질 때를 알기에 매 순간 진심이고 애틋했던 그들. 1354일, 그동안의 못다 한 이야기. 안녕, 그리고 안녕…', 'https://image.tmdb.org/t/p/w500/2rDHFtRtAiixl3eWT7h5pae6Tue.jpg', 'MOVIE'),(368, NULL, 1391409, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2024-12-06', '사상 최대 암호화폐 도난 사건', 'Biggest Heist Ever', '놀라운 범죄 행각으로 \'비트코인 보니와 클라이드\'라는 별명을 얻은 커플. 파면 팔수록 더욱 기괴한 그들의 이야기가 펼쳐진다. 사상 최대 규모의 절도 사건을 다룬 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/k7i68SFZDciAT3vtElj50sqUHIa.jpg', 'MOVIE'),(369, NULL, 1517772, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2025-08-29', '의문의 발신자: 고등학교 캣피싱 사건', 'Unknown Number: The High School Catfish', '언젠가부터 상스러운 욕설 메시지가 한 10대 소녀와 남자 친구의 휴대폰을 쉴 새 없이 울린다. 누가, 왜 이런 문자를 보내는 걸까? 반전을 거듭하며 충격적인 진실을 밝혀내는 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/kaWkPgfcA0lIDOHNskmgcihXUC9.jpg', 'MOVIE'),(370, NULL, 1376704, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2024-11-19', '지금 구매하세요: 쇼핑의 음모', 'Buy Now! The Shopping Conspiracy', '브랜드들이 고객의 소비를 유도하기 위해 사용하는 전략이 우리의 일상과 사회에 미치는 영향을 분석한 파격적인 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/zDDKUY2Y7oFh2WvX6w6Wl7hXBbt.jpg', 'MOVIE'),(371, NULL, 1340628, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2024-10-18', '역전', 'The Turnaround', '필라델피아 필리스의 열성 팬이 부진에 빠진 유격수에게 경기의 흐름을 바꿀 기립 박수를 보내도록 필라델피아 시민을 독려하는 감동적인 단편 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/u75uRfuBB6q7Sfc7URFDnsF4bpT.jpg', 'MOVIE'),(372, NULL, 553645, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2019-04-26', '리마스터드: 악마와 걸은 사나이', 'ReMastered: Devil at the Crossroads', '혜성처럼 나타나 주옥같은 명곡을 남기고 떠난 뮤지션 로버트 존슨. 사람들은 그의 갑작스러운 죽음을 두고 이렇게 말한다. 그는 블루스를 위해 악마와 거래했던 것이라고!', 'https://image.tmdb.org/t/p/w500/mZHuM1rUJcXHRMgff35gGZmu7xF.jpg', 'MOVIE'),(373, NULL, 595399, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2019-05-03', '보통의 가족', 'All in My Family', '중국 출신의 미국 영화감독 하오. 게이인 그는 파트너와 두 아이를 고향 가족에게 소개하기로 한다. 보수적인 가족이 그를 받아들이는 과정을 담담하게 기록한 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/rNhwtG2UPsZJuohqvlCdaYuSPIJ.jpg', 'MOVIE'),(374, NULL, 1390590, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'ko', '2024-12-11', '엔시티 드림 미스터리 랩: 드림 이스케이프 인 시네마', '엔시티 드림 미스터리 랩: 드림 이스케이프 인 시네마', 'NCT DREAM의 세 번째 월드 투어 ‘THE DREAM SHOW 3 : DREAM( )SCAPE’. 전 세계를 펄 네오 샴페인 빛으로 물들인 서막이 스크린에서 다시 펼쳐진다! 꿈을 향한 여정에서 마주하는 성장의 비밀을 풀어가며 서로에게 위로의 처방전을 건네는 특별한 실험실, 미스터리 랩의 비밀이 풀린다. 그들의 청춘으로 빛났던 환상적인 무대와 치열하게 준비했던 열정 가득한 비하인드까지. 그들의 꿈을 향한 탈출과 새로운 여정의 시작을 알리는 무대.', 'https://image.tmdb.org/t/p/w500/gBIxYqWigRxn0AnqLlbb2ZKVFjs.jpg', 'MOVIE'),(376, NULL, 869602, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2021-11-30', '나의 집은 어디인가', 'Lead Me Home', '미국 서부 도시의 거리에 사는 노숙인들의 가슴 아픈 이야기를 담은 다큐멘터리. 나날이 심각해져 가는 노숙 문제를 밀착 조명한다.', 'https://image.tmdb.org/t/p/w500/i2MqnAk5bLMRhZgSjH8gpW4kBY3.jpg', 'MOVIE'),(377, NULL, 1418965, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'ko', '2025-02-05', '레드벨벳 해피니스 다이어리 : 마이 디어, 레베럽 인 시네마', '레드벨벳 해피니스 다이어리 : 마이 디어, 레베럽 인 시네마', '레드벨벳 데뷔 10주년, 러비들에게 특별한 추억과 선물이 될 영화! 레드벨벳의 환상적인 음악과 이야기가 스크린에서 펼쳐진다! \'행복 (Happiness)\'을 시작으로 \'Ice Cream Cake\', \'빨간 맛 (Red Flavor)\', \'Psyco\', \'Feel My Rhythm\', \'Cosmic\' 등 시간이 지나도 회자되는 수 많은 명곡을 탄생시킨 독보적 아티스트 레드벨벳. 2024 레드벨벳 팬콘 투어 <해피니스 : 마이 디어, 레베럽> 서울 공연의 화려한 무대 실황과 함께 지난 10년간 레드벨벳이 만들어 온 음악과 순간들에 대해 멤버들이 직접 전하는 비하인드 스토리까지 레드벨벳의 음악과 진솔한 이야기가 스크린에서 펼쳐진다. 레드벨벳 데뷔 10주년 이벤트의 환상적인 피날레!', 'https://image.tmdb.org/t/p/w500/5tAm010Mh0WEru1cKKsoVYHKK3I.jpg', 'MOVIE'),(378, NULL, 1556398, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2025-10-03', '명사들의 마지막 한마디: 제인 구달 박사', 'Famous Last Words: Dr. Jane Goodall', '독보적인 방식으로 인류와 자연을 이어 온 제인 구달 박사. 박사가 지극히 내밀한 인터뷰를 통해 마지막 메시지를 세상과 나눈다.', 'https://image.tmdb.org/t/p/w500/ypfl5VYRkeZ3HVM64HxOKriloe4.jpg', 'MOVIE'),(379, NULL, 1013577, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2022-09-02', '로버트 다우니 \"시니어\"', '\"Sr.\"', '로버트 다우니 주니어가 세상을 떠난 아버지에게 경의를 표한다. 시대를 앞서간 영화감독 로버트 다우니 시니어의 생애와 경계를 허무는 그의 커리어를 연대순으로 기록한 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/2lyqE4OQaEvNvNQwngsZH9xzg4B.jpg', 'MOVIE'),(380, NULL, 522393, '2026-01-29 12:23:27', '2026-01-29 12:23:27', 'en', '2018-05-01', '리커버리 보이즈', 'Recovery Boys', '웨스트버지니아에 아주 특별한 농장이 있다. 그들이 돌보고 키우는 건 다름 아닌 자기 자신! 한때 삶을 포기하고 약물에 중독됐던 네 명의 청년들이 작은 기적에 도전한다.', 'https://image.tmdb.org/t/p/w500/i8lsiLjNuEED3yxlmp89s4WAlOp.jpg', 'MOVIE'),(381, NULL, 1516391, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-12-26', '커버업: 은폐된 진실', 'Cover-Up', '권력층이 감추려 한 이야기를 파헤치는 데 커리어 전부를 건 남자. 미라이 학살에서 아부그라이브 사건까지, 기자 시모어 허시의 발자취를 들여다본다.', 'https://image.tmdb.org/t/p/w500/9L3CJAmy1pvT18jjEHWOIbvEbKO.jpg', 'MOVIE'),(382, NULL, 653574, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2020-01-23', '딕 존슨이 죽었습니다', 'Dick Johnson Is Dead', '죽음은 숙명, 피할 수 없다면 맞설 수밖에. 감독 커스턴 존슨이 노년의 아버지와 함께 다양한 방식으로 죽음을 연출한다. 그 비통한 순간에, 유머가 힘이 될 수 있을까.', 'https://image.tmdb.org/t/p/w500/vnfI34kmi3fcdgP7HZjIgGOJHGY.jpg', 'MOVIE'),(383, NULL, 1591516, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-12-30', '악마 인플루언서: 조디 힐데브란트 이야기', 'Evil Influencer: The Jodi Hildebrandt Story', '육아 유튜버 루비 프랭키와 함께 아동 학대 혐의로 체포된 유타주 심리 치료사, 조디 힐데브란트. 사람들을 교묘히 조종하고 통제해 온 그의 일그러진 민낯과 사건의 실체를 파헤친다.', 'https://image.tmdb.org/t/p/w500/rM3NLZgjs7vVWX3htMAWfwHypO8.jpg', 'MOVIE'),(384, NULL, 286407, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2014-01-30', '미션 블루', 'Mission Blue', '어류 남획과 독성물질 배출 등의 위협으로부터 전 세계 해양을 구하려는 해양학자 실비아 얼의 캠페인을 다룬 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/34sR023uQt7gNMFWNIWRHaacrVc.jpg', 'MOVIE'),(386, NULL, 1275897, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-06-28', '나는 너의 비너스', 'I\'m Your Venus', '비너스 엑스트라바간자는 1991년 획기적인 다큐멘터리 <파리 이즈 버닝>에서 화려한 \"볼 워커\"로 등장한 후 전세계적인 트랜스 아이콘으로 떠올랐다. 영화가 개봉하기도 전에 비너스는 살해되었고, 수십 년이 지난 지금 <아임 유어 비너스>는 사건의 실마리를 찾아간다. 그녀의 두 가족, 혈연 가족과 볼룸에서 만든 가족이 모여 그녀가 남긴 것을 기리고, 살인 사건에 대한 답을 찾으며 예상치 못한 공통분모를 발견하게 된다.', 'https://image.tmdb.org/t/p/w500/dzvEPrSJGyVAdUdOBzVniym3XQI.jpg', 'MOVIE'),(388, NULL, 877657, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2021-09-28', '할리우드 클리셰의 모든 것', 'Attack of the Hollywood Clichés!', '17대 1로 싸우는 주인공부터 운명 같은 남녀의 첫 만남, 폭발 후 멀쩡히 걸어가는 장면까지. 배우들과 내부 관계자들이 할리우드 영화의 전형적인 클리셰를 가감 없이 파헤친다.', 'https://image.tmdb.org/t/p/w500/fmI1oIAwXjfX8LcZYT8Rs2rZe2R.jpg', 'MOVIE'),(389, NULL, 1018648, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2022-10-07', '리딤팀: 다시 드림팀으로', 'The Redeem Team', '2004년 올림픽에서 처참한 성적을 거둔 미국 남자 농구 대표팀. 그로부터 4년 후, 2008 베이징 올림픽에서 금메달을 따내 과거의 부진을 만회하려 한다.', 'https://image.tmdb.org/t/p/w500/iXu5rPQYean8AktqZHmWb27rOEe.jpg', 'MOVIE'),(390, NULL, 1525091, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-12-01', '텅 빈 모든 방', 'All the Empty Rooms', '학교 총격 사건으로 목숨을 잃은 아이들이 남긴 방. 한 기자와 사진작가가 이 방들을 기록하며 아이들을 추모한다.', 'https://image.tmdb.org/t/p/w500/jyL7Ds058lhakrhoKSMLYQQnNj1.jpg', 'MOVIE'),(391, NULL, 1262209, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'ko', '2024-04-10', '에스파: 월드 투어 인 시네마', '에스파: 월드 투어 인 시네마', '2023년 21개 도시에서 전 세계 관객을 사로잡은  글로벌 히트메이커 에스파의 첫 번째 월드 투어 ‘aespa LIVE TOUR 2023 SYNK : HYPER LINE’  그 대단원의 마지막 마침표를 찍을 무대가 극장에서 펼쳐진다.  월드투어의 마지막 챕터를 장식할 공연 실황 영화 는  영국 런던의 세계적인 공연장 O2 아레나의 뜨거웠던 현장을  14대의 시네마틱 카메라로 생생하게 담아냈다.  오직 영화에서만 만날 수 있는 월드 투어 비하인드 인터뷰 뿐만 아니라  ‘Next Level’, ‘Black Mamba’, ‘Savage’ 등 메가 히트곡과  MY들의 뜨거운 반응을 얻은 ‘Salty & Sweet’, ‘도깨비불 (Illusion)’,  그리고 멤버 4인의 솔로 무대를 포함한 풍성한 공연 셋리스트까지!  매 활동마다 NEXT LEVEL로 나아가는 글로벌 아티스트 에스파의 독보적 퍼포먼스와  월드 투어의 현장감을 ScreenX, 4DX, ULTRA 4DX 특별관  그리고 압도적인 스크린으로 경험한다.', 'https://image.tmdb.org/t/p/w500/AwzvmZXw5JwEAmuztkltRLISaeo.jpg', 'MOVIE'),(392, NULL, 805047, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'ko', '2021-11-17', '너에게 가는 길', '너에게 가는 길', '성소수자와 그 부모에 관한 다큐멘터리. 트랜스젠더인 한결과 그의 어머니 나비, 그리고 게이인 예준과 어머니 비비안, 이 네 사람의 삶을 통해 LGBTQ에 대한 한국 사회의 배타성을 폭로함과 동시에 소수자와 비소수자 간 대안적인 관계 맺기가 가능하다는 사실을 드러낸다.', 'https://image.tmdb.org/t/p/w500/v6xXjyp3c2HRfBLRRsPRn6iLFye.jpg', 'MOVIE'),(393, NULL, 757388, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2021-01-05', '오드리', 'Audrey', '영국 배우 오드리 헵번(1929~1993)의 삶과 작품, 그리고 영원한 유산을 전례 없이 친밀하게 들여다봅니다.', 'https://image.tmdb.org/t/p/w500/ikAgImz1rkedYM2mW0TeGZP1xdi.jpg', 'MOVIE'),(395, NULL, 857800, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2026-01-22', '레드 제플린의 탄생', 'Becoming Led Zeppelin', '전설적인 밴드 레드 제플린의 기원과 그들의 이야기. 레드 제플린의 경이롭고 사이키델릭한 미공개 영상과 공연, 그리고 음악과 함께 밴드 멤버들의 목소리로 직접 전해 듣는 그들의 이야기를 만나본다.', 'https://image.tmdb.org/t/p/w500/cAxteOtjaeQN045qNNbSEwu78c4.jpg', 'MOVIE'),(396, NULL, 1455575, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-04-15', '기묘한 이야기: 첫 번째 그림자 - 무대 뒤 이야기', 'Behind the Curtain: Stranger Things: The First Shadow', '호킨스의 세계관을 확장한 라이브 무대 쇼 《기묘한 이야기: 첫 번째 그림자 - 무대 뒤 이야기》. 수상 경력을 자랑하는 이 작품의 출연진 및 제작진과 함께 무대 뒤 숨겨진 이야기를 들여다본다.', 'https://image.tmdb.org/t/p/w500/vuGIlORwxgDu9Wsa3I21L2TXJqr.jpg', 'MOVIE'),(397, NULL, 1363282, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-11-19', '카맨 가족 미스터리', 'The Carman Family Deaths', '조난당한 한 청년이 바다에서 극적으로 구조된다. 그러나 곧 그는 자신의 부유한 뉴잉글랜드 가족 중 두 명을 살해했다는 의혹에 휘말리는데. 범죄 실화를 다룬 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/viwBYAZTKbNbhugoW1u0mOtDS4w.jpg', 'MOVIE'),(398, NULL, 656690, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2020-09-09', '소셜 딜레마', 'The Social Dilemma', '중독과 가짜 뉴스에 시달리는 현대사회. 실리콘 밸리 전문가들이 용기 내어 경고한다. 자신들의 창조물, 소셜 미디어를 주의하라고. 다큐멘터리와 드라마를 결합한 영화.\r 게시물을 올리고, ‘좋아요’를 누르고, 공유하고, 소셜 미디어는 우리 삶에서 빠질 수 없는 요소가 되었다. 하지만 그 대가는 무엇일까? 디지털 플랫폼이 개인과 세상을 잇는 생명줄이 된 지금, 실리콘 밸리의 내부자들이 스크린 이면에 숨은 진실을 폭로한다. 그리고 소셜 미디어가 인류의 문화를 어떻게 다시 프로그래밍하는지 보여준다.', 'https://image.tmdb.org/t/p/w500/d8oFkbWMimxNzL729r74cow3Fka.jpg', 'MOVIE'),(399, NULL, 416052, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'ko', '2015-05-07', '명량: 회오리 바다를 향하여', '명량: 회오리 바다를 향하여', '명량해전에 대한 도발적인 질문의 해답을 찾기 위해 김한민 감독과 명량의 주역들이 국내 최초 다큐 영화에 도전한다. 명량해전이 있기 직전 16일간 이순신 장군의 실제 행적을 쫓아가며 긴박했던 수군 재건 과정과 더불어 이순신 장군이 가졌던 인간적인 고민과 리더로서의 고뇌를 통해, 우리가 몰랐던 이순신의 진짜 이야기를 낱낱이 파헤친다.', 'https://image.tmdb.org/t/p/w500/9fMI9LpWnmbNeRgcTJUJCLbUGe5.jpg', 'MOVIE'),(403, NULL, 962192, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2022-06-14', '제니퍼 로페즈: 내 인생의 하프타임', 'Halftime', '세계적인 슈퍼스타 제니퍼 로페즈의 삶을 밀착 조명하는 다큐멘터리. 그녀가 여러 분야에서 펼쳐온 다양한 활동과 유명인으로 살면서 느끼는 압박을 집중 조명한다.', 'https://image.tmdb.org/t/p/w500/jUVglxBw7KSkcVEhvfJs1eipPnk.jpg', 'MOVIE'),(407, NULL, 800728, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2021-02-26', '지니 & 조지아 - 애프터파티', 'Ginny & Georgia - The Afterparty', '시즌 1은 끝났습니다. 하지만 아직 궁금한 점이 많답니다. 배우들이 들려주는 인기 시리즈 《지니 & 조지아》의 이야기. 진행자들과 그 어머니들의 대화도 놓치지 마세요.', 'https://image.tmdb.org/t/p/w500/jUCinYtvrF9n9SQCU6thTkIkFve.jpg', 'MOVIE'),(408, NULL, 448448, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2017-04-23', '킹메이커 로저 스톤', 'Get Me Roger Stone', '비열한 사기꾼? 뛰어난 전략가? 트럼프 캠페인을 주도한 정치 고문 로저 스톤. 미디어를 활용해 대중을 사로잡은 그가 자신이 완성한 게임의 법칙을 낱낱이 공개한다.', 'https://image.tmdb.org/t/p/w500/n0FXjHHG4a0apw3X4zggpIC5fih.jpg', 'MOVIE'),(409, NULL, 664280, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2020-10-04', '데이비드 애튼버러: 우리의 지구를 위하여', 'David Attenborough: A Life on Our Planet', '지금 이 순간에도 수많은 생명이 사라지고 있다. 세계적인 동물학자이자 자연 다큐멘터리의 거장이 전하는 위대한 조언. 다큐멘터리에서 그는 과거를 돌아본다. 지금껏 살아오면서 자신이 목격했던 가장 파괴적인 순간들을. 이 다큐멘터리는 지구상의 모든 생명체가 마주한 커다란 위기를 다룬다. 우리는 그동안 무엇을 잃었나. 지구의 파멸을 언제까지 지켜볼 것인가. 그는 호소한다. 지구의 재앙이 다가오고 있다. 막아야 한다. 그리고 길을 제시한다. 우리가 할 수 있는 일이 있으니 아직 희망은 있다고.\r 《데이비드 애튼버러: 우리의 지구를 위하여》는 다수의 상을 받은 자연 다큐멘터리 전문 제작사 실버백 필름스(Silverback Films)와 국제적 환경 단체인 세계자연기금이 함께 만든 독보적인 장편 다큐멘터리다. 누구보다도 많은 자연계를 지켜본 데이비드 애튼버러가 들려주는 우리 지구의 생명에 관한 이야기. 그는 90년이 넘는 세월, 전 세계 모든 대륙을 찾아 지구의 야생 세계를 탐험하며 다양하고 경이로운 모습으로 살아 숨 쉬는 세상을 기록해 왔다. 우리의 지구가 직면한 가장 어려운 문제들을 다루는 이 다큐멘터리는 미래의 세대에게 강력한 희망의 메시지를 전달하는 작품이다.', 'https://image.tmdb.org/t/p/w500/L05FleZHcTUj3FoHd6MAus1iZS.jpg', 'MOVIE'),(411, NULL, 1400784, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2025-11-17', '셀레나 이 로스 디노스: 가족의 유산', 'Selena y Los Dinos: A Family\'s Legacy', '테하노 음악의 여왕, 셀레나 킨타니야의 삶과 유산을 기리는 다큐멘터리 《셀레나 이 로스 디노스: 가족의 유산》. 셀레나와 가족이 함께 공연하고 성공을 거두며 장르의 경계를 허물었던 여정을, 가족의 개인 소장 자료의 미공개 영상을 통해 생생하게 담아낸다.\r <시놉시스> 테하노 음악의 여왕, 셀레나. 그녀의 잊을 수 없는 음악 여정은 세계적으로 알려졌지만, 셀레나를 진정으로 이해한 이는 킨타니야 가족뿐이다. 밴드 \'셀레나 이 로스 디노스\'를 함께 이끈 가족이 개인 기록 자료를 공개하며 지금껏 알려진 적 없는 셀레나의 이야기를 최초로 들려준다. 이사벨 카스트로 감독(《Mija》)이 연출한 다큐멘터리 《셀레나 이 로스 디노스: 가족의 유산》은 부모 마르셀라와 아브라함, 언니 수젯, 오빠 A.B. 3세, 남편 크리스, 그리고 밴드 멤버 등 가장 가까웠던 사람들의 목소리를 통해 셀레나 킨타니야의 눈부신 시작과 폭발적인 성공을 조명한다. 레이크 잭슨의 텍사스풍 멕시코 식당에서 저녁 공연을 하던 초창기부터, 셀레나의 타고난 재능과 빛나는 매력이 점차 세상에 알려지며 마침내 테하노 음악 차트 정상에 오르기까지, 셀레나 가족의 음악 여정을 차례로 담아낼 예정. 동생이자 딸, 아내이기도 했던 셀레나의 새로운 모습이 담긴 홈비디오를 비롯한 미공개 영상까지 만나볼 수 있는 이 작품은, 지역색 강한 테하노 음악과 주류 음악 차트의 벽을 허문 킨타니야 가족 밴드, 그리고 그 가족의 일원으로서 어린 시절 자라며 배운 방식 그대로 그 눈부신 성과를 이끌었던 슈퍼스타 보컬리스트의 이야기를 생생히 들려준다.', 'https://image.tmdb.org/t/p/w500/eoKeIeoJAkJFQ1YaoMY51naSlly.jpg', 'MOVIE'),(413, NULL, 1146302, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2023-11-03', '슬라이', 'Sly', '험난한 유년기의 탈출구로 영화를 사랑하게 된 남자. 보잘것없던 무명 배우에서 할리우드의 전설이 된 실베스터 스탤론이 자신의 이야기를 들려주는 다큐멘터리.', 'https://image.tmdb.org/t/p/w500/1utWajLPvv1R9ZwkD98s2ZEngS.jpg', 'MOVIE'),(414, NULL, 566222, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2019-07-24', '거대한 해킹', 'The Great Hack', '2016년 대선 이후, 거대한 스캔들이 미국을 강타한다. 시민의 일거수일투족을 수집한 데이터 분석 회사. 그들은 누구를 위해, 누구와 함께 일했을까. 그 전말을 확인하라.\r 데이터가 석유를 능가해 세계에서 가장 가치 있는 자산으로 등극했다. 이제 데이터는 문화적, 정치적 전쟁을 위해 무기화되고 있다. 도처에서 우리의 내밀한 개인 정보를 장악하려는 경쟁이 진행 중이다. 수상 경력에 빛나는 영화감독 카림 아메르와 제한 누젬이 만든 다큐멘터리 《거대한 해킹》은 이러한 데이터 착취의 어두운 세계를 폭로한다. 충격적 파장을 일으킨 케임브리지 애널리티카와 페이스북 스캔들에 연루된 핵심 인물들을 이례적으로 집중 조명했다. 아카데미상 후보에 이름을 올린 아메르와 누젬 감독(《해방광장》 《컨트롤 룸(Control Room)》 《스타트업 닷컴(Startup.com)》)은 강렬하고 다층적인 작품을 통해 소셜미디어가 몰고 온 일대 파문들에 천착하는 작업을 이어가고 있다. 《거대한 해킹》은 우리가 일상적으로 소비하는 정보의 원천에 대해 질문하게 만든다. 디지털 시대에 스마트폰이나 컴퓨터 키보드를 두드려 자신에 대해 공유하면서 우리는 무엇을 내주고 있을까? 2019년 선댄스 영화제에서 첫선을 보인 《거대한 해킹》은 아메르와 누젬 감독이 연출을 맡고 카림 아메르, 제럴린 드라이퍼스, 주디 코린, 페드로 코스가 제작했다.', 'https://image.tmdb.org/t/p/w500/f3YhRJEepmgT2aQNTDkUKgRcxH2.jpg', 'MOVIE'),(415, NULL, 653610, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2020-06-19', '디스클로저', 'Disclosure', '할리우드는 트랜스 커뮤니티에 어떤 영향을 끼쳤을까. 그 빛과 그늘을 조명하는 다큐멘터리. 선도적인 트랜스 창작자와 사상가들이 진솔한 견해와 분석을 들려준다.', 'https://image.tmdb.org/t/p/w500/2MB2FPNxdSlykbH7ghBltoBYnTH.jpg', 'MOVIE'),(416, NULL, 726887, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2020-08-26', '불사조, 비상하다', 'Rising Phoenix', '장애란 무엇이며, 정상이란 무엇인가. 탁월함은 어디에서 오는가. 각자의 도전을 돌아보는 패럴림픽 선수들. 한계를 넘어, 가능성을 만드는 그들의 이야기를 만난다.', 'https://image.tmdb.org/t/p/w500/oso09gID2bFk9q3Cni8GNOuzTWZ.jpg', 'MOVIE'),(417, NULL, 593691, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2019-04-17', '비욘세의 홈커밍', 'HOMECOMING: A film by Beyoncé', '비욘세의 2018 코첼라 페스티벌! 세계적인 찬사를 받는 그녀만의 특별함은 무엇인가. 섬세하게 준비된 완벽한 공연을 통해, 음악을 넘어 문화를 창조하는 그녀를 만난다.', 'https://image.tmdb.org/t/p/w500/nKdP4K3Bj3qnjtDCq9lTg7UOHVy.jpg', 'MOVIE'),(418, NULL, 1214506, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2024-09-27', '윌과 하퍼', 'Will & Harper', '윌 페럴의 오랜 친구 하퍼가 트랜스젠더 여성으로 등장하면서 기획된 자동차 여행. 두 친구가 우정을 재확인하고, 동시에 하퍼의 참모습도 세상에 공개하는 여정을 들여다본다.', 'https://image.tmdb.org/t/p/w500/wpQP48Z15VnjH0MWZrvDS25Pf0Y.jpg', 'MOVIE'),(419, NULL, 685264, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'en', '2021-06-16', '프레이 어웨이', 'Pray Away', '동성애를 정신병의 일종이라고 믿고 동성애자들을 기독교의 교리로 이성애자로 전환시킬 수 있다는 미국내 기독교 단체가 끼친 문제점을 고발한 다큐멘터리', 'https://image.tmdb.org/t/p/w500/1wikrtZZZoThwnHulB7klQek4Ai.jpg', 'MOVIE'),(420, NULL, 1056099, '2026-01-29 12:23:28', '2026-01-29 12:23:28', 'ko', '2023-10-06', '노란문: 세기말 시네필 다이어리', '노란문: 세기말 시네필 다이어리', '세상에 공개되지 않은 봉준호 감독의 첫 단편 \"룩킹 포 파라다이스\"를 본 이들은 ‘노란문 영화연구소’의 멤버 십여 명뿐이다. 어둡고 더러운 지하실의 고릴라가 똥벌레의 공격을 피해 낙원으로 향하는 이야기의 이 스톱모션 애니메이션은 청년 봉준호가 속해있던 ‘노란문’의 송년회에서 처음 공개되었다. 이후 30년간 오동나무 상자에 담겨 봉준호의 서재에 깊숙이 숨겨져 있던 8mm 필름 상자가 열리자 90년대 초 시네필들의 추억도 와르르 쏟아진다. “다들 미친 듯이 영화 공부를 하던” 영화광 시대에 ‘노란문’은 그들만의 시네마테크이자 영화학교였고 무엇보다 이상적인 청년공동체였다.', 'https://image.tmdb.org/t/p/w500/zAHzCqQP65lYMOtABVpoA5ZGWBy.jpg', 'MOVIE'),(421, NULL, 39068, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2008-05-05', '너는 내 운명', '너는 내 운명', '드디어…서른 여섯 살 노총각 인생에 사랑이 찾아왔습니다.\n\n사랑하는 사람이 나타나기를 꼬박 손꼽아 기다리기 서른 여섯 해. 천사 같은 그녀가 스쿠터를 타고 제 곁을 스쳐 지나갔습니다. 사람들은 그녀가 서울에서 갓 내려 온 다방 아가씨라고 합니다. 차 배달도 나가고 다른 남자들과 술도 마신다고 했습니다. 그러나, 저는 틈만 나면 그녀를 보러 다방으로 달려갔습니다. 장미꽃과 갓 짠 우유를 그녀에게 선물했습니다. 그녀와 함께 있고 싶은 마음에 난생 처음 티켓을 끊기도 했습니다.\n\n그러나, 그녀는 사랑 따위는 필요 없다 합니다. \n\n그녀는 절 쉽게 받아주지 않았습니다. 사랑 따윈 필요 없다며. 그러던 어느 날, 저는 우연히 그녀의 눈물을 보게 되었습니다. 그녀도 사실은 사랑 받으며 행복하게 살고 싶어한다는 걸 알게 되었습니다. 그녀의 그 눈물을 씻어줄 수 있는 사람이 나였으면 좋겠다고 생각했습니다. 그래서 그 날, 저는 용감하게 마음을 고백했습니다. 세상에서 제일 행복하게 해주겠다고. 그리고 마침내, 그녀는 내 진심을 받아주었습니다. \n\n그녀와 함께 있으면 세상 모든 걸 가진 것 같았습니다. 그런데…\n\n행복한 순간이 영원할 줄 믿었던 것도 잠시, 그녀에게 잊지 못할 과거가 찾아왔습니다. 혼자 힘들어 하는 그녀를 위해 전 재산인 젖소 목장이와 통장 5개를 처분했습니다. 이제, 우리 사랑에 더 이상의 장애는 없을 거라 믿었습니다. 그런데, 어느 날 그녀가 편지 한 통만 남긴 채 제 곁을 떠났습니다. 행복하게 살라고. 미안하다고. 며칠 후, 저는 그녀가 에이즈에 감염되었다는 청천벼락 같은 이야기를 듣게 되었습니다. 그녀가 아플 까봐 너무나 걱정이 됩니다. 내가 곁에 있어주어야 하는데. \n\n모두 그녀를 포기하라 합니다. 하지만, 저는 그녀를 끝까지 지킬 겁니다.\n\n가족도, 친구도, 세상도 모두 그녀를 찾지 말라고 합니다. 하지만 저는 그녀 없으면 한시도 살 수 없습니다. 죽을 때까지, 아니 죽어서도 그녀를 지켜야 합니다. \n\n왜냐하면.. 그녀는 제 운명이기 때문입니다.', 'https://image.tmdb.org/t/p/w500/2T517OGQXPoe8l3dLuw79ymYQ6F.jpg', 'TV'),(422, NULL, 18376, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2007-06-23', '황금신부', '황금신부', '베트남에서 시집 온 누엔진주와 그녀의 가족을 둘러싼 이야기를 담은 드라마', 'https://image.tmdb.org/t/p/w500/yVtMOotArgquedM1FWkYjwTj9bl.jpg', 'TV'),(423, NULL, 59603, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2013-04-27', '출생의 비밀', '출생의 비밀', '해리성 기억장애로 사랑하는 남자와 아이에 대한 기억을 잃은 여자의 딜레마와 천재 딸을 대하는 무식한 아버지의 눈물 어린 부성애를 그린 드라마.', 'https://image.tmdb.org/t/p/w500/cwZIjIknucYLzEly5MPLr0ZkSbZ.jpg', 'TV'),(424, NULL, 63787, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2014-04-05', '엔젤 아이즈', '엔젤 아이즈', '아픈 가족사 때문에 첫 사랑을 떠나보낸 남녀 주인공이 12년 후 재회하면서 벌어지는 이야기', 'https://image.tmdb.org/t/p/w500/342Qs3tsCEQehSKf5Qo8lZMaopD.jpg', 'TV'),(425, NULL, 32769, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2008-10-27', '그들이 사는 세상', '그들이 사는 세상', '제작진의 실제 삶이 오히려 그들이 만드는 인기 TV 드라마 못지않게 드라마틱할 수 있다! 방송가의 뒷이야기를 그린 작품', 'https://image.tmdb.org/t/p/w500/wGat96oivlQeAxSZwehSa1HJvqG.jpg', 'TV'),(426, NULL, 14731, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2007-03-21', '마녀유희', '마녀유희', '일에는 성공했지만 사랑에서는 성공하지 못한 여자의 이야기를 그린 드라마. 맛있는 이야기, 그래서 더 행복한 드라마.\n\n현재 상황은 완벽하지만 2% 부족한 아픔이 있는 커리어 우먼 마유희와 처한 상황은 열악하지만 꿈과 희망이란 열정이 있어 행복한 요리지망생 채무룡이 펼치는 좌충우돌 인생기. 여기에 일류 요리사를 꿈꾸는 무룡의 프랑스식 퓨전 요리가 만들어내는 맛있는 연애가 시작된다.', 'https://image.tmdb.org/t/p/w500/z0gdlKGva3R4wFGA4XK52dQ22sR.jpg', 'TV'),(427, NULL, 46578, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2011-01-23', '신기생뎐', '신기생뎐', '역사의 뒤안길에 사라진 기생 문화가 현존한다는 전제 속에 부용각에서 펼쳐지는 삶과 사랑의 이야기', 'https://image.tmdb.org/t/p/w500/65FNgLEOjzVBssxYrfzUlhs0vfK.jpg', 'TV'),(428, NULL, 30735, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2009-07-27', '드림', '드림', '소년원 출신 격투기 선수와 스포츠에이전트가 어려움을 극복하고 성공에 이르는 과정을 담은 드라마이다.\n\n', 'https://image.tmdb.org/t/p/w500/i5XgEXp6q2rsehJwlZ0apthhjnX.jpg', 'TV'),(429, NULL, 62863, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2015-06-08', '상류사회', '상류사회', '황금 수저를 입에 물고 태어난 재벌딸과 황금사다리를 오르려는 개천용, 두 사람의 불평등한 계급 간 로맨스를 통해 진정한 사랑의 의미와 오포 세대 청춘들에게 희망의 메시지를 전하는 청춘 멜로 드라마다.', 'https://image.tmdb.org/t/p/w500/gldDUMK6AUdbFrCIDJgVEY0V02x.jpg', 'TV'),(430, NULL, 5208, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2006-05-17', '스마일 어게인', '스마일 어게인', '두 남자의 우정이 한 여자를 사랑하게 되며 그려지는 엇갈린 사랑 이야기.', 'https://image.tmdb.org/t/p/w500/rZpOAZrzcjG6GzF3SozhRRBuayw.jpg', 'TV'),(431, NULL, 63624, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2013-12-02', '따뜻한 말 한마디', '따뜻한 말 한마디', '모든 상처와 장애를 끌어안고 가정을 지키기 위해 아슬아슬 외줄 타기를 하는 두 부부의 갈등을 리얼하게 다루며 복잡 미묘한 결혼생활의 현실을 그리는 드라마', 'https://image.tmdb.org/t/p/w500/2coho0RSrTNiBOfrdPbgw3po8eX.jpg', 'TV'),(432, NULL, 61021, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2004-08-28', '매직', '매직', '신세대 마술사의 사랑과 야망, 배신과 파멸을 다룬 트렌디 드라마이다.', 'https://image.tmdb.org/t/p/w500/eUn5tS9yQUVGPINDI0ETcZ3NSmm.jpg', 'TV'),(433, NULL, 64176, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2013-11-09', '세 번 결혼하는 여자', '세 번 결혼하는 여자', '한 어머니와 두 딸의 집안을 중심으로 펼쳐지는 이야기', 'https://image.tmdb.org/t/p/w500/cgwIkoFAPjQiEs7CANyL9B9KnHC.jpg', 'TV'),(434, NULL, 62651, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2007-06-15', '8월에 내리는 눈', '8월에 내리는 눈', '상처받은 33살의 이혼녀, 27살의 미혼부가 만나 서로의 상처를 보듬으며 힘겨운 사랑을 헤쳐 나가는 과정을 그린 드라마.', 'https://image.tmdb.org/t/p/w500/d0Bz76JN2xuSXmIMRYbNI3UwBVF.jpg', 'TV'),(435, NULL, 32824, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2009-09-26', '그대 웃어요', '그대 웃어요', '갑자기 몰락한 건설회사 재벌 집안이 수십년간 일해온 자가용 기사의 집에 얹혀 살게 되면서 벌어지는 에피소드를 그린 가족 드라마다.', 'https://image.tmdb.org/t/p/w500/8qY3zN0QAWMbCim6EeR08X6KpxE.jpg', 'TV'),(436, NULL, 8418, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2007-07-28', '칼잡이 오수정', '칼잡이 오수정', '오광고 최고의 퀸카 오수정은 사시에 붙었다는 이유로 폭탄으로 유명한 고만수와의 결혼식을 감행한다. 생각없이 사람좋은 아버지 때문에 집안이 풍지박산의 위기에 처한 수정은 결혼식 당일, 만수로부터 3차에서 떨어졌다는 고백을 듣게 되고, 결혼식 행진 도중 갑자기 뒤돌아 달리기 시작하는데... 수정은 필숙이 만수를 만났다는 얘기를 듣고 필숙을 찾아간다. 필숙은 그런 수정의 속내를 꼬집어 내고, 내숭떨던 수정은 본색을 드러낸다. 필숙은 수정에게 만수를 잡을 생각하지 말고 수준에 맞는 남자를 만나라고 충고하고, 수정은 예전과 달라진 자신을 보며 허탈해 하는데...', 'https://image.tmdb.org/t/p/w500/eQtZgNz8gIIXUkVGqZnJbX8XzqF.jpg', 'TV'),(437, NULL, 62610, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2014-07-14', '유혹', '유혹', '한 남자가 매혹적인 제안을 받고 이어지는 관계들 속에서 진정한 사랑의 의미를 찾아가는 멜로드라마', 'https://image.tmdb.org/t/p/w500/5xOdtKkmEeloXUJJEuNvK2FXNGp.jpg', 'TV'),(438, NULL, 64206, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2015-01-17', '내 마음 반짝반짝', '내 마음 반짝반짝', '서민의 딸로 태어난 여자가 가진 자들의 횡포 속에서 집안의 복수와 아버지의 복수, 자신의 성공을 위해 살아가는 이야기', 'https://image.tmdb.org/t/p/w500/nHkgWeB8i5kBx7zFDChbDEjOlDZ.jpg', 'TV'),(439, NULL, 62925, '2026-01-29 12:23:30', '2026-01-29 12:23:30', 'ko', '2015-06-27', '너를 사랑한 시간', '너를 사랑한 시간', '오랜 시간 동안 우정을 이어 온 두 남녀가 서른이 되며 겪게 되는 성장통을 그린 드라마. 슈즈 론칭을 앞두고 모델이 잠적하는 바람에 모든 일이 꼬여버린 하나. 그 와중에 애인은 곧 결혼한다는 충격적인 통보를 하고, 하나는 제 연애의 모든 원흉이 원이 때문인 것만 같다. 하나의 하소연을 묵묵히 받아 주던 원은 하나에게 말할 수 없는 사정 때문에 답답하기만 한데...', 'https://image.tmdb.org/t/p/w500/iRBHCrAwrs9SbkLb0JfogQ5o7gZ.jpg', 'TV'),(440, NULL, 79744, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2018-10-16', '더 루키', 'The Rookie', '이혼 후 은행 강도를 당한 일을 계기로 LAPD에 지원한 40세의 최고령 신입을 중심으로 펼쳐지는 이야기', 'https://image.tmdb.org/t/p/w500/7LUiqnZFX9JXYZtRpzv8n7taKV.jpg', 'TV'),(441, NULL, 1408, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2004-11-16', '하우스', 'House', '2004년 11월 FOX에서 방영을 시작한 미스터리 의학 시리즈. 프린스턴 플레인즈보로 대학병원의 진단의학과 과장인 그레고리 하우스는 환자들을 성심성의껏 돌보는 데는 영 꽝인 의사. 사사건건 병원 원장인 리사 커디와 부딪히는 그는 못된 매너와 그 매너를 더욱 돋보이게 하는 외모로 유명하지만, 또한 창조적인 생각과 결점없는 의학적 본능을 유감없이 발휘하는 최고의 의사이기도 하다. 천재적인 분석능력을 갖춘 전염병 전문의로서 그가 이제 인명을 살리기 위한 흥미롭고 미스터리한 의학의 퍼즐을 풀어간다.', 'https://image.tmdb.org/t/p/w500/3Cz7ySOQJmqiuTdrc6CY0r65yDI.jpg', 'TV'),(442, NULL, 34307, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2011-01-09', '쉐임리스', 'Shameless', '미국 시카고 후미진 마을에서 힘겹게 살고 있는 싱글 대디 프랭크와 총명하고 독립적인 그의 여섯 자녀들의 리얼한 이야기', 'https://image.tmdb.org/t/p/w500/9ZTivNsXHQWVq578CIsvsM5zd08.jpg', 'TV'),(444, NULL, 1400, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '1989-07-05', '사인필드', 'Seinfeld', '코미디언 제리 사인필드가 직접 자신의 삶을 무대로 연기한 드라마.\n\n래리 데이비드(《Curb Your Enthusiasm》)와 제리 사인펠드 제작. 뉴욕에 사는 4명의 싱글 친구들이 등장하는 거침없는 시트콤. 《LA Times》는 \'끝내주는 작품\'이라고 평했다.', 'https://image.tmdb.org/t/p/w500/aCw8ONfyz3AhngVQa1E2Ss4KSUQ.jpg', 'TV'),(445, NULL, 60625, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2013-12-02', '릭 앤 모티', 'Rick and Morty', '술에 절어 사는 천재 과학자 릭은 투정이 심한 10대 손자 모티를 데리고 외계와 대체 현실로 아슬아슬한 모험을 떠난다.', 'https://image.tmdb.org/t/p/w500/WGRQ8FpjkDTzivQJ43t94bOuY0.jpg', 'TV'),(446, NULL, 502, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '1969-11-10', '세서미 스트리트', 'Sesame Street', '새서미 스트리트는 미국 어린 아이들을 위한 장수 TV 시리즈였습니다. 이 프로그램은 교육적인 목적으로 만들어졌지만 짐 핸슨의 인형극, 애니메이션, 짧은 영화, 유머와 문화에 대한 내용들로 매우 창의적인 내용들을 다루고 있습니다. 첫 시리즈는 1969년 11월 10일 방영되었으며 당시 긍정적인 리뷰가 있었고 논란이 되기도 하였고 높은 평가를 받았습니다.', 'https://image.tmdb.org/t/p/w500/wZC3fXTxR00YCjgqkc1N20seZJb.jpg', 'TV'),(447, NULL, 71728, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2017-09-25', '영 셸던', 'Young Sheldon', '\'빅뱅이론\'의 주인공 셸든 쿠퍼의 어린 시절을 다룬 이야기.', 'https://image.tmdb.org/t/p/w500/c9J6uYthPPYpBHjOVEEWg7MvMtY.jpg', 'TV'),(448, NULL, 307534, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2026-01-22', '버트에게 자유를', 'Free Bert', '엉뚱하고 막무가내인 아빠와, 그 못지않게 필터 없는 가족. 명문 사립 학교의 잘난 척하는 엘리트 가족들 틈에 끼어 보려다, 그야말로 난장판이 벌어진다.', 'https://image.tmdb.org/t/p/w500/bQ0nPGGESLVKejaAwbgb7noQhzQ.jpg', 'TV'),(450, NULL, 4586, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2000-10-05', '길모어 걸스', 'Gilmore Girls', '독립심이 강한 싱글맘 로렐라이는 아이비리그 진학은 문제없을 정도로 명석한 두뇌를 가진 딸 로리를 키운다. 이 모녀 사이에는 항상 재치 넘치는 대화가 끊이지 않는다.', 'https://image.tmdb.org/t/p/w500/gwtzCwU2wdLLf8oejQu2TINiWfQ.jpg', 'TV'),(451, NULL, 119051, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2022-11-23', '웬즈데이', 'Wednesday', '똑똑함은 기본, 비꼬는 것에도 도가 튼 웬즈데이 아담스. 암울함을 풍기는 그녀가 네버모어 아카데미에서 얽히고설킨 미스터리를 파헤치기 시작한다. 새 친구도 사귀고, 앙숙도 만들며.', 'https://image.tmdb.org/t/p/w500/oCpvKD0yuRV9OAZ8xklRy9HWc6l.jpg', 'TV'),(452, NULL, 229891, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'ko', '2026-01-16', '이 사랑 통역 되나요?', '이 사랑 통역 되나요?', '촬영차 전 세계를 오가는 스타 배우와 그녀의 통역사. 서로를 향한 마음이 깊어지는 것과 달리 설렘의 감정은 자꾸만 오역이 되는데. 과연 둘만의 사랑의 언어를 찾을 수 있을까?', 'https://image.tmdb.org/t/p/w500/ePz0D6B6wbxoLHsUtcaqfGx7E41.jpg', 'TV'),(453, NULL, 48891, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2013-09-17', '브루클린 나인-나인', 'Brooklyn Nine-Nine', '경찰의 명예를 중시하는 원칙주의자 홀트 서장. 그 아래 재능은 물론 꼼수, 공갈, 운까지 총동원해서 어떻게든 사건을 해결해내는 듬직한(?) 형사들이 있는 곳. 브루클린 99 관할 경찰서에 오신 것을 환영합니다!', 'https://image.tmdb.org/t/p/w500/A3SymGlOHefSKbz1bCOz56moupS.jpg', 'TV'),(455, NULL, 33238, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'ko', '2010-07-11', '런닝맨', '런닝맨', '대한민국 최고의 연예인들이 곳곳에 있는 미션을 해결하고, 끊임없는 질주와 긴박감 넘치는 대결을 통해 대한민국 랜드마크들의 숨겨진 뒷모습을 전격 공개하는 프로그램', 'https://image.tmdb.org/t/p/w500/15SMnscZqd7HZ0bzruatOcKUlOV.jpg', 'TV'),(456, NULL, 62117, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2015-03-31', '영거', 'Younger', '갑작스러운 이혼으로 새로운 일을 시작하려 하나 적지 않은 나이로 고민하는 주인공을 돕는 친구 덕분에 위장 취업을 하게 되면서 생기는 이야기', 'https://image.tmdb.org/t/p/w500/bIFp20ZUg3kPOfR5FUuAE5cxhHh.jpg', 'TV'),(457, NULL, 61222, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2014-08-22', '보잭 홀스맨', 'BoJack Horseman', '90년대 최고의 시트콤 스타였던 보잭은 과연 20년 후 어떤 모습으로 살고 있을까? 괴팍한 동물이지만 마음만은 비단결인 보잭. 아니, 비단까지는 아니고 명주 정도 되려나?', 'https://image.tmdb.org/t/p/w500/Acr7CdUX6L96heNHooKaESqW1Al.jpg', 'TV'),(458, NULL, 77169, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2018-05-02', '코브라 카이', 'Cobra Kai', '지독한 숙적, 치열하게 싸우는 도장, 그리고 새로운 세대. 과거 라이벌이었던 다니엘과 조니가 웨스트 밸리를 배경으로 다시 한번 충돌한다. 영화 《베스트 키드》 시리즈의 반가운 속편.', 'https://image.tmdb.org/t/p/w500/smVIOAVCcoaBTx054SO9SiyDqep.jpg', 'TV'),(459, NULL, 37606, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2011-05-03', '검볼', 'The Amazing World of Gumball', '12살 사고뭉치 파란 고양이 검볼. 돈 버느라 언제나 바쁜 엄마. 게임과 TV에 빠진 철부지 아빠. 어리지만 똑소리 나는 여동생. 늘 검볼과 함께하는 금붕어 절친. 평범한 듯 특별한 검볼 가족의 시끌벅적한 일상을 그린 애니메이션.', 'https://image.tmdb.org/t/p/w500/VYnnyA2hyxi3VUPgCA71mMtt69.jpg', 'TV'),(460, NULL, 139798, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'ko', '2021-12-18', '솔로지옥', '솔로지옥', '매력적인 싱글 남녀가 무인도에 갇혔다. 누군가와 커플이 되는 게 유일한 탈출 방법. 근데 커플들이 \'천국도\'로 이동해 밤을 불태울 때, 솔로는 \'지옥도\'에 남아 자급자족해야 한다고?', 'https://image.tmdb.org/t/p/w500/tF3G9yCgmTzcAWx22c7fZZLRURk.jpg', 'TV'),(462, NULL, 45140, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2013-04-23', '틴 타이탄 GO!', 'Teen Titans Go!', '10대 히어로들의 평범하지만 평범하지 않은 일상을 그린 틴 타이탄의 외전격인 애니메이션', 'https://image.tmdb.org/t/p/w500/kPKAigYUlWRpnfo4Ptiwlz4FWXU.jpg', 'TV'),(463, NULL, 38693, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2012-01-11', '레고 닌자고', 'Ninjago: Masters of Spinjitzu', '최초의 스핀짓주 마스터로 부터 내려져온, 선과 악의 대결을 종결시킬 그린닌자(로이드)를 지키기 위해, 마스터 우는 불, 번개, 얼음, 흙의 속성을 가진 원소 마스터들을 훈련시키는데....', 'https://image.tmdb.org/t/p/w500/beKgqwruOGmVAvRwRvfuOcXwl2Z.jpg', 'TV'),(464, NULL, 186, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2005-08-07', '위즈', 'Weeds', '제목인 Weeds는 영어로 대마초를 가리키기도 하고, 과부가 입는 검정색 로브를 칭하기도 한다. 캘리포니아의 평범한 중-상층 주부였던 낸시 바트윈이 남편의 갑작 스러운 죽음 후에 생계유지를 위해 대마초를 떼다팔며 일어나는 에피소드를 다루고 있다.', 'https://image.tmdb.org/t/p/w500/gKUsBTa5b0GY7U4iWBseeBalfjO.jpg', 'TV'),(465, NULL, 1424, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2013-07-11', '오렌지 이즈 더 뉴 블랙', 'Orange Is the New Black', '한때의 실수라고만 믿었다. 하지만 이제는 죗값을 치러야 한다. 안락한 삶을 뒤로하고, 여성 교도소에 수감된 뉴요커. 이 잔혹한 정글에선 누가 친구이고 누가 적일까.', 'https://image.tmdb.org/t/p/w500/ekaa7YjGPTkFLcPhwWXTnARuCEU.jpg', 'TV'),(466, NULL, 14929, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2007-10-14', '하트랜드', 'Heartland', '야무진 소녀 에이미는 어머니의 갑작스럽게 죽은 충격에서 헤어나지 못 한다. 한편 에이미와 그녀의 할아버지는 목장을 잃을 수 있는 위기에 봉착한다.', 'https://image.tmdb.org/t/p/w500/uc2gtWczT58BiAUJWFz9P5aZmNF.jpg', 'TV'),(468, NULL, 33765, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2010-10-10', '마이 리틀 포니: 우정은 마법', 'My Little Pony: Friendship Is Magic', '포니 트와일라잇 스파클과 다섯 명의 포니가 가까운 친구가 되면서 우정에 생긴 문제들을 함께 해결해 나가는 모험담을 그린 애니메이션', 'https://image.tmdb.org/t/p/w500/iqpxbJX66AjG7iS5CxbEbRLlse8.jpg', 'TV'),(469, NULL, 10283, '2026-01-29 12:23:32', '2026-01-29 12:23:35', 'en', '2009-09-17', '아처', 'Archer', '상냥하고 세련된 스파이 아처는 멋진 장치로 무장했지만 상사인 어머니와는 여전히 부딪친다.', 'https://image.tmdb.org/t/p/w500/vhnrkTGYPqcB63ALcSJm0WoaKHT.jpg', 'TV'),(471, NULL, 82596, '2026-01-29 12:23:32', '2026-01-29 12:23:32', 'en', '2020-10-02', '에밀리, 파리에 가다', 'Emily in Paris', '새로운 열정과 새로운 패션. 그리고 새로운 에밀리? 결단력 있는 미국인 마케터 에밀리가 파리에서 꿈꾸던 일을 하게 되면서 새로운 삶과 사랑을 헤쳐 나간다.', 'https://image.tmdb.org/t/p/w500/qADiIcbPT27MxUiS9yi4oy9JBZB.jpg', 'TV'),(473, NULL, 81356, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'en', '2019-01-11', '오티스의 비밀 상담소', 'Sex Education', '상담사 엄마 덕분에 섹스 이론에 도가 튼 소심한 소년, 오티스. 아웃사이더 소녀 메이브는 그런 오티스에게 학교에 섹스 클리닉을 열자고 제안한다.', 'https://image.tmdb.org/t/p/w500/g2Os8JGYCEvBVrqW5WccNZ57NOD.jpg', 'TV'),(474, NULL, 74204, '2026-01-29 12:23:33', '2026-01-29 12:23:35', 'en', '2017-09-29', '빅 마우스', 'Big Mouth', '오, 놀랍고 위대한 사춘기여! 10대들의 삶을 완전히 뒤흔드는구나! 닉 크롤과 앤드루 골드버그 콤비가 사이좋게 만들었다, 재기발랄 사춘기 예찬 코미디.', 'https://image.tmdb.org/t/p/w500/dW3LxhCQyHWFzDB8vDtABvintET.jpg', 'TV'),(477, NULL, 112888, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'ko', '2020-12-09', '여신강림', '여신강림', '외모 콤플렉스를 가지고 있다가 화장을 통해 여신이 된 주경과 남모를 상처를 간직한 수호가 만나 서로의 비밀을 공유하며 성장하는 자존감 회복 로맨틱 코미디', 'https://image.tmdb.org/t/p/w500/gaCOvKGG2qEnsijNHEAigYcQ1U3.jpg', 'TV'),(486, NULL, 97645, '2026-01-29 12:23:33', '2026-01-29 12:23:36', 'en', '2020-05-08', '솔라 오포짓', 'Solar Opposites', '외계인 가족이 지구에 불시착한 후 한 마을에 정착하면서 생기는 갈등과 유머를 다룬 애니메이션', 'https://image.tmdb.org/t/p/w500/1qh0b8ogKAfvj01G7RKTu2Lev1J.jpg', 'TV'),(488, NULL, 62320, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'en', '2015-05-08', '그레이스 앤 프랭키', 'Grace and Frankie', '에미상 후보에 오른 시리즈. 고상한 그레이스와 괴짜 프랭키는 친구 사이는 아니지만 남편들이 서로에게 사랑에 빠져 그들을 떠나자 유대를 쌓기 시작한다.', 'https://image.tmdb.org/t/p/w500/3aD3PaSeF8eHJFLliLlWYw4EcPt.jpg', 'TV'),(490, NULL, 198004, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'ko', '2023-06-17', '킹더랜드', '킹더랜드', '세상에는 의지와 상관없이 웃어야 하는 사람들도 있고, 억지로 웃지 않아도 지장 없는 사람들이 있다. 누군가에게 웃음은 생존 도구이고, 누군가에 웃음은 아량이다. 일상에서 웃는 얼굴은 편하다. 갑은 보기 좋아 편하고, 을은 자신을 감출 수 있어 편하다. 그러는 사이 웃음은 기호로 남고 진실은 사라진다. 이 드라마는 진짜로 환하게 웃을 수 있는 날을 만들어가는 사람들 이야기이다.', 'https://image.tmdb.org/t/p/w500/7LiOlsfy8rlD9BojJ8qSYqFh4e4.jpg', 'TV'),(491, NULL, 218539, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'ko', '2023-11-24', '마이데몬', '마이데몬', '냉혹한 악마와 차가운 상속녀. 둘이 우연한 만남으로 얽히면서 악마의 능력이 사라진다. 그런데 어쩌면 그 능력과 악마의 마음을 되살릴 열쇠가 상속녀에게 있을지 모른다.', 'https://image.tmdb.org/t/p/w500/hHCFsQaVW7oeh0MfZTL2A4c5dRS.jpg', 'TV'),(494, NULL, 117581, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'en', '2021-02-24', '지니 & 조지아', 'Ginny & Georgia', '자유분방한 조지아가 북부로 이사 온다. 두 아이, 지니와 오스틴을 데리고. 애들을 위해 부유한 동네에서 새 출발을 하는 거야! 하지만 그 길은 생각만큼 순탄하지 않다.', 'https://image.tmdb.org/t/p/w500/vOwunzW4dx3n0J5mH40n9jTRSwY.jpg', 'TV'),(496, NULL, 236235, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'en', '2024-03-07', '젠틀맨: 더 시리즈', 'The Gentlemen', '가족의 부동산을 물려받은 귀족 에디는 그곳이 거대한 대마초 제국의 본거지였음을 알게 된다. 그리고 그 운영자들이 한 발짝도 물러나지 않을 거라는 사실도.', 'https://image.tmdb.org/t/p/w500/tw3tzfXaSpmUZIB8ZNqNEGzMBCy.jpg', 'TV'),(497, NULL, 270420, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'ko', '2026-01-16', '오늘부터 인간입니다만', '오늘부터 인간입니다만', '행여라도 인간이 될까봐 선행과 남자를 멀리하는 괴짜 구미호와 자기애 과잉 축구 선수 스타의 혐관 로맨스 드라마', 'https://image.tmdb.org/t/p/w500/wPqwfPOfJOMLFR1ZF2HL6mcpVas.jpg', 'TV'),(498, NULL, 67915, '2026-01-29 12:23:33', '2026-01-29 12:23:33', 'ko', '2016-12-02', '도깨비', '쓸쓸하고 찬란하神-도깨비', '2016년 12월 tvN에서 방영을 시작한 드라마. 도깨비 설화를 모티브로 김은숙 작가가 3년 전부터 기획하였으며 사극과 현대극을 오가는 판타지적인 요소를 강조한 드라마이다. 당신이 세상에서 멀어지고 있을 때 누군가 세상 쪽으로 등을 떠밀어 주었다면, 그건 신이 당신 곁에 머물다 가는 순간이다.불멸의 삶을 끝내기 위해 인간 신부가 필요한 도깨비, 그리고 그와 기묘한 동거를 시작한 기억상실증 저승사자. 그런 그들 앞에 도깨비 신부라 주장하는 죽었어야 할 운명의 소녀가 나타나며 벌어지는 신비로운 낭만 설화.', 'https://image.tmdb.org/t/p/w500/qZMEiTsNlCQV27hHQE27ZtlPWyv.jpg', 'TV'),(504, NULL, 57532, '2026-01-29 12:23:35', '2026-01-29 12:23:35', 'en', '2013-08-12', '퍼피 구조대', 'PAW Patrol', '퍼피구조대 대장 라이더와 용감한 여섯마리의 강아지 구조대의 이야기. 안전한 어드벤쳐 베이를 만들기 위한 라이더 대장과 여섯마리 귀여운 강아지 구조대의 끊임없는 연습과 도전! 경찰견 체이스와 소방견 마샬, 공사견 러블, 미화견 로키에 해양구조견 주마와 하늘을 나는 스카이까지! 여섯마리 강아지의 엉뚱발랄 신나는 구조활동을 지켜봐주세요!', 'https://image.tmdb.org/t/p/w500/juAmsE4GC6gql0L1HsDmABkLWuX.jpg', 'TV'),(510, NULL, 12225, '2026-01-29 12:23:35', '2026-01-29 12:23:35', 'en', '2004-05-31', '페파 피그', 'Peppa Pig', '페파 피그는 엄마, 아빠, 그리고 남동생 조지와 함께 사는 활기찬 돼지입니다. 그녀는 진흙 웅덩이에 뛰어드는 것과 큰 코웃음 소리를 내는 것을 좋아합니다.', 'https://image.tmdb.org/t/p/w500/aTaGTqkbMWoy0ef0M48qJkMltxE.jpg', 'TV'),(523, NULL, 94605, '2026-01-29 12:23:35', '2026-01-29 12:23:35', 'en', '2021-11-06', '아케인', 'Arcane', '지상 도시 필트오버와 그 아래의 지하 도시 자운. 극심하게 반목하는 두 쌍둥이 도시에서, 두 자매가 서로 반대편에 서서 싸우기에 이른다. 마법 기술과 신념의 충돌 속에서 전쟁이 시작된다.', 'https://image.tmdb.org/t/p/w500/1PeuDHoxfvgTaNIrJzM6vKmJarD.jpg', 'TV'),(525, NULL, 71026, '2026-01-29 12:23:35', '2026-01-29 12:23:35', 'ko', '2014-09-01', '출동! 슈퍼윙스', '출동! 슈퍼윙스', '세상에서 가장 빠른 택배 비행기 호기와 멋진 변신 비행기 친구들 슈퍼윙스가 펼치는 세계 문화탐험 어드벤처 이야기', 'https://image.tmdb.org/t/p/w500/gvHwUZOivDtwCUB48Wdnx5BO2Vp.jpg', 'TV'),(528, NULL, 86831, '2026-01-29 12:23:35', '2026-01-29 12:23:35', 'en', '2019-03-15', '러브, 데스 + 로봇', 'Love, Death & Robots', '미스터리의 세계, 공포의 괴물, 스릴 넘치는 작전, 그리고 코믹한 연기. 세상의 모든 이야기와 장르를 담았다. 팀 밀러와 데이비드 핀처가 제작한 성인용 연작 애니메이션.', 'https://image.tmdb.org/t/p/w500/3WbLvijPjldqImRLNTqpCxvX5Ii.jpg', 'TV'),(560, NULL, 87083, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2019-03-08', 'F1: 본능의 질주', 'Formula 1: Drive to Survive', '2019년 3월 Netflix에서 방영을 시작한 다큐멘터리. 가장 빠른 자가 살아남는 세계, 포뮬러 원. 그 화려한 트랙 안팎의 치열한 풍경이 모습을 드러낸다. 최첨단 자동차, 최고의 속도, 화려한 테크닉. 이 모든 것은 그저 일부일 뿐이다. 1년 내내 전 세계에서 개최되는 레이스를 따라 서킷 안팎을 질주하는 드라이버와 팀원들. 위험한 경주에 도전하는 드라이버들과 그들 뒤에 있는 팀원 및 가족들의 모습까지, 이제껏 본 적 없는 서킷 뒤의 모습을 독점 공개한다. 지금부터 포뮬러 원의 진짜 경주가 공개된다.', 'https://image.tmdb.org/t/p/w500/bTvsFzYK4ZdbcAIPSEJ3i8uLHSh.jpg', 'TV'),(561, NULL, 96481, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2020-01-24', '오스만 제국의 꿈', 'Rise of Empires: Ottoman', '그 성벽은 결코 무너지지 않는다. 숱한 공격을 견딘 도시 콘스탄티노플. 오스만 제국의 술탄 메흐메트 2세가 그곳을 향해 진군한다. 역사를 바꾸고, 세상을 지배하기 위해.', 'https://image.tmdb.org/t/p/w500/12z1wWznKM605YtQpmYZdA3Ttgu.jpg', 'TV'),(562, NULL, 79525, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2020-04-19', '마이클 조던: 더 라스트 댄스', 'The Last Dance', '2020년 4월 ESPN과 Netflix에서 방영을 시작한 다큐멘터리. 현재까지 공개되지 않았던 500시간짜리 미공개 영상을 담은, 1997-98 시카고 불스에 초점을 맞춰 농구 황제 마이클 조던과 시카고 불스의 1990년대 황금기를 돌아본다. 시카고 불스는 어떻게 전설이 되었는가. 마이클 조던에서 스코티 피펜, 데니스 로드먼, 필 잭슨 등의 유명 인사들이 1990년대 황금기를 회고하며, 특히 1997-98 시즌의 미공개 영상과 이들의 성공 스토리가 여과 없이 공개된다.', 'https://image.tmdb.org/t/p/w500/xZbtNBY7ZFkJDTEALyYuaTHN1hB.jpg', 'TV'),(563, NULL, 46504, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2012-01-01', '헌팅맨', 'MeatEater', '전문 사냥꾼, 작가, 요리사, 환경 보호 활동가 등 다양한 이름으로 불리는 스티븐 리넬라. 그가 세계 곳곳의 척박한 오지, 때 묻지 않은 아름다운 자연을 찾아가 직접 사냥해 요리를 낸다. 야생이 길어 올린 야성, 그 날것의 세계로!', 'https://image.tmdb.org/t/p/w500/iIBlBmYupUT8n5jyiGyuh3EDmDq.jpg', 'TV'),(564, NULL, 66130, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'ko', '1992-03-31', '그것이 알고싶다', '그것이 알고싶다', 'SBS의 대표적인 시사고발 프로그램으로 사회, 종교, 미제사건 등 다양한 분야를 취재한다.', 'https://image.tmdb.org/t/p/w500/dm21RNuQAh4HmovfZgyZ8t8iAMq.jpg', 'TV'),(565, NULL, 213609, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2023-10-25', '지구 위의 생명', 'Life on Our Planet', '수십억 년에 걸쳐 지구상에서 정복하고 적응하고 생존해 온 생명체들. 그 놀라운 여정을 생생하게 담아낸 획기적인 자연 다큐시리즈.', 'https://image.tmdb.org/t/p/w500/eRE5MVKKZgpXyOJVf2JvOG6EkD7.jpg', 'TV'),(566, NULL, 102905, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2020-05-22', '히스토리 101', 'History 101', '2020년 5월 Netflix에서 방영을 시작한 다큐멘터리. 인류의 역사를 바꾼 순간들을 향해 떠난다. 우주를 향한 여정, 평등을 위한 투쟁, 사회운동과 과학의 발전, 역사를 바꾼 놀라운 발견에 관해 배우는 시간. 그 모든 것을 핵심만 담은 인포그래픽과 영상 자료를 교재 삼아, 짧고 굵은 수업이 시작된다. 이토록 쏙쏙 들어오는 수업, 또 있었을까?', 'https://image.tmdb.org/t/p/w500/3wY1EwinwrtpNZCwFmpDHZ5ISaK.jpg', 'TV'),(567, NULL, 93219, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2019-11-29', '무비: 우리가 사랑한 영화들', 'The Movies That Made Us', '영화의 역사를 바꾸고, 우리의 인생을 바꾼 영화들. 누가, 어떻게 만들었을까? 배우와 감독, 제작진과 함께 시대를 초월한 명작이 탄생한, 극적인 여정을 다시 조명한다.', 'https://image.tmdb.org/t/p/w500/l7p40cVratmPTdWrx4UFjZbANKF.jpg', 'TV'),(568, NULL, 255251, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2025-12-02', '숀 콤스: 심판의 시간', 'Sean Combs: The Reckoning', '숀 \'디디\' 콤스를 조명한 다큐멘터리 시리즈. 수십 년에 걸친 삶과 커리어를 되짚어보며 그와 \'배드 보이\' 제국을 둘러싼 충격적인 의혹들을 파헤친다.', 'https://image.tmdb.org/t/p/w500/mmV5GTO5k5NKv6FiiL5YVNnysOZ.jpg', 'TV'),(569, NULL, 289485, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2025-07-29', 'WWE: 언리얼', 'WWE: Unreal', '먼데이 나이트 RAW부터 레슬매니아까지, WWE 슈퍼스타와 관계자들의 무대 뒤 이야기를 담아낸 시리즈. WWE의 가장 화려한 쇼가 만들어지기까지 그들의 생생한 활약을 따라가 본다.', 'https://image.tmdb.org/t/p/w500/tvrJ1rIkKaAnQDTdEjrOTLnrCpJ.jpg', 'TV'),(570, NULL, 83880, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2019-04-05', '우리의 지구', 'Our Planet', '2019년 4월 Netflix에서 방영을 시작한 다큐멘터리. 우리 모두의 터전인 경이로운 지구를 만난다. 혁신적인 촬영 기술로 이제껏 본 적 없는 야생의 지역과 동물을 정밀하게 포착한 이 이 야심찬 시리즈는 전 세계 모든 대륙을 오가며 50개국에서 촬영됐다. 600명이 넘는 제작진이 3,500여 일에 걸쳐 촬영한 영상은 북극의 오지와 대양의 심해, 아프리카의 초원과 남미의 정글 등에 숨겨진 미지의 서식지를 다양하게 보여주는 데 중점을 둔다. 압도적인 스케일, 경이로운 영상미 그리고 전 인류를 향한 메시지로 우리 지구에 관한 가장 광대한 탐험을 만난다.', 'https://image.tmdb.org/t/p/w500/vMTjGkPLTu2WzRjiqrf1KbGEr1D.jpg', 'TV'),(571, NULL, 68708, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2016-11-11', '로마 제국', 'Roman Empire', '콤모두스, 카이사르, 칼리굴라. 로마 제국을 호령한, 하지만 피로 얼룩진 통치자들의 시대가 부활한다. 화려한 볼거리와 치밀한 고증을 결합한 역사 다큐멘터리 드라마.', 'https://image.tmdb.org/t/p/w500/mDAAywg5Kv1GiJaZfLjREf41G6n.jpg', 'TV'),(572, NULL, 247441, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2024-03-27', '테스터먼트: 모세 이야기', 'Testament: The Story of Moses', '왕자이자 선지자였던 모세의 놀라운 삶을 조명하는 다큐드라마 시리즈. 신학자와 역사가들의 통찰이 더해져 이해를 돕는다.', 'https://image.tmdb.org/t/p/w500/rRMIvf9OismdaKSuyUoo3mQa3iD.jpg', 'TV'),(573, NULL, 118043, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2021-02-17', '어멘드: 미국을 위한 투쟁', 'Amend: The Fight for America', '미국에서 자유와 평등을 위한 투쟁은 어떤 길을 지나왔는가? 때로는 잔인했으나 점진적으로 진화했다. 모두가 알아야 할 역사. 윌 스미스가 수정 헌법 제14조를 안내한다.', 'https://image.tmdb.org/t/p/w500/Ab5UBh94Kt6QObEwVUxWYmj2YSU.jpg', 'TV'),(574, NULL, 105177, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2020-07-01', '풀리지 않은 미스터리', 'Unsolved Mysteries', '미궁에 빠진 실제 사건들, 그 답을 찾아야 한다. 혼돈과 충격만을 남긴 실종과 살인 사건, 믿지 못할 초자연적 만남. 전설의 다큐멘터리 시리즈가 다시금 추적을 시작한다.', 'https://image.tmdb.org/t/p/w500/7P1E125fK5fTR6SSt1qJsLn6vG7.jpg', 'TV'),(575, NULL, 263089, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2024-09-25', '미스터 맥마흔', 'Mr. McMahon', '빈스 맥마흔이 경영권을 쥐고 있던 시절. WWE는 역사적인 성공을 거두기도 했지만, 처참한 위기도 겪었다. 여러 논란을 일으킨 당시 WWE를 다룬 다큐멘터리 시리즈.\n\n이 작품을 통해 크리스 스미스 감독(《타이거 킹》)과 총괄 프로듀서 빌 시먼스(《30 for 30》)는 스포츠 엔터테인먼트 업계에서 가장 수수께끼 같은 인물 중 하나에 대한 전모를 여과 없이 보여준다.', 'https://image.tmdb.org/t/p/w500/8NuoGhOXUJVKAobG7aCxf7RVXQd.jpg', 'TV'),(576, NULL, 74851, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2017-10-27', '기묘한 이야기의 궁금한 이야기', 'Beyond Stranger Things', '출연진과 제작진이 들려주는 《기묘한 이야기 2》의 모든 것. 구상, 제작 비화부터 각 인물의 캐릭터 해석까지, 기묘한 세계의 늪으로 초대한다. \"스포일러 나갑니다!\"', 'https://image.tmdb.org/t/p/w500/rHCFO8RJ3Hg6a8KjWAsvAsa38hp.jpg', 'TV'),(577, NULL, 100698, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2020-03-20', '타이거 킹', 'Tiger King', '사자와 호랑이, 온갖 별종들에 둘러싸인 남자. 타이거 킹이라 불린 희대의 말썽꾼을 중심으로, 걷잡을 수 없는 파국이 시작된다. 맹수 사육의 세계에서 일어난 충격 실화.', 'https://image.tmdb.org/t/p/w500/aCN4SyvMNJSQpLaI9LRraF4hKKb.jpg', 'TV'),(578, NULL, 76307, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2018-01-26', '검은돈', 'Dirty Money', '맹신하지 마라. 교묘하게 조작된 자동차부터 엄청나게 부풀려진 금리까지. 기업들의 탐욕과 부패는 먹이를 가리지 않는다. 당신들의 지갑도, 생명도 결코 안전하지 않다.', 'https://image.tmdb.org/t/p/w500/dmCSh0cOZvNnjhsGo9xP29LQLsj.jpg', 'TV'),(579, NULL, 272299, '2026-01-29 12:23:36', '2026-01-29 12:23:36', 'en', '2024-10-23', '조디악이다', 'This Is the Zodiac Speaking', '실제 범죄를 다룬 다큐멘터리 시리즈. 진실을 찾던 한 가족이 조디악 살인 사건의 유력 용의자에 관한 각종 단서와 함께 충격적인 이야기를 들려준다.', 'https://image.tmdb.org/t/p/w500/crvYcZTN7TTEa85nClY3JqL2F0O.jpg', 'TV'),(580, NULL, 300999, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2025-10-07', '트루 호러', 'True Haunting', '실감 나는 재연과 관련자들의 최근 인터뷰를 통해 초자연적인 사건을 섬뜩하게 그려낸 시리즈. 당시 상황을 직접 겪은 이들의 시선으로 이야기가 전개된다.', 'https://image.tmdb.org/t/p/w500/8XK4kBkP7QVIPnl6dFfdPSCICs6.jpg', 'TV'),(581, NULL, 245926, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2024-03-12', '터닝 포인트: 핵무기와 냉전', 'Turning Point: The Bomb and the Cold War', '냉전 시대를 광범위하게 조명한 다큐시리즈. 전 세계 저명인사와 관련 인물들이 직접 들려주는 증언과 설명을 통해 냉전과 그 여파에 대해 살펴본다.\n\n루미넌트 미디어(Luminant Media)와 브라이언 내픈버거 감독이 냉전에 관한 모든 것을 총망라한 다큐멘터리를 선보인다. 원자폭탄의 개발과 그 후 수십 년간 이어진 핵무기의 빠른 확산에서 시작해 소련의 붕괴와 블라디미르 푸틴의 부상, 러시아의 우크라이나 침공에 이르기까지 냉전의 역사를 추적한다.\n\n《터닝 포인트: 핵무기와 냉전》은 전 세계 7개국에서 진행된 100여 건의 인터뷰를 통해 냉전이 삶을 어떻게 변화시키고 세계 역사를 주도해 왔는가에 대해 매우 개인적인 이야기를 들려준다. 히로시마 원폭 생존자들의 삶과 우크라이나, 독일, 구 소비에트 공화국 일부 지역에서 광범위하게 촬영된 내용을 비롯해 우크라이나 대통령 볼로디미르 젤렌스키, 북대서양조약기구(NATO) 사무총장 옌스 스톨텐베르그, 전 CIA 국장 로버트 게이츠, 전 국무장관 콘돌리자 라이스 등 전현직 세계 지도자 7명의 인터뷰도 담았다. 또한 줄리어스 로젠버그와 에설 로젠버그의 아들, 베를린 장벽 붕괴를 도운 독일의 저명한 시위 지도자 등 냉전시대 주요 인물들의 이야기와 함께, 핵에 관련된 미국의 비밀 계획을 \'제도적 광기\'라고 비판한 반핵 운동가 대니얼 엘즈버그가 생전에 마지막으로 남긴 인터뷰도 길게 담았다. 총 9화로 구성된 이번 다큐시리즈는 수십 년간 이어진 미국과 소련의 갈등을 시사적인 사건을 중심으로 살펴보며 아직도 우리가 느끼는 냉전의 영향이 상당함을 분명하게 보여준다.', 'https://image.tmdb.org/t/p/w500/dxVStrF1zPtIbLlbcC1M2hZUnzE.jpg', 'TV'),(582, NULL, 69373, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2017-04-21', '세상을 구하는 사나이 빌 나이', 'Bill Nye Saves the World', '에미상을 차지하기까지 한 과학자 빌 나이가 각 분야 전문가와 유명 스타들을 실험실로 초대해 우리 생활 속에 숨겨진 과학 이슈들을 낱낱이 풀어헤친다.', 'https://image.tmdb.org/t/p/w500/vqfnOYrs0eYVd5VMWh9dg7w6nWz.jpg', 'TV'),(583, NULL, 226135, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2023-06-07', '아놀드', 'Arnold', '보디빌딩 챔피언부터 시작해 할리우드 아이콘을 거쳐 정치인이 되기까지, 아놀드 슈워제네거의 다각적인 삶과 커리어를 따라가는 내밀한 다큐시리즈.', 'https://image.tmdb.org/t/p/w500/o9KmWrG9rbFhB7jWW4vFHTmqv28.jpg', 'TV'),(584, NULL, 259709, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2024-08-21', '와이어트 어프와 카우보이 전쟁', 'Wyatt Earp and the Cowboy War', '한 시대를 뒤흔든 악명 높은 총격전을 현실감 넘치게 담아낸 다큐드라마. 와이어트 어프와 아이크 클랜턴의 전설적인 대결이 생생한 재연을 통해 실감 나게 펼쳐진다.', 'https://image.tmdb.org/t/p/w500/3J6MdyMKOb5bAEn0C6c3RtuqgT7.jpg', 'TV'),(585, NULL, 116986, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2021-01-20', '스파이크래프트', 'Spycraft', '개인, 집단, 넓게는 국가의 안위가 달린 첩보. 성패가 핵심인 만큼, 작전에 투입되는 기기에 끊임없는 투자와 개발이 이뤄져 왔다. 어찌 보면 스파이만큼 중요한 첩보 기기의 발전 역사를 세기의 사건이 기록된 실제 영상으로 다뤄본다.', 'https://image.tmdb.org/t/p/w500/3JJMgQ09UpZKzfsbjHatqhSmPJc.jpg', 'TV'),(586, NULL, 96129, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2019-12-18', '고양이는 건드리지 마라: 인터넷 킬러 사냥', 'Don\'t F**k with Cats: Hunting an Internet Killer', '온라인에 잔혹한 영상이 떠돌고, 일군의 네티즌이 행동에 나섰다. 과연 인터넷 탐정들은 범인을 찾아낼 수 있을까? 충격적인 사건의 해결 과정을 담은 다큐멘터리 시리즈.', 'https://image.tmdb.org/t/p/w500/Crc4XkhLddMTNJfj1iLca0w1Bb.jpg', 'TV'),(587, NULL, 155094, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2022-02-16', '지-니어스: 카니예 3부작', 'jeen-yuhs: A Kanye Trilogy', '라이징 슈퍼스타와 영화감독, 두 인생이 만났다. 20여 년에 걸쳐 카니예 웨스트의 커리어를 촬영한 내밀한 다큐시리즈.\n\n카니예 웨스트의 삶을 기록한 기념비적인 3부작 다큐멘터리 《jeen-yuhs: A Kanye Trilogy》. 클래런스 \'쿠디\' 시먼스와 치케 오자가 연출을 맡아 우리가 미처 몰랐던 카니예 웨스트의 모습을 내밀하게 포착했다. 돌파구를 찾던 무명 뮤지션 시절부터 세계적으로 유명한 글로벌 아티스트가 된 현재에 이르기까지, 카니예 웨스트의 진면목을 만나볼 수 있다.', 'https://image.tmdb.org/t/p/w500/wm0K7pnZSboFEBXG2Ds92KIXNve.jpg', 'TV'),(589, NULL, 137646, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2021-11-10', '애니멀', 'Animal', '세계에서 가장 위대한 생명체를 생생하게 담아낸 다큐멘터리 시리즈. 관찰을 통해 포착한 동물들의 가슴 따뜻한 순간부터 충격적인 모습까지, 지금껏 본적 없는 놀라운 동물의 생태가 펼쳐진다.', 'https://image.tmdb.org/t/p/w500/5owCH4C9PKr6gbQDTYVpHhnuwLt.jpg', 'TV'),(590, NULL, 102360, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2020-04-26', '익스플레인: 코로나바이러스를 해설하다', 'Coronavirus, Explained', '2020년, 세상이 변했다. 주범은 범유행 중인 코로나19. 정체가 무엇일까? 바이러스에 맞선 싸움부터 정신 건강을 돌보는 일까지, 코로나19 사태의 이모저모를 해설한다.', 'https://image.tmdb.org/t/p/w500/n8AhmFsGeyIricCMtbNUQrITF0w.jpg', 'TV'),(591, NULL, 85837, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2018-12-06', '러스트 밸리 브라더스', 'Rust Valley Restorers', '40년 동안 하나둘씩 모은 차가 어느새 400대, 오래된 자동차에 미친 마이크 홀의 리얼리티 쇼', 'https://image.tmdb.org/t/p/w500/iie281wQpFiaGq3KBCrN1Yhq3LG.jpg', 'TV'),(592, NULL, 76305, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2018-01-12', '필이 좋은 여행, 한입만!', 'Somebody Feed Phil', '《내 사랑 레이몬드》의 제작자 필 로즌솔이 맛있는 여행을 떠난다. 멕시코와 베트남, 태국 등에서 맛보는 최고의 현지 음식. 배고파서 행복하다, 더 먹을 수 있으니까!', 'https://image.tmdb.org/t/p/w500/x6kMGTs3YO8p9oumtYU2IHO2tvU.jpg', 'TV'),(593, NULL, 103506, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2020-05-27', '제프리 엡스타인: 괴물이 된 억만장자', 'Jeffrey Epstein: Filthy Rich', '억만장자 성범죄자, 제프리 엡스타인. 부와 권력으로 수많은 여성을 나락에 떨어트린 괴물의 민낯이 밝혀진다. 생존자들의 용기 있는 증언을 담아낸 다큐멘터리 시리즈.', 'https://image.tmdb.org/t/p/w500/l71LfocE8V4JmAJoVp95QMppAYK.jpg', 'TV'),(594, NULL, 78704, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2018-04-27', '로버트, 우리가 사랑한 케네디', 'Bobby Kennedy for President', '1960년대 \'보비 열풍\'은 어디에서 왔는가. 당시를 기록한 필름, 그 시대를 함께 한 인사들의 목소리를 통해 로버트 F. 케네디의 염원을 만난다. 그가 남긴 유산들과 함께.', 'https://image.tmdb.org/t/p/w500/rVEIAUhAbHZ1PAbSRQ9UiF3UYBP.jpg', 'TV'),(595, NULL, 125972, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2021-03-06', '디스 이즈 팝', 'This Is Pop', '전 세계의 사랑을 받았던 팝송들. 그 이면에 숨겨진 진짜 이야기들. 음악 축제와 오토튠, 보이 그룹 등이 팝 역사에 미친 영향들을 살펴본다. 팝 스타들의 인터뷰가 담긴 다큐멘터리 시리즈.', 'https://image.tmdb.org/t/p/w500/uVG8QtrKspTYGCJRKqFUa4Vyfgs.jpg', 'TV'),(596, NULL, 262955, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2024-10-09', '스타팅 5', 'Starting 5', '흥미진진한 스포츠 시리즈. 2023~24 NBA 시즌 동안 지미 버틀러, 앤서니 에드워즈, 르브론 제임스, 도만타스 사보니스, 제이슨 테이텀 등의 선수들이 펼치는 활약상을 조명한다.', 'https://image.tmdb.org/t/p/w500/nIE2dIemIGHHfbIPa9K3fum6wk.jpg', 'TV'),(598, NULL, 89557, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2019-06-07', '더 셰프 쇼', 'The Chef Show', '영화를 찍다가 요리에 푹 빠진 작가 겸 감독 존 패브로. 그가 유명 셰프 로이 최와 함께 요리 탐험을 떠난다. 쟁쟁한 셰프들과 스타들의 부엌을 훔쳐볼 절호의 기회라나!', 'https://image.tmdb.org/t/p/w500/l2jZr8zjlXXURKh4ybnlj1UgLQg.jpg', 'TV'),(599, NULL, 279942, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2025-08-19', '댈러스 카우보이스: 제리 존스와 황금기', 'America\'s Team: The Gambler and His Cowboys', '댈러스 카우보이스와 제리 존스가 NFL 역사에 끼친 영향을 탐구하는 시리즈. 미공개 자료 영상과 인터뷰가 그 이야기를 더욱 생생하게 전한다.', 'https://image.tmdb.org/t/p/w500/2LZegU8xUyhiWDJ4vXA03DjXtPU.jpg', 'TV'),(600, NULL, 62391, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2015-04-26', '셰프의 테이블', 'Chef\'s Table', '그들은 안주하지 않는다. 끝없이 노력하고 실험하며 전진한다. 그렇게 새로운 미식의 역사를 창조한다. 세계 최고의 셰프들을 만나는 시간. 에미상 후보에 오른 시리즈다.', 'https://image.tmdb.org/t/p/w500/ufV8rrtQ6NZvqSgrpvuVEkYR2n0.jpg', 'TV'),(601, NULL, 237458, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2023-11-14', '갱단 두목이 되는 법', 'How to Become a Mob Boss', '어두운 풍자로 가득한 비법 전수 시리즈. 역사상 가장 악명 높은 갱단 두목들의 흥망성쇠와 그들의 성공 비결을 파헤쳐 본다.', 'https://image.tmdb.org/t/p/w500/grG70j02LVi94JafITgjltujz4B.jpg', 'TV'),(603, NULL, 196122, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2022-04-06', '지미 새빌: 브리티시 호러 스토리', 'Jimmy Savile: A British Horror Story', '특이한 성격과 자선 활동으로 전 국민을 매료시킨 TV 스타 지미 새빌. 그러나 성범죄 혐의가 제기되면서, 그의 겉모습 뒤에 감춰져 있던 충격적인 실체가 만천하에 드러난다.', 'https://image.tmdb.org/t/p/w500/5mAHyr2W9nNufjx8BpInkSworcY.jpg', 'TV'),(604, NULL, 289123, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2025-05-14', '프레드와 로즈 웨스트: 브리티시 호러 스토리', 'Fred and Rose West: A British Horror Story', '영국 역사상 가장 많은 사람을 죽인 살인자 중 하나인 프레드 웨스트와 로즈 웨스트. 최근 발견된 경찰 측 녹취와 사건 관련자들의 증언을 통해 그들의 이야기가 밝혀진다.', 'https://image.tmdb.org/t/p/w500/gKUZ1brH9luG8LnlBMneQK5oQLP.jpg', 'TV'),(605, NULL, 108298, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2020-09-16', '챌린저: 마지막 비행', 'Challenger: The Final Flight', '1986년에 발사된 우주왕복선 챌린저가 참사를 당한다.  온 국민의 관심 속에 출발했으나 추락해 버린 꿈. 기술자와 관계자, 대원의 가족들이 그때 그 사고를 되짚는다.', 'https://image.tmdb.org/t/p/w500/1McwYPB2guUgxNA0BzhO23Gae31.jpg', 'TV'),(606, NULL, 72541, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2016-04-20', '지상 최악의 교도소에 가다', 'Inside the World\'s Toughest Prisons', '범죄의 종착지일까, 범죄의 심장부일까. 두 명의 저널리스트가 야만과 고통으로 얼룩진 교도소들을 체험한다. 높은 담장 안에는 재소자와 간수뿐, 안전망이란 없다!', 'https://image.tmdb.org/t/p/w500/kCj9WlSOoIZ6ucOpWNYTCIzrMk7.jpg', 'TV'),(607, NULL, 261649, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2024-09-12', '인투 더 파이어: 사라진 딸', 'Into the Fire: The Lost Daughter', '1989년, 입양 보낸 딸이 실종되는 사건이 발생한다. 이 사실을 알게 된 친모가 사건을 둘러싼 복잡한 미스터리를 풀어나가는데.', 'https://image.tmdb.org/t/p/w500/bELrkAbQ2JZlykfJbf2z0rwElVB.jpg', 'TV'),(608, NULL, 213611, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2024-11-20', '우리의 바다', 'Our Oceans', '지구 오대양의 수면 아래, 숨겨진 이야기들이 펼쳐진다. 경이로운 자연 다큐멘터리 시리즈에서 각 대양의 신비로운 세계를 탐험해 보자.', 'https://image.tmdb.org/t/p/w500/5S1xVcfCXPzBeAluiTWKGqwMmRz.jpg', 'TV'),(609, NULL, 70508, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2017-03-31', '다섯이 돌아왔다: 할리우드와 2차대전 이야기', 'Five Came Back', '제2차 세계대전을 담아내고자 참전도 마다 않은 할리우드의 신화적인 영화 감독 5인. 이들 다섯 감독의 이야기를 현대의 스타 영화 감독 다섯을 통해 들어본다.', 'https://image.tmdb.org/t/p/w500/ksO7o3tyD19MonyoysxHIXrbvrs.jpg', 'TV'),(610, NULL, 219819, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2023-02-14', '더 로맨틱스', 'The Romantics', '자료 영상과 유명 인사들과의 심층 인터뷰를 통해 발리우드의 거장 영화감독인 야시 초프라의 삶과 유산을 기리는 다큐 시리즈.', 'https://image.tmdb.org/t/p/w500/hOBiDTcHsZBqZYYTAuC9oSJUNKf.jpg', 'TV'),(611, NULL, 70177, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2017-02-10', '앱스트랙트: 디자인의 미학', 'Abstract: The Art of Design', '2017년 2월 Netflix에서 방영을 시작한 다큐멘터리. 디자이너의 또 다른 이름이라 할 수 있는 단어, 이노베이터. 일러스트레이션에서 자동차 디자인까지 예술과 디자인 분야에서 가장 뛰어나고 독창적인 8명의 디자이너들. 각각의 분야에서 혁신을 창출하고 우리의 일상을 그려가고 있는 위대한 디자이너들을 만나 우리의 일상 곳곳을 새로이 파고드는 디자인 세계를 짚어본다. 디자이너들의 머릿속에 들어있는 미래에 대한 단순한 청사진과 컴퓨터에서 나아가 디자인의 기술과 철학을 탐구한다. 지금 세계적 거장들의 머릿속으로 여행을 떠나보자.', 'https://image.tmdb.org/t/p/w500/xNlKtCGyFQSGC7HWnrXwd39teyI.jpg', 'TV'),(612, NULL, 235345, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2023-10-04', '베컴', 'Beckham', '어려운 환경에서 자라 세계적인 축구 스타가 되기까지. 혜성처럼 떠오른 데이비드 베컴의 미공개 영상들을 담은 다큐시리즈.\n\n《베컴》은 아카데미상 수상자 피셔 스티븐스(《파머》 《And We Go Green》 《더 코브: 슬픈 돌고래의 진실》)와 아카데미상, 에미상을 수상한 프로듀서 존 뱃섹(《One Day in September》 《서칭 포 슈가맨》 《윈터 온 파이어: 우크라이나의 자유 투쟁》)의 작품으로, 이제껏 공개되지 않았던 데이비드 베컴과 아내 빅토리아, 가족, 지인, 동료들의 모습을 담았다. 한 남자의 내밀한 초상이자 후기 근대 사회에 꽃핀 스포츠와 셀러브리티 문화의 연대기적 기록이라 할 수 있는 작품.', 'https://image.tmdb.org/t/p/w500/vmXhy8gR7EHu8j7OpQR9lf7tOdH.jpg', 'TV'),(613, NULL, 96557, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2020-01-22', '판데믹: 인플루엔자와의 전쟁', 'Pandemic: How to Prevent an Outbreak', '그들의 손에 인류의 존망이 달려있다. 치명적인 독감의 대유행을 막는 데 뛰어든 의료 종사자들. 세계 곳곳, 그들이 사투를 벌이는 현장을 찾아가는 다큐멘터리 시리즈.', 'https://image.tmdb.org/t/p/w500/8c4jVpK9ylt228ZP0wo6o3QoErO.jpg', 'TV'),(614, NULL, 114066, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2022-05-19', '애덤 코노버: 정부가 왜 이래', 'The G Word with Adam Conover', '좋든 싫든, 정부는 우리 삶에서 큰 역할을 하고 있다. 애덤 코노버가 정부 시스템의 성공과 실패, 그리고 우리가 이를 어떻게 바꿀 수 있는지를 탐구한다.', 'https://image.tmdb.org/t/p/w500/zKvnKGEafn7taeggype1ETeujQB.jpg', 'TV'),(615, NULL, 87832, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2019-04-26', '길 위의 셰프들', 'Street Food: Asia', '달콤한 설탕을 졸이며 쓰디쓴 삶을 견뎠다. 향신료를 한데 섞으며 흩어진 가족을 되찾았다. 길거리 음식에 담긴 숱한 사연. 그 맛을 찾아, 아시아 9개국 도시로 떠난다.', 'https://image.tmdb.org/t/p/w500/1MZWpfRCytagOnYQ0F8VH3R35O0.jpg', 'TV'),(616, NULL, 136323, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2021-12-06', '영화, 보기의 미학', 'Voir', '때론 가슴 뛰고, 때론 혼란스럽거나 새로운 시각을 갖게 되고. 영화 애호가들이 인생을 바꾼 영화에 대한 단상과 통찰을 공유한다.', 'https://image.tmdb.org/t/p/w500/hEHGlUQFVe4Wk11pVTGHzwFOyZL.jpg', 'TV'),(617, NULL, 81337, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2018-05-29', '나는 살인자다', 'I AM A KILLER', '만약 그날이 아니었다면, 그들의 미래는 바뀌었을까. 사형을 선고받은 1급 살인범들이 악몽의 그날을 증언한다. 선과 악, 죄와 벌을 되묻게 만드는 다큐멘터리 시리즈.', 'https://image.tmdb.org/t/p/w500/3O3WpVQms41mDZrC0O7tRqoSuut.jpg', 'TV'),(618, NULL, 74579, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2017-10-20', '엘 차포를 만난 날', 'The Day I Met El Chapo: The Kate del Castillo Story', '엘 차포 구스만. 땅굴을 파고 탈옥한 마약왕과 슈퍼스타 여배우가 비밀리에 만났다. 그 후 눈덩이처럼 불어난 흉흉한 소문들은 진실인가 음모인가? 그녀가 입을 열었다.', 'https://image.tmdb.org/t/p/w500/irj9rIimJl3aw9zTv1GFnbelFaQ.jpg', 'TV'),(619, NULL, 197248, '2026-01-29 12:23:37', '2026-01-29 12:23:37', 'en', '2022-04-20', '살인을 말하다: 존 웨인 게이시 테이프', 'Conversations with a Killer: The John Wayne Gacy Tapes', '그는 유력 인사들과 만찬을 즐겼다. 동시에 취약한 이들을 먹잇감 삼았다. 미소 짓는 얼굴 뒤에 소름 끼치는 어둠을 감추고 있었던 가학적인 연쇄 살인마의 초상.', 'https://image.tmdb.org/t/p/w500/pKEPLzjrBA06kgd4ItV150PsheW.jpg', 'TV');
